    % \footnote{$\tilde{N}$ is determined by the task to experience, consistent with the NAHT setting in~\cite{wang2025n}, while $N$ indicates a sufficiently large set of agents, agnostic to tasks, consistent to the viewpoint about modeling AHT with cooperative game theory in~\cite{wang2024open}.}
    $G_{\texttt{NAHT}}$ is isomorphic to $\mathbb{R}^{(2^{|\tilde{N}|} - 1) \times d}$, if we simply consider a finite state space such that $|\mathcal{S}|=d$. Note that the controlled agent set denoted as $\tilde{C}$ is a subset of $\tilde{N}$. Considering uncontrolled agents denoted as $\tilde{U} := \tilde{N} \backslash \tilde{C}$ is necessary for evaluating the controlled agents' policies. If we ignore the uncontrolled agents, the game space with a fixed state will be reduced to a subspace $W \subset \mathbb{R}^{(2^{|\tilde{C}|} - 1)}$, where coordinates not contributing to $\tilde{C}$ are always zeros. The effect of uncontrolled agents is totally ignored. This will induce a bias measured by the angle between two game vectors representing two scenarios. For example, $\theta$ is the angle between two game vectors such that $v_{s} \in W = \text{span}\{v_{\{1\}, s}^{1}\}$ and $w_{s} \in \text{span}\{v_{\{1\}, s}^{1}, v_{\{1,2\}, s}^{1}\} \backslash W$, as shown in Figure~\ref{fig:state-space-cooperative-game-case}. \textbf{As well as providing a visualization of NAHT, the main purpose of this model is for formalizing the use of Shapley value when solving NAHT. More specifically, this supports why coalitions up to $\tilde{N}$ must be considered during the NAHT process, when imposing axiomatic characterization in Section~\ref{sec:shapley-value-for-n-agent-ad-hoc-teamwork}.}


\section{Shapley Value for N-Agent Ad Hoc Teamwork}
\label{sec:shapley-value-for-n-agent-ad-hoc-teamwork}
    As described in Definition~\ref{def:ad-hoc-teamwork-in-cooperative-game}, a NAHT process can be represented by $G_{\texttt{NAHT}}=\oplus_{s \in \mathcal{S}} G(s)$, where each subspace $G(s)$ is generated by a set of basis games with a fixed state $s \in \mathcal{S}$, such as $\{v_{C,s}^{1} \ | \ \emptyset \neq C \subseteq \tilde{N} \}$. Therefore, we can uniquely describe a game $v_{s} \in DG(s)$ by the following formula: $v_{s} = \sum_{\emptyset \neq C \subseteq \tilde{N}} k_{C} v_{C, s}^{1}$, given a fixed state $s$. By Definition~\ref{def:game-set}, we denote $v_{C, s}^{z} = z v_{C, s}^{1}$, for any $z \in \mathbb{R}$, such that if $C \subseteq D$, $v_{C, s}^{z}(D) = z$, otherwise, $v_{C, s}^{z}(D) = 0$. 

    \begin{lemma}
    \label{lemm:subgame-transform}
        Given a fixed state $s \in {\cal S}$ each subgame $v_{s} \in G(s)$, it can be uniquely represented by $v_{s} = \sum_{\emptyset \neq C \subseteq \tilde{N}} \frac{k_{C}}{v_{s}(\tilde{N})} \cdot v_{C,s}^{v_{s}(\tilde{N})}$.
    \end{lemma}
    By Lemma~\ref{lemm:subgame-transform}, we can represent a subgame as follows: $v_{s} = \sum_{\emptyset \neq C \subseteq \tilde{N}} \frac{k_{C}}{v_{s}(\tilde{N})} \cdot v_{C,s}^{v_{s}(\tilde{N})}$. Imposing a linear operator $\phi: G(s) \rightarrow \mathbb{R}^{|\tilde{N}|}$ on the subgame $v_{s}$, we derive the following formula such that
    \begin{equation}
        \phi(v_{s}) = \phi \left( \sum_{\emptyset \neq C \subseteq \tilde{N}} \frac{k_{C}}{v_{s}(\tilde{N})} \cdot v_{C, s}^{v_{s}(\tilde{N})} \right).
    \label{eq:shapley-value-impose}
    \end{equation}
    By the Linearity axiom of $\phi$, we can transform Eq.~\eqref{eq:shapley-value-impose} as follows:
    \begin{equation}
        \phi(v_{s}) = \sum_{\emptyset \neq C \subseteq \tilde{N}} \frac{k_{C}}{v_{s}(\tilde{N})} \cdot \phi \left( v_{C, s}^{v_{s}(\tilde{N})} \right).
    \label{eq:shapley-value-linear}
    \end{equation}

    \subsection{Realization of Efficiency and Additivity Axioms in Markov Games}
    \label{subsec:links-to-rl}
            In this section, we will discuss how the Efficiency and Additivity axioms are realized in Markov games~\cite{littman1994markov}. For brevity, we rewrite $v_{C_{i}, s}^{v_{s}(\tilde{N})}(\tilde{N})$ as $V(C_{i}, s)$ and $v_{s}(\tilde{N})$ as $V(\tilde{N}, s)$, respectively, and $V(C_{1}, s) = V(C_{2}, s) = \cdots = V(C_{m}, s) = V(\tilde{N}, s)$, according to the definition of $v_{C,s}^{z}=z$. 

            In the context of Markov games, a subgame evaluating a group of agents $\tilde{N}$, $v_{s_{t}}(\tilde{N}) \in G(s)$, as a state value, can be defined by $\mathbb{E}_{\pi}[\sum_{\tau=0}^{T-t-1} \gamma^{\tau} R_{t+\tau} \ | \ s_{t}]$, following the convention of reinforcement learning~\cite{sutton1988learning}[Chap. 3], where $\pi = \times_{i \in \tilde{N}} \pi_{i}$ is a joint stationary policy of agents belonging to $\tilde{N}$ and $T$ is an episode length. By the Bellman equation with n-step returns, we have the follow-up expansion for $V(\tilde{N}, s_{t})$:
            \begin{equation}
                V(\tilde{N}, s_{t}) = \mathbb{E}_{\pi} \left[ \sum_{\tau=0}^{k-1} \gamma^{\tau} R_{t+\tau} + \gamma^{k} V(\tilde{N}, s_{t+k}) \ \mathlarger{\mathlarger{\mathlarger{\vert}}} \ s_{t} \right].
            \label{eq:game-value-expansion}
            \end{equation}
            Since $V(C_{1}, s) = V(C_{2}, s) = \cdots = V(C_{m}, s) = V(\tilde{N}, s)$, we have the following formula:
            \begin{equation}
                V(C_{i}, s_{t}) = \mathbb{E}_{\pi} \left[ \sum_{\tau=0}^{k-1} \gamma^{\tau} R_{t+\tau} + \gamma^{k} V(\tilde{N}, s_{t+k}) \ \mathlarger{\mathlarger{\mathlarger{\vert}}} \ s_{t} \right].
            \label{eq:game-value-expansion-coalition}
            \end{equation}
            Next, we will discuss how the value of $k$ is uniquely determined for each $V(C_{i}, s_{t})$ under a reasonable assumption. For conciseness, we denote the n-step return as $G_{t:t+n}$ such that
            \begin{equation*}
                G_{t:t+n} = \sum_{\tau=0}^{n-1} \gamma^{\tau} R_{t+\tau} + \gamma^{n} V(\tilde{N}, s_{t+n}).
            \end{equation*}

            \begin{assumption}
            \label{assm:correspondence-subgame-n-step-return}
                 For a state $s_{t} \in \mathcal{S}$, the basis games ordered in an ascending sequence of the coalition sizes, $(v_{C_{1}, s_{t}}^{v_{s_{t}}(\tilde{N})}(\tilde{N}), v_{C_{2}, s_{t}}^{v_{s_{t}}(\tilde{N})}(\tilde{N}), ..., v_{C_{m}, s_{t}}^{v_{s_{t}}(\tilde{N})}(\tilde{N}))$, are associated with a sequence of $n$-step returns, $\left( \mathbb{E}_{\pi}[G_{t:t+1} | s_{t}], \mathbb{E}_{\pi}[G_{t:t+2} | s_{t}], ..., \mathbb{E}_{\pi}[G_{t:t+n} | s_{t}] \right)$, such that $\mathbb{E}_{\pi}[G_{t:t+k} | s_{t}] = \sum_{i=p}^{q} v_{C_{i}, s_{t}}^{v_{s_{t}}(\tilde{N})}(\tilde{N})$, for $1 \leq k \leq n$, where $|C_{p-1}| < |C_{p}| = |C_{p+1}| = \cdots = |C_{q}| < |C_{q+1}|$ and $n < m$.
            \end{assumption}

            By Assumption~\ref{assm:correspondence-subgame-n-step-return} (\textcolor{black}{see Appendix~\ref{sec:explanation-of-assumptions} for more justification}), we can obtain the formula such that $v_{C_{i}, s_{t}}^{v_{s_{t}}(\tilde{N})}(\tilde{N}) = \frac{1}{q(i)} \cdot \mathbb{E}_{\pi}[G_{t:t+n(i)} | s_{t}]$ due to identical values across $v_{C_{i}, s_{t}}^{v_{s_{t}}(\tilde{N})}(\tilde{N})$, where $q(i)$ denotes the total number of coalitions that have the same size as $C_{i}$, and $n(i)$ denotes the index of the corresponding n-step return $G_{t:t+n(i)}$, with respect to coalition $C_{i}$. Note that coalitions with the identical sizes are assigned the same $n(i)$. By substitution, we rewrite Eq~\eqref{eq:game-value-expansion-coalition} as follows:
            \begin{equation}
                V(C_{i}, s_{t}) = \frac{1}{q(i)} \cdot \mathbb{E}_{\pi} \left[ \sum_{\tau=0}^{n(i)-1} \gamma^{\tau} R_{t+\tau} + \gamma^{n(i)} V(\tilde{N}, s_{t+n(i)}) \ \mathlarger{\mathlarger{\mathlarger{\vert}}} \ s_{t} \right].
            \label{aligned-coalition-value-to-expected-value}
            \end{equation}

             We now impose a multidimensional linear operator denoted by $\phi: G(s) \rightarrow \mathbb{R}^{|\tilde{N}|}$ on $V(C_{i}, s_{t})$. By linearity, it follows that:
            \begin{equation}
                \phi(V(C_{i}, s_{t})) = \frac{1}{q(i)} \cdot \mathbb{E}_{\pi} \left[ \sum_{\tau=0}^{n(i)-1} \gamma^{\tau} \phi(R_{t+\tau}) + \gamma^{n(i)} \phi(V(\tilde{N}, s_{t+n(i)})) \ \mathlarger{\mathlarger{\mathlarger{\vert}}} \ s_{t} \right].
            \label{eq:impose-shapley-value}
            \end{equation}

        \subsubsection{Efficiency Axiom}
            \begin{proposition}
            \label{prop:shapley-machine-reward}
                Given the condition that $\sum_{i=1}^{|\tilde{N}|} \phi_{i}(R_{t}) = R_{t}$, the payoff allocation defined on returns $R_{t}$, can be expressed as:
                \begin{equation}
                    \phi_{i}(R_{t}) := R_{t} - \sum_{j \neq i} \left( \ \phi_{j}(V(\tilde{N}, s_{t})) - \gamma \phi_{j}(V(\tilde{N}, s_{t+1})) \ \right).
                \label{eq:individual-reward-approximation}
                \end{equation}
            \end{proposition}
            Note that $\phi(R_{t+\tau})$ in Eq.~\eqref{eq:impose-shapley-value} has not yet been defined. For it to be well defined on the subspace $G(s)$, it is required to represent $\phi(R_{t+\tau})$ in the form of $\phi(V(\tilde{N}, s))$. To achieve this, we now define $\phi(R_{t})$ by introducing the Efficiency axiom. To satisfy the Efficiency axiom such that $\sum_{i=1}^{|\tilde{N}|} \phi_{i}(V(\tilde{N}, s_{t})) = V(\tilde{N}, s_{t})$, it is reasonable to assume that $\sum_{i=1}^{|\tilde{N}|} \phi_{i}(R_{t}) = R_{t}$. In other words, each agent's value expansion can be expressed independently with its own $\phi_{i}(R_{t})$, which will be detailed in the next subsection. Then, the resulting $\phi_{i}(R_{t})$ is detailed in Proposition~\ref{prop:shapley-machine-reward}.

        \subsubsection{Additivity Axiom}
            Recall that $v_{C_{i}, s}^{v_{s}(\tilde{N})}(\tilde{N})$ is denoted by $V(C_{i}, s)$, and $v_{s}(\tilde{N})$ is denoted by $V(\tilde{N}, s)$. Substituting Eq.~\eqref{eq:impose-shapley-value} into the Additivity axiom detailed in Eq.~\eqref{eq:shapley-value-linear} and presuming that there are $m$ n-step returns $G_{t:t+n}$ in total with no loss of generality, we obtain the following formula:
            \begin{equation}
                \phi(V(\tilde{N}, s_{t})) = \sum_{n=1}^{m} \frac{k_{C_{n}}}{V(\tilde{N}, s_{t})} \cdot \mathbb{E}_{\pi} \left[ \sum_{\tau=0}^{n-1} \gamma^{\tau} \phi(R_{t+\tau}) + \gamma^{n} \phi(V(\tilde{N}, s_{t+n})) \ \mathlarger{\mathlarger{\mathlarger{\vert}}} \ s_{t} \right].
            \end{equation}

            By linearity of the expectation operator, we obtain that:
            \begin{equation}
                \phi(V(\tilde{N}, s_{t})) = \mathbb{E}_{\pi} \left[ \sum_{n=1}^{m} \frac{k_{C_{n}}}{V(\tilde{N}, s_{t})} \cdot \sum_{\tau=0}^{n-1} \gamma^{\tau} \phi(R_{t+\tau}) + \gamma^{n} \phi(V(\tilde{N}, s_{t+n})) \ \mathlarger{\mathlarger{\mathlarger{\vert}}} \ s_{t} \right],
            \label{eq:shapley-value-expected-game}
            \end{equation}
            where the term in the $\mathbb{E}_{\pi}[\cdot]$ can be seen as a form of truncated $\lambda$-return~\cite{sutton1988learning}, with $\frac{k_{C_{n}}}{V(\tilde{N}, s)}$ as a weight, generated by a distribution parameterized by $\lambda$. We will specify this in the next section.

    \subsection{Implementation of Additivity, Efficiency and Symmetry in N-Agent Ad Hoc Teamwork}
    \label{subsec:implementation-in-marl}
        In this section, we will discuss how the conditions derived above can be implemented in NAHT, to fulfill the axiomatic characterization: Additivity, Efficiency and Symmetry. From the perspective of various composition of the axiomatic characterization, we propose a new algorithm named Shapley Machine, and interpret the existing algorithm, POAM~\cite{wang2025n}, in Section~\ref{subsec:summary-of-proposed-algorithms}.

        \subsubsection{Additivity Axiom}
            First, we will learn $\phi_{i}(V(\tilde{N}, s_{t}))$ directly for each controlled agent $i \in \tilde{C}$. For brevity, we can represent each $\phi_{i}(V(\tilde{N}, s_{t}))$ as $V_{i}(s_{t})$, and $\phi_{i}(R_{t})$ as $R_{t,i}$, respectively. By sampling trajectories under a joint policy $\pi$, we derive the following TD error $\delta_{t,i}$ for each agent $i$ such that
            \begin{equation}
                \delta_{t,i} = \sum_{n=1}^{m} \frac{k_{C_{n}}}{V(\tilde{N}, s)} \cdot \sum_{\tau=0}^{n-1} \left( \gamma^{\tau} R_{t+\tau,i} + \gamma^{n} V_{i}(s_{t+n}) \right) - V_{i}(s_{t}).
            \label{eq:td-error-general}
            \end{equation}
            % \begin{proposition}
            %     For the class of superadditive games with basis games $v^1_{C_n,s}$ it holds that $k_{C_n} \geq 0$.
            % \label{prop:positive-Kc}
            % \end{proposition}
            \begin{proposition}
                For the class of superadditive games formed by a set of basis games $\{v^1_{C,s} | \emptyset \neq C \subseteq \tilde{N} \}$, it holds that $k_{C} \geq 0$, for all $\emptyset \neq C \subseteq \tilde{N}$.
            \label{prop:positive-Kc}
            \end{proposition}
            For brevity, we denote $k_{C_{n}}' = \frac{k_{C_{n}}}{V(\tilde{N}, s)}$. Since in definition $V(\tilde{N}, s) > 0$, we can conclude that $k_{C_{n}}' > 0$ is a sufficient condition for $V(\tilde{N}, s)$ belonging to the superadditive game class, according to Proposition~\ref{prop:positive-Kc}. In other words, $k_{C_{n}}' > 0$ facilitates cooperation within a group of agents, following the relationship between superadditive games and cooperative MARL described in~\cite{wang2020shapley} (see Appendix~\ref{subsec:superadditive-game-cmarl} for details). 

            Following the convention of TD($\lambda$) in RL~\cite{sutton1988learning}, the values of $(k_{C_{1}}', k_{C_{2}}', \cdots, k_{C_{m}}')$ are generated using a geometric distribution $P_{\lambda}$ with the parameter $0 < \lambda < 1$, such that $k_{C_{i}}' = P_{\lambda}(i)$, resulting $((1-\lambda), (1-\lambda)\lambda, \cdots, (1-\lambda)\lambda^{m-1}, \lambda^{m})$. With this condition, Eq.~\eqref{eq:td-error-general} becomes the TD error of the well-known truncated TD($\lambda$) prediction, shortened as TTD($\lambda$)~\cite{cichosz1994truncating}. 

        \subsubsection{Efficiency Axiom}
            % This evidence justifies our assumption about reward shaping to derive the Efficiency axiom for dynamic scenarios.
            By substitution into Eq.~\eqref{eq:individual-reward-approximation}, the $R_{t+\tau,i}$ in Eq.~\eqref{eq:td-error-general} can be expressed as 
            \begin{equation}
                R_{t,i} = R_{t} - \sum_{j \neq i} \left( V_{j}(s_{t}) - \gamma V_{j}(s_{t+1}) \right).
            \label{eq:shape-rewards}
            \end{equation}
            % \subsubsection{Adaptation to More General Games}
            % \label{subsubsec:adaptation-to-more-general-games}
            % \textcolor{black}{Dynamic Bayesian Network factorization is not necessarily equivalent to coalition partitioning.}
            \begin{theorem}[\cite{oliehoek2016concise}]
            \label{thm:factored-dec-pomdp}
                Given an additively factored immediate reward function, for any timestep $t$ there is a factorization scheme of the Dynamic Bayesian Network (describing the transition function), such that the value of a finite-horizon factored Dec-POMDP is decomposable across agents.
            \end{theorem}
            $R_{t} = \sum_{i=1}^{|\tilde{N}|} \phi_{i}(R_{t})$ to derive the Efficiency axiom is also referred to as additively factored immediate reward function. Theorem~\ref{thm:factored-dec-pomdp} indicates that the Efficiency axiom such that $V(\tilde{N}, s_{t}) = \sum_{i=1}^{|\tilde{N}|} \phi_{i}(V(\tilde{N}, s_{t}))$ always exists in the context of Dec-POMDP~\cite{bernstein2002complexity}, given a factorization scheme of the transition function. However, we may optionally add one additional condition to implicitly facilitate searching for a factorization scheme during training such that
            \begin{equation}
                \sum_{i=1}^{|\tilde{N}|} \phi_{i}(V(\tilde{N}, s_{t})) = V(\tilde{N}, s_{t}).
            \label{eq:efficiency}
            \end{equation}

        \subsubsection{Symmetry Axiom}
            In practice, an agent is only able to receive an observation, in theory generated from a function of the state in Dec-POMDPs, a partially observable Markov game. This leads to that an agent is required to infer the state, as an individual hidden state, by the history of observations, e.g., using recurrent neural networks (RNNs), e.g. GRUs~\cite{chung2014empirical}. Owing to the feature of NAHT, each agent has to infer other agents' characteristics, which are used as inputs in addition to the individual hidden state, for both individual value functions and policies. This has been accomplished by the previous work, POAM~\citep{wang2025n}, a variant of IPPO~\citep{de2020independent} with an encoder-decoder module to infer other agents' characteristics, as a joint embedding vector. The value functions (critics) with the concatenation of individual hidden state and the joint embedding. Recall that the Symmetry axiom states that two agents who contribute equally to all coalitions excluding themselves should receive equal payoff allocations~\cite{chalkiadakis2011computational}[Chap. 2]. In the context of NAHT, this axiom applies when agents $i$ and $j$ share identical agent types. Since their types are the same, the two agents are exchangeable—from the perspective of any third agent, $i$ and $j$ are indistinguishable when included as teammates. Similarly, from each agent’s own perspective, the other agent appears identical within the teammate set. As a result, when interacting with the same teammates, agents $i$ and $j$ will exhibit identical behavioral trajectories, leading to identical inferred individual hidden states. Furthermore, since the joint embedding vector of teammates is computed based on their behavioral trajectories, and the teammates are fixed while $i$ and $j$ behave identically, both agents will infer the same joint teammate representation. Consequently, their expected payoff allocations, $V_i$ and $V_j$, are equal, thereby satisfying the Symmetry axiom.
            % The value functions (critics) with the concatenation of individual hidden state and the joint embedding, are invariant to the permutation of agents. Recall that $V_{i}(s_{t}) := \phi_{i}(V(\tilde{N}, s_{t}))$. The invariance of $V_{i}(s_{t})$ to permutation of agents means that $V(\tilde{N}, s_{t})$ is also invariant to permutation of agents (since $\phi$ is a linear transformation), which is known as a sufficient condition to satisfy the Symmetry axiom~\citep{dubey1975uniqueness}. 

    \subsection{Discussion on Proposed Algorithms and POAM}
    \label{subsec:summary-of-proposed-algorithms}
        To summarize, POAM uses TD($\lambda$) as the target values to update critics, and the global reward $R_{t}$ for each agent's policy optimization. Our algorithm named Shapley Machine is implemented based on POAM, by simply replacing the global reward $R_{t}$ with each agent's $R_{t,i}$ defined in Eq.~\eqref{eq:shape-rewards}, using TTD($\lambda$) with the horizon proportional to the number of possible agents, and adding Eq.~\eqref{eq:efficiency} as a regularization term.
        \begin{proposition}
        \label{prop:shapley-machine}
            Shapley Machine is an algorithm that fulfills Efficiency, Additivity and Symmetry, so it learns $V_{i}$ as Shapley values for dynamic scenarios.
        \end{proposition} 

        Note that Shapley Machine is forced to comply with Efficiency, Additivity and Symmetry during learning, so the resulting $V_{i}$ has to be Shapley value, as highlighted in Proposition~\ref{prop:shapley-machine}.
        \begin{remark}
            Banzhaf Machine is an algorithm which generates $V_{i}$, fulfilling Additivity and Symmetry.
        \end{remark}
        Following the principle of designing algorithms by complying with axiomatic characterization, we also propose an algorithm that satisfies conditions corresponding to Additivity and Symmetry. As the resulting $V_{i}$ is likely to be Banzhaf index~\cite{banzhaf1964weighted},~\footnote{It is known that Banzhaf index is not the only payoff allocation scheme that satisfies Additivity and Symmetry.} the algorithm is referred to as Banzhaf Machine.
        \begin{remark}
            POAM is a Banzhaf Machine that learns Banzhaf indices for dynamic scenarios. 
        \end{remark}
        According to the taxonomy of our theory, POAM also satisfies Additivity and Symmetry, so it is a Banzhaf Machine. However, it uses TD($\lambda$) rather than TTD($\lambda$), which means that it may overparameterize the value function in some situations where there are few agents \textcolor{black}{(justified by the MPE case in Figure~\ref{fig:shapley-machine-m})}. 
        % However, it is defined based on TD($\lambda$) rather than RTTD($\lambda$).


