    \def\thelemma{\ref{lemm:subgame-transform}}
        \begin{lemma}
            Given a fixed state $s \in {\cal S}$ each subgame $v_{s} \in G(s)$, it can be uniquely represented by $v_{s} = \sum_{\emptyset \neq C \subseteq \tilde{N}} \frac{k_{C}}{v_{s}(\tilde{N})} \cdot v_{C,s}^{v_{s}(\tilde{N})}$.
        \end{lemma}
        \begin{proof}
            We can represent each $k_{C}$ equivalently as $\frac{k_{C}v_{s}(\tilde{N})}{v_{s}(\tilde{N})}$. Substituting this term into the formula in Definition~\ref{def:game-set}, we can get the following formula:
            \begin{equation*}
                v_{s} = \sum_{\emptyset \neq C \subseteq \tilde{N}} \frac{k_{C}v_{s}(\tilde{N})}{v_{s}(\tilde{N})} \cdot v_{C, s}^{1}.
            \end{equation*}
            Since $v_{C, s}^{v_{s}(\tilde{N})} = v_{s}(\tilde{N}) v_{C, s}^{1}$ with $z = v_{s}(\tilde{N})$, we can have the following formula:
            \begin{equation*}
                v_{s} = \sum_{\emptyset \neq C \subseteq \tilde{N}} \frac{k_{C}}{v_{s}(\tilde{N})} \cdot v_{C, s}^{v_{s}(\tilde{N})}.
            \end{equation*}
        \end{proof}
