\begin{algorithm}[t]
\SetAlgoCaptionLayout{bottom}
\caption{Algorithm to estimate the expectation value of an observable $O$ with respect to the Lindblad map applied to a quantum state.}\label{algo: lindblad dynamics}
%  
\KwIn{Initial system state in $\rho_S$, $m$ single qubit sub-environment states, each initialized in the state defined in Eq.~\eqref{eq:sub-environment-thermal}, observable $O$, unitaries $\widetilde{U}_1$, \dots. $\widetilde{U}_m$, the total number of repetitions $\nu$, and precision $\eps'$, where the LCU decomposition of each $\widetilde{U}_j=\sum_{k}\alpha_{jk} W_{jk}$, such that $\forall j\in [1, m]$, $\norm{\widetilde{U}_j-e^{-i\Delta t\overline{H}_j}}\leq \eps'$.~\\~\\}
    \begin{itemize}
        \item[1.~] Initialize the system and the ancilla in the state $\rho_S$ and $\ket{+}$, respectively.
        \item[2.~] For iterations from $j = 0$ to $K-1$, where $K=m\nu$:
            \begin{itemize}
                \item[a.~] Set $\ell=j(\mathrm{mod~}m)+1$.
                \item[b.~] Initialize the environment register in state $\rho_{E_{\ell}}$.
                \item[c.~] Draw two i.i.d.~samples $X_j$ and $Y_j$ from the ensemble 
                    \begin{equation*}
                        \mathcal{D}_{\ell}=\left\{ W_{\ell k}, \frac{\alpha_{\ell k}}{\alpha^{(\ell)}}\right\},
                    \end{equation*} 
                    where $\alpha^{(\ell)} = \sum_k|\alpha_{\ell k}|$
                \item[d.~] Apply the controlled unitary $X_j^{(c)}$ and the anti-controlled unitary $Y_j^{(a)}$ to the system. 
                \item[e.~] Perform a partial trace over the environment register. 
            \end{itemize}
      \item [3.~]  Measure the joint ancilla and system state on the observable $(\sigma^x \otimes O)$ and record the measurement outcome as $\mu_i$.
      \item [4.~] Repeat Steps 1 to 3 a total of $T$ times.  
      \item [5.~] Compute the final estimate $\mu$ as:
    \begin{equation*}
        \mu = \dfrac{\zeta^2}{T}\sum_{j=1}^{T} \mu_j,
    \end{equation*}
      where $\zeta = \prod_{j=1}^K \alpha^{(j)}$.
      \end{itemize}
  \KwOut{Estimated expectation value $\mu$}  
\end{algorithm} 
