We consider that the interaction Hamiltonian corresponding to the $j$-${\mathrm{th}}$ collision (between the system and $j$-${\mathrm{th}}$ sub-environment)  $H_{I_j}$ can also be expressed as a linear combination of some $L_{I_j}$ Pauli operators. For instance, we can express it in terms of the Lindbladian jump operators as 
\begin{equation*}
H_{I_j} = \left(A_j \otimes \sigma^{+} + A_j^\dag \otimes \sigma^{-}\right),    
\end{equation*}
where $\sigma^{\pm}=(\sigma^x\pm i\sigma^y)/2$ are the raising and lowering operators respectively. We assume $\beta_{I_j}$ denotes the total weight of the coefficients in the description of $H_{I_j}$ and that this Hamiltonian has $L_{I_j}$ terms. Note that in some cases, the individual jump operator $A_j$ may itself be unitary~\cite{pocrnic2023quantum}. Overall, the total Hamiltonian corresponding to the $j$-${\mathrm{th}}$ collision is given by:
\begin{equation}
    \label{eq: collision hamiltonian, Lindbladian}
    \overline{H}_j =  \dfrac{1}{\beta_j}\left(\dfrac{1}{m} H_S +  H_{E_j} + \lambda H_{I_j}\right),
\end{equation}
where $\beta_j\leq \beta_S/m+\lambda\beta_{I_j}+\beta{E_j}$, and $\lambda=1/\sqrt{\Delta t}$. Hence, $\overline{H}_j$ also can be expressed as a linear combination of $L_S+L_{I_j}+1$ Pauli operators with total weight at most $\beta_j$.

Let us now discuss the choice of $\Delta t$ and $K$ for a $K$-collision map to be close (in induced $1$-norm) to $e^{\mathcal{L}t}[.]$. The collisions between the system and the $m$ sub-environments occur one by one in a fixed order ($E_1$, $E_2$, $\ldots$, $E_{m}$). Now, to simulate the Lindblad dynamics for a total evolution time of $t$, this sequence is repeated $\nu$ times, with each collision occurring for a time interval $\Delta t = t/\nu$. Thus, in all, there are $K=m\times \nu$ collisions, making it an $(m,\nu)$-collision map. 

As before, the interaction of $j$-${\mathrm{th}}$ sub-environment with the system is given by
$$
    U_j = e^{-i\beta_j \overline{H}_j \Delta t},
$$
and, from Definition \ref{def: collision map}, the $j$-th collision map is
\begin{equation}
    \Phi_j[.] = \text{Tr}_{E_j} \left[ U_j \left(. \otimes \rho_{E_j}\right) U_j^{\dagger} \right].
\end{equation}
The $(m,\nu)$-collision map is defined as follows:

\begin{restatable}[$(m,\nu)$-collision map]{definition}{}
\label{def: m, nu-collision map}
Let $\Phi_1$ to $\Phi_{m}$ be the collision maps as defined in Definition \ref{def: collision map}. Then a $(m, \nu)$-collision map, $\mathcal{M}_{m, \nu}$, is defined as the application of these maps composed $\nu$ times as follows:
    \begin{align}
        \mathcal{M}_{m, \nu}[.] \equiv  \left( \bigcirc_{j=1}^{m} \Phi_j\left[.\right] \right)^{\circ \nu}.        
    \end{align}    
\end{restatable}
\noindent
The value of $\nu$, i.e., the number of times the sequence of $m$ collisions should be repeated so that a $(m,\nu)$-collision map approximates $e^{\mathcal{L}t}$ up to an additive accuracy $\varepsilon$ was found in Ref.~\cite{pocrnic2023quantum}. For this, let us define
\begin{equation}
\label{eq:Gamma}
\Gamma =  \dfrac{\|\mathcal{L}\|^2_{1\to 1}}{m}+\left[\max_{\ell\in [1,m]}\left(\beta_S, \beta_{I_{\ell}}, \beta_{E_{\ell}}\right)\right]^4, 
\end{equation}
where $\|\mathcal{L}\|_{1\to 1}$ is the induced 1-norm of $\mathcal{L}[.]$. Now, we restate the result of \cite{pocrnic2023quantum} here:
\begin{lemma}[Corollary 2.1 of \cite{pocrnic2023quantum}]
\label{lemma: accuracy of collision model (Wiebe)}
For $\eps\in (0,1)$, a $(m, \nu)$-collision map as defined in Definition \ref{def: m, nu-collision map}, with interaction time $\Delta t = t/\nu$,
\begin{align}
    \nu \geq O \bigg( \frac{t^2 m}{\eps} \Gamma\bigg),
\end{align}
and $\lambda \rightarrow \frac{1}{\sqrt{\Delta t}}$ satisfies  
\begin{equation}    
    \norm{e^{\mathcal{L}t} - \mathcal{M}_{m, \nu}[.]}_{1 \to 1} \leq \eps.
\end{equation}
\end{lemma}
%
\noindent
This demonstrates that the $(m, \nu)$-collision map $\mathcal{M}_{m, \nu}[.]$ provides an accurate approximation of Lindbladian dynamics, provided $\nu$ is as stated in Lemma \ref{lemma: accuracy of collision model (Wiebe)}.  We use Hamiltonian simulation by SA-LCU and Algorithm \ref{algo: lindblad dynamics} to achieve this.

We intend to implement the circuit shown in Fig.~\ref{fig: Lindbladian circuit}. Each sequence of unitaries $Q_i$ corresponds to $m$ collisions between the system and each single-qubit sub-environment $E_1$ through $E_m$. As this is repeated $\nu$ times, there are overall $K=m\nu$ collisions. Since each block $Q_i$ corresponds to collisions with the same set of sub-environments, we do not have $K$ distinct collisions with distinct sub-environments, but rather $\nu$ blocks of $m$-collisions between the system and the $m$ sub-environments. So, to implement the circuit in Fig.~\ref{fig: Lindbladian circuit}, we slightly modify Algorithm~\ref{algo: collision model}. 

We rewrite the $(m,\nu)$-collision map as
\begin{equation}
\label{eq:m,nu map rewritten as K-collision map}
    \mathcal{M}_{m, \nu}[.] =  \bigcirc_{j=0}^{K-1} \Phi_{j(\mathrm{mod~}m)+1} \left[.\right], 
\end{equation}
where $K=m\nu$. The right-hand side of Eq.~\eqref{eq:m,nu map rewritten as K-collision map} is simply a $\Phi_j[.]$ map, composed $K$ times, where the cyclic order of the $\nu$ repetitions is respected. Thus, the problem of simulating Lindbladian dynamics implies implementing a specific $K$-collision map. Just as in Sec.~\ref{subsec:K-collision-approx}, this map can be implemented using a number of near-term Hamiltonian simulation algorithms. In our case, this change is reflected in Step 2a. of Algorithm~\ref{algo: lindblad dynamics}. For the $j$-${\mathrm{th}}$ iteration in Step 2 of Algorithm \ref{algo: collision model}, the $\Phi_{\ell}[.]$ map is implemented, where $\ell=j(\mathrm{mod~}m)+1$, i.e.\ it implements a collision between the system and the single qubit environment $E_{\ell}$. Overall, the correctness of Algorithm~\ref{algo: lindblad dynamics} is similar to Theorem \ref{thm: Algorithm 1 proof}. Formally, we state the results via the following theorem: 
\begin{restatable}[]{theorem}{}
\label{thm: collision map to lindbladian}
Let us consider an observable $O$, an $n$-qubit system prepared in the initial state $\rho_S$, and $m$ single-qubit sub-environments with each initialized in the single-qubit thermal state defined in Eq.~\eqref{eq:sub-environment-thermal}. Let $\eps, \delta \in (0,1)$ and $K=m\nu$, where
\begin{equation}
    \nu = \bigO \left( \frac{t^2 m\norm{O}\Gamma}{\eps}  \right).
    \label{eq: nu value in theorem}
\end{equation}
Then, for $\eps'=\eps/(12K\|O\|)$, Algorithm~\ref{algo: lindblad dynamics} outputs an estimate $\mu$ with a probability of at least $1-\delta$, such that:
\begin{equation}
    \left| \mu - \Tr\left[ O e^{\mathcal{L}t}[\rho_S] \right] \right| \leq \eps,
\end{equation} 
using $T$ runs of the circuit shown in Figure~\ref{fig: Lindbladian circuit},  
where 
\begin{equation}
\label{eq: number of samples}
       T = \bigO\left( \dfrac{\norm{O}^2\log(1/\delta)}{\eps^2}\right).
\end{equation}
Moreover, the circuit depth of each run is
\begin{equation}
\label{eq:circuit-depth-lindblad-single-ancilla}
 \tau_d=\widetilde{\bigO}\left(\dfrac{m^3 t^3 \norm{O}}{\varepsilon}\Gamma \beta^2_{\max}\right),   
\end{equation}
where 
\begin{equation}
\label{eq:beta-max}
    \beta_{\max}=\max_{\ell\in [1, m]} \left(\beta_{I_{\ell}},~ \sqrt{\frac{t}{m^2\nu}}\beta_S,~ \beta_{E_\ell}\sqrt{\frac{t}{\nu}}\right).
\end{equation}
\end{restatable}
\begin{proof}
First, from the proof of Theorem \ref{thm: Algorithm 1 proof}, we know that for precision $\eps'=\eps/(12\|O\|K)$ and $\nu$ as chosen in the statement of the Theorem, Algorithm~\ref{algo: lindblad dynamics} outputs $\mu$ such that,
$$
\left| \mu - \Tr\left[ O~ \mathcal{M}_{m, \nu}[\rho_S] \right] \right| \leq \frac{\eps}{2},
$$   
with probability at least $(1-\delta)$. This requires 
$$
T=\bigO\left(\dfrac{\|O\|^2}{\eps^2}\log(1/\delta)\right),
$$
repetitions of the circuit in Fig.~\ref{fig: Lindbladian circuit}. Furthermore, from Lemma~\ref{lemma: accuracy of collision model (Wiebe)}, we know that our choice of $\nu$ ensures 
$$
        \left\| e^{t \mathcal{L}} - \mathcal{M}_{m, \nu}[.] \right\|_{1 \to 1} \leq \dfrac{\eps}{2\norm{O}}.
$$
For any valid initial state of the system, $\rho_S$, we have from the definition of induced-1 norm:
    \begin{equation}
        \left\| e^{t \mathcal{L}}[\rho_S] - \mathcal{M}_{m, \nu}[\rho_S] \right\|_1 \leq \dfrac{\eps}{2\norm{O}}.
    \end{equation}   
Using the tracial version of H\"{o}lder's inequality  (Lemma \ref{thm:holder}) we obtain
    \begin{equation}\label{eq: distance lindbladian-collision map}
        \left| \Tr\left[ O e^{t \mathcal{L}}[\rho_S] \right] - \Tr\left[ O \mathcal{M}_{m, \nu}[\rho_S] \right] \right| \leq \dfrac{\eps}{2}.
    \end{equation}
Then, the triangle inequality gives us
\begin{align}
        \bigg| \mu - &\Tr\left[ O e^{t \mathcal{L}}[\rho_S] \right] \bigg| 
        \nonumber \\&\leq \left| \mu - \Tr\left[ O \mathcal{M}_{m, \nu}[\rho_S] \right] \right|\nonumber \\
        &\quad + \left| \Tr\left[ O \mathcal{M}_{m, \nu}[\rho_S] \right] - \Tr\left[ O e^{t \mathcal{L}}[\rho_S] \right] \right| \nonumber \\
        &\leq \frac{\eps}{2} + \frac{\eps}{2} = \eps.
    \end{align}


