    \subsection{Scattering Distance Measurement}
    SAR images are quite sensitive to natural structures, especially structures like dihedrals and trihedrals, which easily form strong scattering points due to their geometric stability. These points exhibit scale and resolution invariance~\cite{qin2024scattering,zhang2025cross}, resulting in topological structures that reveal correlations between targets across different resolutions. As shown in Fig.~\ref{fig:structures}, targets of the same category often display similar topological patterns (e.g., aircraft targets typically exhibit a cross-shaped structure). Quantifying these structural similarities can facilitate the association of targets at varying resolutions.

    Given a SAR target image $I_{i}$, the distribution of its strong scattering points is represented as:
    ${P_i}= \left\{{{x_n},{y_n},{a_n}}\right\}_{n = 1}^{N}$. $(x_{n},y_{n})$ and $a_{n}$ respectively represent the spatial coordinates and intensities of scattering points in the image. 
    Similarly, the scattering point set of another SAR target $I_{j}$ can be expressed as ${Q_j}= \left\{{{x_m},{y_m},{a_m}}\right\}_{m = 1}^{M}$. Considering the sparsity and uneven distribution of scattering points, traditional distance measurement methods cannot effectively quantify such distribution differences. 
    In contrast, based on optimal transport theory, Earth Mover's Distance (EMD)~\cite{emd} constructs the distribution difference between point sets $P_{i}$ and $Q_{j}$ as the minimum transportation cost from distribution $P_{i}$ to $Q_{j}$. 
    EMD is robust to variations in the size, distribution, and domain of the scattering point sets. 
    It can effectively measure the global and local differences between sparse scattering point sets under different resolutions and scales. The calculation method for scattering structure distance
    measurement is shown in Alg.~\ref{ag1}.

    \begin{algorithm}
        \caption{Scattering Structure Distance.}
        \label{ag1}
        \begin{algorithmic}
            [1] \Statex \textbf{Input:} Region of interest $I_{0}$ and $I_{1}$. \Statex
            \textbf{Output:} Scattering structure distance $d_{ST}$. 
            \State {Apply Gaussian smoothing} to $I_{0}$ and $I_{1}$; 
            \State {Detect local maxima in $I_{0}$ and $I_{1}$ as scatter point sets:}
            $P = \{(x_{n}, y_{n}, a_{n})\}_{n=1}^{N}$, $Q = \{(x_{m}, y_{m}, a_{m}
            )\}_{m=1}^{M}$. Retain the top scatter points based on intensity $a$;
            \State {Compute the normalized weights for $P$ and $Q$:} $w_{n}= a_{n}/{\sum_{n=1}^{N}a_{n}}$,
            $w_{m}= a_{m}/{\sum_{m=1}^{M}a_{m}}$; 
            \State {Compute the scattering structure distance $d_{ST}$ between $P$ and $Q$ by EMD:}
            \[
                d_{ST}(P, Q) = \min \sum_{n=1}^{N}\sum_{m=1}^{M}f_{n,m}\cdot \sqrt{(x_{n}- x_{m})^{2}+ (y_{n}- y_{m})^{2}};
            \]
            \State {Constraints:}
            \[
                f_{n,m}\geq 0, \quad\sum_{n=1}^{N}\sum_{m=1}^{M}f_{n,m} = 1,
            \]
            \[
                \sum_{m=1}^{M}f_{n,m}= w_{n}, \quad \sum_{n=1}^{N}f_{n,m}= w_{m};
            \]
            \State {Solve the linear programming problem~\cite{sinkhorn} to compute $d_{ST}$:}
            \[
                d_{ST}= \frac{\sum_{n=1}^{N}\sum_{m=1}^{M}f_{n,m}\cdot \sqrt{(x_{n}- x_{m})^{2}+ (y_{n}- y_{m})^{2}}}{\sum_{n=1}^{N}\sum_{m=1}^{M}f_{n,m}}
                .
            \]
        \end{algorithmic}
    \end{algorithm}

