\section{Dynamic Graph Decomposition}\label{J3 Section method}
%
\par Problem \eqref{eq.General} is generic and can be tailored to diverse contexts. In this section, we refine it by specifying the fitting error loss function, along with the constraints on the latent adjacency matrices in $\bbA$ and their temporal signatures in $\bbC$. We also define functions that promote the desired relationships among the latent adjacency matrices $\bbA$ and between the signals $\uvbX$, the adjacency matrices $\bbA$, and the temporal signatures in $\bbC$.
\par\smallskip\noindent\textbf{Fitting error.} For the fitting function, we consider a least-squares (LS) cost
\begin{equation}\label{eq.fittingterm_LS}
\ell(\uvbA,\uvbM,\bbA,\bbC)=||\uvbM\circ(\uvbA-\sum_{r=1}^R\bbA_r\diamond\bbc_r)||_F^2,
\end{equation}
that measures how well the latent graphs predict observed topological evolution. The norm in \eqref{eq.fittingterm_LS} can be adjusted to incorporate prior information about the observation errors. For example, the $\ell_1$ norm would be well-motivated if errors were sparse and independent across links. 

\par\smallskip\noindent\textbf{Constraint sets.} We want to estimate latent graphs that are undirected, have positive weights and do not contain self-loops. As a result, we consider $\ccalS_A = \{\bbS \in \reals^{N \times N}: \, \tr(\bbS) = 0,\, \bbS=\bbS^{\top}, \, [\bbS]_{ij} \geq 0 \, \forall \,(ij), \}$, representing non-negative symmetric $N\times N$ matrices with zero trace. For the temporal signatures, we consider $\ccalS_C=\{\bbs \in \reals^{T}:\,[\bbs]_i\geq 0 \;\forall\, i\}$. Positive weights in both $\bbA_r$ and $\bbc_r$ aid in interpretation, especially when it comes to comparing different time signatures. They also further restrict the degrees of freedom, rendering Problem \eqref{eq.General} more tractable.%Second, it allows us to view Problem \eqref{eq.General} in terms of a Non-Negative Matrix Factorization problem, which is a pre-requisite for the identifiability of the $\bbA_r$s and $\bbc_r$s.
\smallskip
\par\noindent\textbf{Sparsity of latent graphs.} We consider the latent graphs to be sparse. We impose sparsity on each adjacency matrix via $\pi_A(\bbA_r)=||\bbA_r||_1$. For $\bbA_r\in\ccalS_A$, this means $\pi_A(\bbA_r) = \mathbf{1}_N^{\top}\bbA_r\mathbf{1}_N$, where $\bbone_N$ is the column vector of $N$ ones.
\smallskip
\par\noindent\textbf{Signal smoothness.} We assume the graph signals are smooth on the (unobserved) graph \cite{dong2016learning,kalofolias2017learning}. Signal smoothness, which implies that nodes connected by edges have similar values, has been commonly used as a prior for identifying topology and performing inference over graphs \cite{mateos_connecting_2019}. To be more specific, we assume the signals at time $t$, $\bbX_t$, to be smooth over the approximated topology at the same time, given by $\sum_{r=1}^R[\bbC]_{t,r}\bbA_r$. A graph signal is smooth if nodes that share edges have similar signal values. Consider the matrix $\bbZ_t\in\mathbb{R}^{N\times N}$ with its $(ij)$-th element $[\bbZ_t]_{ij}=||[\bbX_t]_{i,:}-[\bbX_t]_{j,:}||_2^2$, measuring the squared $\ell_2$ norm between the signals $[\bbX_t]_{i,:}$ and $[\bbX_t]_{j,:}$ at nodes $i$ and $j$ at time $t$. The smoothness of the graph signal $\bbX_t$ over the recovered model-driven topology is given by the quadratic variation $\QV(\bbX_t)=\frac{1}{2}\tr(\uvbA_{:,:,t}\bbZ_t)$ \cite{kalofolias2017learning}. The signal-incorporating prior $g()$ is the sum of the signal smoothness function for each time instant, and it is calculated as
%\red{The function not only depends on $\uvbX,\bbA$, but also on $\bbC$. Change it here and in \eqref{eq.General}} 
\begin{align}\label{prior smoothness}
\begin{split}
g(\uvbX,\bbA,\bbC)&=\sum_{t=1}^T\frac{1}{2}\tr(\bbA_{:,:,t}\bbZ_t)=\sum_{t=1}^T\sum_{r=1}^R[\bbC]_{t,r}\frac{\tr(\bbA_r\bbZ_t)}{2}.
    \end{split}
\end{align}
This promotes the creation of new links from the signals in $\uvbX$ that are smooth in the original temporal network when portions of $\uvbA$ are not observed due to the mask. Finally, notice that we do not impose temporal smoothness. However, our model can accommodate it by a straightforward modification of the cost function in \eqref{prior smoothness}.
\smallskip
\par\noindent\textbf{Non-overlapping support.} We desire that the supports of the different latent graphs do not overlap so that each component uniquely contributes to the structural evolution and provides distinct insights. One way to promote this non-overlapping support is to penalize the $\bbA_r$s that share many common edges. This is achieved by imposing a regularizer on the latent adjacency matrices through the function
\begin{align}
h(\bbA)=\sum_{r=1}^R\sum_{\substack{\bar{r}=1 \ \bar{r}\neq r}}^R\tr(\bbA_r^{\top}\bbA_{\bar{r}}),
\end{align}
which promotes orthogonality among the latent adjacency matrices. The lowest possible value of $h(\bbA)$ is zero, which is achieved when no edge is shared among the adjacency matrices.
\smallskip
\par\noindent\textbf{Avoiding trivial solutions.} The formulation in \eqref{eq.General} can generate trivial solutions for some of the variables. More specifically, suppose we have a mask $\uvbM$ that hides all the information across an edge for all $t$, i.e., $[\uvbM_{:,:,t}]_{ij}=[\uvbM_{:,:,t}]_{ji}=0~\forall~t$. This leads to a trivial solution for the corresponding variables because of the dependence only on the functions $g()$ and $h()$. One way to tackle this is to force each node at every time instant to have a positive degree $\zeta>0$. This is expressed through the constraint
\begin{align}\label{constraint for nontrivial}
\Big(\sum_{r=1}^R [\bbC]_{t,r}\bbA_r\Big)\mathbf{1}_N \geq \zeta \mathbf{1}_N.
\end{align}
We extend this constraint for all time instants as
\begin{align}
\bbA[\bbC^{\top}\otimes\mathbf{1}_N]\geq \zeta\mathbf{1}_{N\times T},
\end{align}
where we recall that $\bbA=[\bbA_1,\ldots,\bbA_R]$. This implies that each node in the reconstructed topology at time $t$ has a degree of at least $\zeta$.
\smallskip
\par\noindent\textbf{Smooth temporal signatures.} We consider each temporal signature $\bbc_r$ to change slowly over time. This helps prevent overfitting to the observed topology $\uvbM\circ\uvbA$, especially when fewer observations are present. A gradual change in the temporal factor leads to smaller changes in the latent adjacency matrices.
%Consider we observe the edge between nodes $i$ and $j$ both at times $t$ and $t+1$ with the same edge weight, i.e., $A_{ij,t}=A_{ij,t+1}>0$. If the values of $\bbc_r$ vary by a large amount between these consecutive time instances, estimation of the corresponding latent adjacency matrices $\bbA_r$s will all be affected.
A gradual change in the temporal signature also helps in predicting an edge if it is not observed over an interval of time, given the true structural evolution is slow. We use  the squared Frobenius norm for the matrix formed by the temporal difference of the elements of each $\bbc_r$, i.e,
%
\begin{align}
\begin{split}
\pi_C(\bbC)=||\bbD\bbC||_F^2=&\sum_{r=1}^R\sum_{t=2}^T([\bbC]_{t,r}-[\bbC]_{t-1,r})^2\\
\end{split}
\end{align}
%
where $\bbD$ is the $T\!\times\!(T\!-\!1\!)$ temporal difference matrix. Additionally, we consider an extra cost function for $\bbC$, namely the squared Frobenius norm. These functions are reasonable from a practical point of view and aid in the convergence analysis of the optimization as we shall elaborate in Section \ref{J3 Section Analysis}.
\par With all these in place, the optimization in \eqref{eq.General} can now be written as
\begin{align}\label{Opt prob basic}
    \begin{split} &\underset{\{\bbA_r\},\{\bbc_r\}}{\text{minimize}}~~f(\bbA,\bbC)\!=\!\frac{1}{2}\Big\|\uvbM\circ(\uvbA-\sum_{r=1}^R\bbA_r\diamond\bbc_r)\Big\|_F^2\!\!\\&+\gamma\!\sum_{r=1}^R\mathbf{1}_N^{\top}\bbA_r\mathbf{1}\! +\!\delta\sum_{t=1}^T\sum_{r=1}^R[\bbC]_{t,r}\frac{\tr(\bbA_r\bbZ_t)}{2}\!+\! \mu||\bbD\bbC||_F^2\\&+\!\!\beta\sum_{r=1}^R\sum_{\bar{r}=1,\bar{r}\neq r}^R\tr(\bbA_r^{\top}\bbA_{\bar{r}})+\frac{\rho}{2}||\bbC||_F^2\\
    &\text{subject to}\\&\bbA_r\in\ccalS_A = \{\bbA_r:\bbA_r \geq \bbzero_{N\times N}, \tr(\bbA_r) = 0 ,\bbA_r=\bbA_r^{\top}\},
\\&\bbc_r\in\ccalS_C=\{\bbc_r:\bbc_r\geq\mathbf{0}_{T}\},\\&[\bbA_1,\ldots,\bbA_R][\bbC^{\top}\otimes\mathbf{1}_N]\geq \zeta\mathbf{1}_{N\times T},
    \end{split}
\end{align}
where $[\gamma,\delta,\beta,\mu, \rho]^{\top}$ denote the hyper-parameters.
\begin{remark}
Problem \eqref{Opt prob basic} is a particular instance of the more general Problem \eqref{eq.General}. The constraints and regularizers can be modified to model diverse scenarios. For example, low-rank latent factors can be promoted via the use of nuclear norms. Additionally, a switching dynamic network can be captured by penalizing the $\ell_1$ norm of each column in $\bbC$ (ensuring that most latent graphs remain inactive at each time instant), the operator $\bbD\bbC$ (preventing the latent graph from changing too frequently), or combinations of the two.
\end{remark}

\subsection{Solving the decomposition}
Due to the multiple bilinear terms, Problem \eqref{Opt prob basic} is jointly non-convex in $\{\bbA_1,...,\bbA_R,\bbC\}$. However, it is separately convex in each variable when the others are fixed. This makes it easier to solve for one variable at a time via an alternating approach, i.e., we solve a sequence of convex problems in these variables until convergence. We do this by formulating $R+1$ optimization problems, where each of the first $R$ solves for a latent adjacency matrix $\bbA_r$, whereas the last solves for the temporal signatures in $\bbC$. We solve each of them via the alternating direction method of multipliers. Thus, we perform alternating minimization between $R+1$ variables.
\subsection{Updating the $\bbA_r$s}
Here we outline the update for the $r$-th latent adjacency matrix $\bbA_r$s, keeping fixed the other matrices $\{\bbA_{r'}\}_{r'\neq r}$ and the temporal signatures in $\bbC$. Consider the $N^2\times 1$ vector $\bbm_t$ formed by vectorizing the mask at time $t$ $\bbM_t$, i.e., $\bbm_t=\text{vec}(\bbM_t)$. Consider also the $N^2\times T$ matrix $\bbM_0$ that collects the $\bbm_t$s along its columns, i.e., \begin{equation}\label{eq M_0}
    \mathbf{M_{0}}=[\bbm_1,\bbm_2,\ldots,\bbm_T]\in\mathbb{R}^{N^2\times T}.
\end{equation}
Let us define the matrix $\bbXi_r=\frac{1}{2}[\bbZ_1,\ldots,\bbZ_T](\bbc_r\otimes\bbI_N)$; then, the terms in the loss function $f(\cdot)$ that depend on the $r$-th adjacency matrix $\bbA_r$ can be rewritten as 
%\agm{Please reorder the terms so that they appear in the same order as in \eqref{Opt prob basic}}
%
\begin{align}\label{J3 loss in A_r}
    \begin{split}
 & f(\bbA_r)=\frac{1}{2}||\bbA_r||_F^2\sum_{t=1}^T[\bbC]_{t,r}^2\mathbf{1}_{N^2}^{\top}\bbm_t \\&+\tr\bigg(\bbA_r^{\top}\big[\sum_{t=1}^T[\bbC]_{t,r}\mathbf{1}_{N^2}^{\top}\bbm_t\sum_{\bar{r}=1,\bar{r}\neq r}^R[\bbC]_{t,\bar{r}}\bbA_{\bar{r}}\big]\bigg)\\&-\tr\big(\bbA_r^{\top}\text{vec}^{-1}\big(\sum_{t=1}^T\uvbA_{:,:,t}[\bbC]_{t,r}\mathbf{1}_{N^2}^{\top}\bbm_t\big)\big)+\gamma\mathbf 1_N^{\top}\bbA_r\mathbf 1_N\!\\&+\!\delta\tr(\bbA_r\bbXi_r)+2\beta\text{vec}(\bbA_r)^{\top}\!\!\sum_{\substack{\bar{r}=1,\bar{r}\neq r}}^R\!\!\text{vec}(\bbA_{\bar{r}})\!\!\!.\end{split}
\end{align} 
%
Note the term $\sum_{t=1}^T[\bbC]_{t,r}^2\mathbf{1}_{N^2}^{\top}\bbm_t$ that scales the squared Frobenius norm of $\bbA_r$. It is the sum across time of the product between the corresponding squared temporal coefficient $[\bbC]_{t,r}$ and the number of ones in the mask $\bbone^{\top}\bbm_t$, which is also the number of observations available in $\uvbA$ at that time. Note also that the influence of the mask on updating the $r$-th adjacency matrix is affected by the corresponding temporal signature $\bbc_r$. Upon defining the matrices $\bbPhi_r=\bbc_{r}^{\top}\otimes \mathbf1_N$ and $\bbGamma_r=\sum_{\bar{r}, \bar{r}\neq r}\bbA_{\bar{r}}(\bbc_{\bar{r}}^{\top}\otimes \mathbf1_N)-\zeta\mathbf1_{N\times T}$, the associated optimization can be compactly written as
%
\begin{align}\label{problem_Ar}
    \begin{split} &\underset{\bbA_r}{\text{minimize}}~f(\bbA_r)\\
    &\text{subject to}~\bbA_r\bbPhi_r+\bbGamma_r\geq\mathbf0_{N\times T},\\&\bbA_r \in \ccalS_A= \{\bbS:\bbS \geq \bbzero_{N\times N}, \tr(\bbS) = 0 ,\bbS=\bbS^{\top}\},
    \end{split}
\end{align}
%
where the inequality constraint is the same as in \eqref{constraint for nontrivial} but written in terms of $\bbA_r$. We solve Problem \eqref{problem_Ar} via the Alternating Direction of Method of Multipliers (ADMM) \cite{boyd2011distributed}. The formulation is
%
\begin{align}\label{augmented prob}
    \begin{split} &\underset{\bbA_r,\bbP}{\text{minimize}}~f(\bbA_r)\\
    &\text{subject to:}~\bbA_r \in \ccalS_A,~\bbA_r\bbPhi_r+\bbGamma_r=\bbP,~\bbP\geq\mathbf{0}_{N\times T},
    \end{split}
\end{align}
%
where the auxiliary variable $\bbP$ is introduced to cast the problem in the ADMM format. Then, the augmented Lagrangian of \eqref{augmented prob} is
\begin{align}\label{LagrangianAr}
    \begin{split}
L(\bbA_r,\bbP,\bbLambda_r)&=f(\bbA_r)+\tr(\bbLambda_r(\bbA_r\bbPhi_r+\bbGamma_r-\bbP))\\&+\frac{\lambda}{2}||\bbA_r\bbPhi_r+\bbGamma_r-\bbP||_F^2,
    \end{split}    
\end{align}
where $\lambda>0$. The updates in the primal variables $\bbA_r$ at iteration $k$ are given as 
\begin{align}\label{ADMM_A}
\begin{split}
    \bbA_r^{k} & = \ccalP_{\ccalS_A}\left(\bbA_r^{k-1}-\lambda\nabla_{\bbA_r}L(\bbA_r^{k-1})\right),
    \end{split}
\end{align}
which is a gradient step followed by a projection onto the set $\ccalS_A$. 
%\red{AGM: I find the notation $\ccalP_{\ccalS_A}$ for projection confusing. I would use $\ccalP_{\ccalS_A}$ or $\ccalP_{\ccalS_A}$.} 
The expression for the gradient $\nabla_{\bbA_r}L(\bbA_r)$ is detailed in Appendix \ref{J3 Appendix ADMM Updates} [cf. \eqref{Appendix derivative A_r}]. For the auxiliary variable $\bbP$, we note that the Lagrangian is convex w.r.t. $\bbP$ and we can readily obtain a closed-form solution, followed by a projection onto the non-negative orthant. The remaining updates for the primal variable $\bbP$ and the dual variables $\bbLambda_r$ are thus
\begin{align}\label{ADMM_A_P}
    \bbP^{k}=[\frac{1}{\lambda}\bbLambda_r^{k-1\top}+\bbA_r^{k}\bbPhi_r+\bbGamma_r]_+
\end{align}
\begin{equation}\label{ADMM_A_Dual}
    \bbLambda_r^{k}=\bbLambda_r^{k-1} + \lambda(\bbA_r^{k}\bbPhi_r+\bbGamma_r-\bbP^{k})^\top,
\end{equation}
where $[\cdot]_+$ is an element-wise operator that clips all negative values to zero. The two steps are repeated until a stopping criterion is met. 
%This whole procedure is repeated alternatively for each latent adjacency matrix $\bbA_r$.
\subsection{Updating $\bbC$}
In this step, we update $\bbC$ keeping $\{\bbA_r\}_{r=1}^R$ fixed. As we did with the adjacency matrices, we first write down the loss function w.r.t. $\bbC$. To do so, we define 
%
\begin{equation}\label{eq X_0}
    \bbA_{\textnormal{vec}}=[\text{vec}(\uvbA_{:,:,1}),\text{vec}(\uvbA_{:,:,2}),\ldots,\text{vec}(\uvbA_{:,:,T})]\in\mathbb{R}^{N^2\times T}.
\end{equation}
\begin{equation}\label{J3 Define A0}
    \mathbf{A_{0}}=[\text{vec}(\bbA_1),\text{vec}(\bbA_2),\ldots,\text{vec}(\bbA_R)]\in\mathbb{R}^{N^2\times R}.
\end{equation}
%
The loss in $\bbC$ then writes as
%
\begin{align}
\begin{split}
    f(\bbC)&=\frac{1}{2}||\bbM_0\circ( \bbA_{\textnormal{vec}}-\bbA_0\bbC^{\top})||_F^2\! +\!\delta\tr(\bbC^{\top}\bar{\bbZ}\bbA_0)\\&+\frac{\mu}{2}||\bbD\bbC||_F^2+\frac{\rho}{2}||\bbC||_F^2,\\
\end{split}
\end{align}
%
where $\tr(\bbC^{\top}\bar{\bbZ}\bbA_0)$ is the signal smoothness prior \eqref{prior smoothness} re-written to show the dependence on  $\bbC$, and $\bar{\bbZ}\in\mathbb{R}^{T\times N^2}$ is a matrix with row $t$ being the vectorized form of the matrix $\bbZ_t^{\top}$, i.e., $[\bar{\bbZ}]_{:,t}=\text{vec}(\bbZ_t^{\top})^{\top}$. The inequality constraint involving both $\bbA$ and $\bbC$ in Problem \eqref{Opt prob basic} translates into $\bbC\Upsilon^{\top}-\zeta\mathbf1_{T\times N}\geq\mathbf0_{T\times N}$ where $\Upsilon=[\bbA_1,\ldots,\bbA_R](\bbI_R\otimes\mathbf1_N)$. Thus, the optimization problem for $\bbC$ can be compactly written as
%
\begin{align}\label{ProblemC}
    \begin{split} \underset{\bbC}{\text{minimize}}\quad &f(\bbC)\\\text{subject to: }&\bbC\Upsilon^{\top}-\zeta\mathbf1_{T\times N}\geq\mathbf0_{T\times N},\\&\bbC\in\ccalS_C=\{\bbS:\bbS\geq\mathbf0_{T\times R}\}.
    \end{split}
\end{align}
%
To deal with the inequality constraint, we formulate another ADMM problem as
%
\begin{align}
    \begin{split} \underset{\bbC}{\text{minimize}}\quad &f(\bbC)
    \\\text{subject to: }&\bbC\Upsilon^{\top}-\zeta\mathbf1_{T\times N}\!=\!\bbQ,\\&\bbC\in\ccalS_C, \;\bbQ\geq\mathbf0_{T\times N}.
    \end{split}
\end{align}
%
%\red{AGM: Is the constraint $\bbC\geq\mathbf0_{T\times N}$ correct? We already have $\bbC\in\ccalS_C$ to enforce that. Either you wanted to write $\bbQ\geq\mathbf0_{T\times N}$ or it is a typo and you should remove it.}
Then, the augmented Lagrangian becomes
%
\begin{align}\label{LagrangianC}
    \begin{split}
L(\bbC,\bbQ,\bbLambda)=& f(\bbC)+\tr\left(\bbLambda(\bbC\Upsilon^{\top}-\zeta\mathbf1_{T\times N}-\bbQ)\right)\\&+\frac{\lambda_c}{2}||\bbC\Upsilon^{\top}-\zeta\mathbf1_{T\times N}-\bbQ||_F^2.
    \end{split}
\end{align}To update $\bbC$, we take a gradient step followed by a projection onto $\ccalS_C$, i.e., 
\begin{align}\label{ADMM_C}
\begin{split}
    \bbC^{k} & = \ccalP_{\ccalS_A}\left(\bbC^{k-1}-\lambda\nabla_{\bbC}L(\bbC^{k-1})\right).
    \end{split}
\end{align} The derivative of the augmented Lagrangian w.r.t. $\bbC$ is detailed in Equation \eqref{Appendix derivative C} in Appendix \ref{J3 Appendix ADMM Updates}. The other two updates are also similar to those made for each $\bbA_r$ and are respectively
\begin{align}\label{ADMM_C_Q}
    \bbQ^{k}=[\frac{1}{\lambda_c}\bbLambda^{k-1\top}+(\bbC^{k}\bbUpsilon)^{\top}-\zeta\mathbf{1}_{TN})\big]_+,
\end{align}
\begin{align}\label{ADMM_C_Dual}
\bbLambda^{k}=\bbLambda^{k-1}+\lambda_c(\bbC^{k}\Upsilon^{\top}-\zeta\mathbf{1}_{TN}-\bbQ^{k})^\top.
\end{align}
Algorithm~\ref{Algorithm TGD}, termed Dynamic Graph Decomposition (DGD), summarizes the steps described in this section.
\begin{algorithm}[!t]
	\caption{\textbf{Dynamic Graph Decomposition (DGD)}}
	\begin{algorithmic}[1]
	\STATE \textbf{Input:} Observations $\uvbM\circ \uvbA\in\reals^{N\times N\times T}$ and $\uvbX\in\reals^{N\times Q\times T}$; mask $\uvbM$; parameters $R$, $\gamma$, $\beta$, $\mu$, $\delta$, $K$, $I$
    \STATE \textbf{Output:} Estimated latent graph adjacency matrices $\bbA_r=\bbA_r^{(I)}$ for $r=1,...,R$ and temporal signatures $\bbC=\bbC^{(I)}$
	\STATE \textbf{Initialization}: Initialize $\{\bbA_r^{(0)}\}_{r=1}^R$, $\bbC^{(0)}$ as i.i.d. realizations of a uniform random variable over $[0,1]$\\
    \quad\quad\textbf{For} $i=1:I$\\
    %\quad\quad\textbf{K Block Alternating updates over $\bbA_r$s and $\bbC$}\\
    \quad\quad~~\textbf{$\bbA_r$-updates:} ($r=1,...,R$)\\
    \quad\quad\quad Initialize $\bbP^0$, $\bbLambda^0$ as i.i.d. realizations of  $\ccalN(0,1)$ \\    
    \quad\quad\quad Set $\bbC^0\!=\!\bbC^{(i-1)}$.\\
    \quad\quad\quad Set $\{\bbA_{r'}^0\!=\!\bbA_{r'}^{(i)}\}_{r'=1}^r$, $\{\bbA_{r'}\!=\!\bbA_{r'}^{(i-1)}\}_{r'=r+1}^R$\\
    \quad\quad\quad Form matrices $\bbXi_r$, $\bbPhi_r$, and $\bbGamma_r$    
    \\

    \quad\quad\quad\quad\textbf{For} $k=1:K$ (ADMM for  $\bbA_r$)\\
    %\quad\quad\quad\quad\; \textbf{Repeat until convergence}~(ADMM for  $\bbA_r$)\\
   \quad\quad\quad\quad\quad Update $\bbA_r^k$ using~\eqref{ADMM_A}\\
   \quad\quad\quad\quad\quad Update $\bbP^k$ using~\eqref{ADMM_A_P}\\
    \quad\quad\quad\quad\quad Update $\bbLambda^k$ using~\eqref{ADMM_A_Dual}\\
    \quad\quad\quad\quad\textbf{end For}\\
    \quad\quad\quad\quad$\bbA_{r}^{(i)} = \bbA_{r}^{K}$\\
    %\quad\quad\quad\quad\textbf{end}\\ 
  %\quad\quad\quad\quad\textbf{end}\\ 
\quad\quad~~\textbf{$\bbC$-update:}\\
\quad\quad\quad\quad Initialize $\bbQ^0$, $\bbLambda^0$ as i.i.d. realizations of $\ccalN(0,1)$\\
\quad\quad\quad\quad Set $\{\bbA_{r'}^0\!=\!\bbA_{r'}^{(i)}\}_{r'=1}^R$\\
    \quad\quad\quad\quad Form matrix $\Upsilon$
    \\
    \quad\quad\quad\quad\textbf{For} $k=1:K$ (ADMM for $\bbC$)\\
%\quad\quad\quad\quad\quad\textbf{Repeat until convergence}~(ADMM for $\bbC$)\\
\quad\quad\quad\quad\quad Update $\bbC^k$ using \eqref{ADMM_C}\\
\quad\quad\quad\quad\quad Update $\bbQ^k$ using~\eqref{ADMM_C_Q}\\
\quad\quad\quad\quad\quad Update $\bbLambda^k$ using~\eqref{ADMM_C_Dual}\\
\quad\quad\quad\quad\textbf{end For}\\
\quad\quad\quad\quad $\bbC^{(i)} = \bbC^{K}$ \\
\quad\quad\textbf{end For}\\
%\quad\quad\quad\quad\textbf{end}
%\State\textbf{end} 
\end{algorithmic} 
\label{Algorithm TGD}
\end{algorithm}
