\end{align}where $|\!|\mathbf 1_{N^2}\mathbf 1_R^{\top}|\!|_F=N\sqrt{R}$ and $|\!|\bbM|\!|_F=\sqrt{R(R-1)}$. The term $|\!|\bbA_0\bbC^{\top}-\bbA_{\textnormal{vec}}|\!|_F$ is the Frobenius norm of the residue matrix, which is bounded following Assumption $\ref{Assumption bounded optimal variables}$. Let this residue be bounded as $\epsilon$. Using Assumption 1, we have
\begin{align}
    |\!|\nabla_{\bbA_0} f\!|\!|_F \!\leq\! \epsilon C \!\!+\!\! \gamma N\sqrt{R} \!+\!\delta C|\!|\bar{\bbZ}_T^{\top}|\!|_F\!\!+\!\!(\beta \sqrt{R(R\!-\!1)}\!+\!\eta)A.
\end{align}The norm $|\!|\bar{\bbZ}_T^{\top}|\!|_F$ is also upper bounded as $N\sqrt{T}$, because each element of $\bar{\bbZ}_T$ and thus, $\bar{\bbZ}_T$, being a negative exponential, is upper bounded by one. Thus, we have
\begin{align}
    |\!|\nabla_{\bbA_0} f\!|\!|_F \!\leq\! \epsilon C\! +\! \gamma N\sqrt{R}\! +\!\delta CN \sqrt{T}\! +\!(\beta\!\sqrt{R(R\!-\!1)}\!+\!\eta)A.
\end{align}
\par\noindent\textbf{Gradient w.r.t. $\bbC$.}: We apply Holder's inequality on the r.h.s. of \eqref{gradient C} to get
\begin{align}
     &|\!|\nabla_{\bbC} f|\!|_F \leq |\!|\bbA_0^{\top}|\!|_F|\!|(\bbA_0\bbC^{\top}-\bbA_{\textnormal{vec}})|\!|_F+\delta N\sqrt{T} A \nonumber \\  &+ |\!|\bbD^{\top}\bbD|\!|_F|\!|\bbC|\!|_F\leq A\epsilon + \delta A N\sqrt{T}+C(\sqrt{6(T-1)}+\rho)
\end{align}where $|\!|\bbD^{\top}\bbD|\!|_F=\sqrt{6(T-1)}$. We see that $ |\!|\nabla_{\bbA_0} f|\!|_F$ and $ |\!|\nabla_{\bbC} f|\!|_F$ are both upper-bounded, implying 
\begin{align}
& |\!|\nabla_{\bbC} f|\!|_F \leq |\!|\nabla_{\bbA_0} f|\!|_F+ |\!|\nabla_{\bbC} f|\!|_F \nonumber \\
& \leq (A+C)\epsilon + \sqrt{R}(\gamma N+\beta A \sqrt{R-1})+ \nonumber \\ & \delta N(C+A)\sqrt{T} +C\sqrt{6{T-1}}+\eta A+\rho C
\end{align}is also upper bounded. Thus, $f(\bbA_0,\bbC)$ is Lipschitz.\qed
\begin{lemma}\label{lemma bi convexity}
$f(\bbA_0,\bbC)$ is strictly bi-convex in both $\bbA_0$ and $\bbC$ if 
\begin{Equation}
        \lambda_{min}(\bbC^{\top}\bbC)>\beta-\eta,~\lambda_{min}(\bbA_0^{\top}\bbA_0)>-\rho.
\end{Equation}
\end{lemma}
\noindent\textbf{Proof.} For strict bi-convexity we need simultaneously  the Hessians $\nabla^2_{\bbA_0}f\succ 0$ and $\nabla^2_{\bbC}f\succ 0$. The Hessian of $f(\cdot)$ w.r.t. $\bbA_0$ is derived as follows: First we write
\begin{align}\label{Hessian A_0}
&\difd\nabla_{\bbA_0}f=\difd\bbA_0\bbC^{\top}\bbC + \beta \difd\bbA_0\bbM+\eta\difd\bbA_0.
\end{align}Doing vectorization on both sides gives us
\begin{align}
    \begin{split}
    \text{vec}(\difd\nabla_{\bbA_0}f)&=(\bbC^{\top}\bbC\otimes\bbI_{N^2}+\beta\bbM^{\top}\otimes\bbI_{N^2})\text{vec}(\difd\bbA_0)\\
        \nabla^2_{\bbA_0}f&=(\bbC^{\top}\bbC+\beta\bbM+\eta\bbI_R)\otimes\bbI_{N^2}
    \end{split}
\end{align} with $\nabla^2_{\bbA_0}f \in \reals^{N^2R\times N^2R}$. The eigenvalues of $\bbM$ are $[R-1,-1,\ldots,-1]$.
%%Proof
For $(\bbC^{\top}\bbC+\beta\bbM+\eta\bbI_R)$ to be positive definite, for any vector $\bbx\in\mathbb R^R$, we have
\begin{align}
\begin{split}
    &\bbx^{\top}(\bbC^{\top}\bbC+\beta\bbM+\eta\bbI_R)\bbx>0\\&\bbx^{\top}\big(\beta\bbM\bbx+\eta\bbI_R\big)\bbx>-\bbx^{\top}\bbC^{\top}\bbC\bbx.
\end{split}
\end{align}Both the l.h.s. and the r.h.s. are functions of $\bbx$. For the inequality to always hold, we need
\begin{align}
\begin{split}
    & \underset{\bbx}{\text{min}}~\bbx^{\top}\big(\beta\bbM+\eta\bbI_R\big)\bbx >  \underset{\bbx}{\text{max}}-\bbx^{\top}\bbC^{\top}\bbC\bbx \\
    & \underset{\bbx}{\text{min}}~\bbx^{\top}\big(\beta\bbM+\eta\bbI_R\big)\bbx > -\underset{\bbx}{\text{min}}~\bbx^{\top}\bbC^{\top}\bbC\bbx.
\end{split}  
\end{align}Now, w.l.o.g. we assume $||\bbx||_2\leq 1$ and have
\begin{align}\label{Hessian A condition}
\begin{split}
    & \beta \lambda_{min}(\bbM) +\eta > -\lambda_{min}(\bbC^{\top}\bbC)\\
    & -\beta +\eta > - \lambda_{min}(\bbC^{\top}\bbC) \\
    &  \lambda_{min}(\bbC^{\top}\bbC) > \beta-\eta. 
\end{split}  
\end{align}For strong convexity in $\bbA_0$, thus, we want condition \eqref{Hessian A condition} to hold always. However, as the feasible set of $\bbC$ is $\mathbb R^N$, the matrix $\bbC^{\top}\bbC$ is not always full rank, thus, $ \lambda_{min}(\bbC^{\top}\bbC)=0$. This implies $\eta>\beta$. Thus, the hyper-parameter associated with signal smoothness over the topology $\beta$ has to be lesser than or equal to $\eta$ for strict convexity in $\bbA_0$.
If this holds, we can conclude that the function is strictly bi-convex in $\bbA_0$.
\par The Hessian w.r.t. $\bbC$ can similarly be derived as
\begin{align}\label{Hessian C}
    \begin{split}
        \difd\nabla_{\bbC}f&=\difd(\bbC)(\bbA_0^{\top}\bbA_0)+(\bbD^{\top}\bbD+\rho\bbI_T)\difd(\bbC)\\
        \text{vec}(\difd\nabla_{\bbC}f)&=(\bbA_0^{\top}\bbA_0\otimes\bbI_{T}) \text{vec}(\difd\bbC)\\&+\bbI_{R}\otimes(\bbD^{\top}\bbD+\rho\bbI_T)\text{vec}(\difd\bbC)\\
\nabla^2_{\bbC}f&=\big(\bbA_0^{\top}\bbA_0\otimes\bbI_{T}+\bbI_{R}\otimes\bbD^{\top}\bbD+\rho\bbI_{RT}\big).
    \end{split}
\end{align} $\nabla^2_{\bbC}f \in \reals^{TR\times TR}$. Both the matrices $\bbA_0^{\top}\bbA_0\otimes\bbI_{T}$ and $\bbI_{R}\otimes\bbD^{\top}\bbD$ are positive semi-definite. Therefore for their sum to be positive definite, we need
\begin{align}
    \begin{split}
        & \lambda_{min}(\bbA_0^{\top}\bbA_0\otimes\bbI_{T})+\lambda_{min}(\bbI_{R}\otimes\bbD^{\top}\bbD)+\rho>0\\
        & \lambda_{min}(\bbA_0^{\top}\bbA_0)+\lambda_{min}(\bbD^{\top}\bbD)>-\rho.
    \end{split}
\end{align}We know that $\lambda_{min}(\bbD^{\top}\bbD)=0$. Therefore, 
for positive definiteness we need $\lambda_{min}(\bbA_0^{\top}\bbA_0)>-\rho$ throughout its domain for strict bi-convexity of $f$ in $\bbC$. Since $\rho>0$, the criterion is satisfied for any $\bbA_0$ in its feasible set. \qed

%% Stationary point
\section{Proof of Proposition \ref{lemma stationary}}\label{app stationary}
Here we evaluate whether the alternating minimization algorithm \ref{Algorithm TGD} converges to a stationary point. Proposition 2.7.1 in \cite{bertsekas1997nonlinear} states that for a block coordinate descent (BCD) problem with the loss function being differentiable in each block, as long as the minimum in each step in uniquely attained, the sequence of descent steps converges to a stationary point. In Algorithm \ref{Algorithm TGD} we perform two block coordinate descents: BCD-1 involving the $\bbA_r$s; BCD-2 involving $\bbA$ and $\bbC$.
\par In BCD-1, the loss in each $\bbA_r$ is differentiable and convex. We also obtain a unique minimum in the dual domain. Following Slater's criterion \cite{boyd2004convex}, this implies we reach the optimal solution, which is unique. Thus, BCD-1 leads to a stationary point in each $\bbA_r$. BCD-2 contains BCD-1 for the $\bbA$ update and thus, we only need to show that the minimizer for $\bbC$ is unique for convergence of Algorithm \ref{Algorithm TGD} to a stationary point. The $\bbC$ update in Equation \eqref{C update} is the solution to the Sylvester Matrix Equation, which is unique if and only if the matrices $\bbD^{\top}\bbD$ and $-\bbA_0^{\top}\bbA_0$ do not share any eigenvalues. Following assumption \ref{sylvester criterion}, this holds. Thus, we have convergence to stationary points for all the variables in BCD-2, i.e., for Algorithm \ref{Algorithm TGD}.\qed

\section{Proof of Proposition \ref{Proposition Local Convergence}}\label{app local minima}
The Proof is based on Corollary $1$ in \cite{li2019alternating}. We provide a sketch of the proof by reasoning for the assumptions we make and how they relate to the conditions mentioned in the original paper.
\par First, the original proof assumes an alternating unconstrained optimization over two variables, with the domain being the space of real numbers. In our case, the optimization involving $\bbA$ (or $\bbA_0$) is over a subset of the real space, thus, Assumption \ref{assumption A0 feasibility} is needed to make sure that both the unconstrained optimization and the constrained one are equivalent. Second, it is required that the loss function is bi-convex in $\bbA$ and $\bbC$. Lemma \ref{lemma bi convexity} highlights the condition where this occurs in our case. The third and final requirement is that the matrix $\nabla_{\bbA_0,\bbC}^2f(\bbA_0,\bbC)$ or $\nabla_{\bbC,\bbA_0}^2f(\bbA_0,\bbC)$ is full rank derived at all strict saddle points. Since the set of strict saddles are contained in the set of all local minima, it suffices for us to show that if $\nabla_{\bbA_0,\bbC}^2f(\bbA_0,\bbC)$ or $\nabla_{\bbC,\bbA_0}^2f(\bbA_0,\bbC)$ is full rank at all stationary points, the criterion for local minima is met. We focus on the matrix $\nabla_{\bbA_0,\bbC}^2f(\bbA_0,\bbC)$ which is of size $TR\times N^2R$, but the same analysis holds for $\nabla_{\bbC,\bbA_0}^2f(\bbA_0,\bbC)$.
The expression of this matrix at a stationary point $(\tilde\bbA_0,\tilde\bbC)$ is
\begin{align}
     \nabla^2_{\bbC,\bbA}f&=(\tilde\bbA_0^{\top}\otimes\tilde\bbC)\bbK_{C,A}+\bbI_R\otimes(\tilde\bbC\tilde\bbA_0^{\top}-\bbA_{\textnormal{vec}}^{\top}+\delta\bar{\bbZ}_T)
\end{align}where $\bbK_{C,A}\in\{0,1\}^{N^2R\times N^2R}$ is the commutation matrix such that $\text{vec}(\difd\bbA_0^{\top})=\bbK_{C,A}\text{vec}(\difd\bbA_0)$. Using Assumption \ref{Assumption rank} and Lemma \ref{lemma stationary}, both $\tilde\bbA_0$ and $\tilde\bbC$ have rank $R$. Thus, their Kronecker product has rank $R^2$. The matrix $\bbK_{C,A}$ is a column permutation matrix and thus, its multiplication does not change the rank of $\tilde\bbA_0\otimes\tilde\bbC$. Thus, for $\nabla^2_{\bbC,\bbA}f$ to have rank $TR$, the second term $\bbI_R\otimes(\tilde\bbC\tilde\bbA_0^{k\top}-\bbA_{\textnormal{vec}}^{\top}+\delta\bar{\bbZ}_T)$ must have rank $TR$. It is a block diagonal matrix. It will have full rank only if $\bbC\bbA_0^{k\top}-\bbA_{\textnormal{vec}}^{\top}+\delta\bar{\bbZ}_T$ has rank $T$. This gives us the desired condition, completing the proof.\hfill\qed
