\title{Mathematical Knowledge Bases as Grammar-Compressed Proof Terms:\\
  Exploring Metamath Proof Structures}


\author{Christoph Wernhard~\inst{1} \and Zsolt
  Zombori~\inst{2,3}}

\authorrunning{C.~Wernhard \and Z. Zombori}
\titlerunning{Mathematical Knowledge Bases as Grammar-Compressed Proof Terms}

\institute{University of Potsdam, Germany%
  \and HUN-REN Alfr\'ed R\'enyi Institute of Mathematics,
  Hungary%
