\section{Policy Optimization for MV-TSGs}\label{sec:MAPI}
In this section, 
% We propose the MV-MAPI method for the MV-TSG when environmental model parameters, such as the reward function and the transition probability function, are known.
we first detail the policy evaluation steps for MV-TSGs. Second, we propose the MV-MAPI algorithm based on the analysis of sensitivity-based optimization and the sequential update scheme, and establish its convergence. Finally, we analyze local geometric properties of first-order stationary points in MV-TSGs.

\subsection{Mean-Variance Policy Evaluation}
\label{sec:policy evaluation}
Inspired by Equation (\ref{eq:mean-variance}), for MV-TSGs we define a surrogate 
reward function associating the mean-variance metric as 
\begin{equation}
    f^{\bm\mu}(s,\bm{a})=r(s,\bm{a}) - \beta(r(s,\bm{a})-\eta^{\bm{\mu}})^2.
    \label{eq:reward_f}
\end{equation} 
Consequently, with the steady state distribution $\pi^{\bm\mu}$ and Equation~(\ref{eq:eta-2}), the mean-variance performance function can be calculated by 
\begin{equation}
    J^{\bm{\mu}}=\sum\limits_{s \in \mathcal{S}} \pi^{\bm\mu}(s) \sum\limits_{\bm{a} \in \mathcal{A}} f^{\bm\mu}(s,\bm{a})\bm\mu(\bm{a}|s) 
    \label{eq:eta_f}.
\end{equation}
According to the definition of the value function in the average-reward setting \citep{sutton2018reinforcement}, we define the value function $V_{f}^{\bm{\mu}}$, action-value function $Q_{f}^{\bm{\mu}}$, and advantage function $A_{f}^{\bm{\mu}}$ in MV-TSGs with respect to the surrogate reward function $f^{\bm{\mu}}$ as follows:
\begin{align} 
    V_{f}^{\bm{\mu}}(s)
    :&= \mathbb{E}_{\bm{\mu}} \Big[\sum\limits_{t=0}^\infty (f^{\bm\mu}(s,\bm{a})- J^{\bm\mu})|s_0 = s \Big], \notag\\
    % & = \mathbb{E}_{\bm{\mu}}  \Big[
    %     \sum\limits_{t=0}^\infty \big( r(s_t,\bm{a}_t) - \eta^{\bm{\mu}} - \beta  ((r(s_t,\bm{a}_t) - \eta^{\bm{\mu}})^2 + \beta\zeta^{\bm{\mu}}   \big) |s_0=s, \Big],\\
    Q_{f}^{\bm{\mu}}(s,\bm{a}):&=\mathbb{E}_{\bm{\mu}} \Bigl[
        \sum\limits_{t=0}^\infty 
        (f^{\bm\mu}(s,\bm{a}) -J^{\bm\mu})|s_0=s,\bm{a}_0=\bm{a}
    \Bigr] \notag\\
    & = f^{\bm\mu}(s,\bm{a})  -J^{\bm\mu} + \sum\limits_{s' 
    \in \mathcal{S}}P(s'|s,\bm{a})V_{f}^{\bm\mu}(s'),  \label{eq:qf function-2 }\\
    \label{eq:af function} A_{f}^{\bm{\mu}}(s,\bm{a}):&= Q_{f}^{\bm{\mu}}(s,\bm{a}) - V_{f}^{\bm{\mu}}(s).
\end{align}

In the long-run dynamic system, the strong Markov property indicates the value function  satisfies the Poisson equation  
\begin{equation*}\label{eq:bellman equation}
    V_{f}^{\bm{\mu}} (s) = f^{\bm{\mu}}(s) - J^{\bm{\mu}} + \sum\limits_{s' 
    \in \mathcal{S}}P^{\bm{\mu}} (s'|s)V_{f}^{\bm{\mu}} (s') \quad \forall s \in \mathcal{S},
\end{equation*}
where $P^{\bm\mu}(s'|s)=\sum\limits_{\bm{a}\in \mathcal{A}}\bm\mu(\bm{a}|s)P(s'|s,\bm{a})$, $f^{\bm{\mu}}(s)=\sum\limits_{\bm{a} \in \mathcal{A}} \bm{\mu}(\bm{a}|s)f^{\bm\mu}(s,\bm{a})$. It is known that $P^{\bm\mu}$ is a stochastic matrix and its rank is $|\mathcal{S}|-1$. Given vectors $\bm{f}^{\bm{\mu}}$, $\bm{\pi}^{\bm\mu}$ and the matrix $\bm{P}^{\bm{\mu}}$, the value function $\bm{V}_{f}^{\bm{\mu}}$ can be calculated as \citep{xia2016generalized} 
\begin{equation}
    \label{eq:fund_matrix}
    \bm{V}_{f}^{\bm{\mu}}=(\boldsymbol{I}-\bm{P}^{\bm{\mu}}+\boldsymbol{e}\bm{\pi}^{\bm\mu})^{-1}\bm{f}^{\bm\mu},
\end{equation}
where $\boldsymbol{I}$ is an $|\mathcal{S}|$-dimensional identity matrix and $\boldsymbol{e}$ is an $|\mathcal{S}|$-dimensional column vector with all elements 1.

Consequently, for MV-TSGs under the joint policy $\bm\mu$, the policy evaluation can be conducted by:  \\
1) Calculate $\pi^{\bm\mu}$ and $P^{\bm\mu}$ according to the transition function $P$ and joint policy $\bm\mu$. \\
2) The values of $\eta^{\bm\mu}$, $f^{\bm{\mu}}$ and $J^{\bm\mu}$ can be calculated using Equations (\ref{eq:eta-2}), (\ref{eq:reward_f}), (\ref{eq:eta_f}), respectively. \\
3) The values of $V_{f}^{\bm{\mu}}$, $Q_{f}^{\bm{\mu}}$, and $A_{f}^{\bm{\mu}}$ can be computed using Equations (\ref{eq:fund_matrix}), (\ref{eq:qf function-2 }), (\ref{eq:af function}), respectively.

% As the values of $\eta^{\bm\mu}$, $f^{\bm{\mu}}$ and $J^{\bm\mu}$ can be calculated by Equation (\ref{eq:eta}), (\ref{eq:reward_f}), (\ref{eq:eta_f}), respectively, we can obtain the values of $V_{f}^{\bm{\mu}}$, $Q_{f}^{\bm{\mu}}$, and $A_{f}^{\bm{\mu}}$ by Equation (\ref{eq:bellman equation}), (\ref{eq:qf function-2 }), (\ref{eq:af function}), respectively.

\subsection{Mean-Variance Policy Optimization}
In MV-TSGs, although the Poisson equation holds, the Bellman optimality equation for joint policies fails to hold. This is because the reward function $f^{\bm\mu}$ incorporates a term $\eta^{\bm\mu}$ that depends on actions across both current and future stages. To address this discrepancy, we analyze MV-TSGs by using the theory of sensitivity-based optimization.

\subsubsection{Analysis of sensitivity-based optimization}
Based on the theory of sensitivity-based optimization \citep{cao2007stochastic}, we derive the following difference formula and derivative formula for MV-TSGs. The proofs of Lemma~\ref{lemma:J-difference} and Lemma~\ref{lemma:J-derivative} are provided in Appendix~\ref{sec:appd_J-difference} and Appendix~\ref{sec:appd_J-derivative}.
\begin{lemma}[Performance Difference Formula for MV-TSGs]
    For any two joint policies $\bm{\mu}$, $\bar{\bm{\mu}} \in \mathcal{U}$, we have
    \begin{equation}
        J(\bar{\bm{\mu}}) - J(\bm{\mu}) 
        % &=\mathbb{E}_{s \sim \pi^{\bar{\bm{\mu}}}, \emph{\bm{a}} \sim \bar{\bm{\mu}}}[A_{f}^{\bm{\mu}}(s,\emph{\bm{a}})] - \beta \mathbb{E}_{s \sim \pi^{\bar{\bm{\mu}}}, \emph{\bm{a}} \sim \bar{\bm{\mu}}} [(r(s,\emph{\bm{a}})-\eta^{\bar{\bm\mu}})^2 - (r(s,\bm{a})-\eta^{\bm\mu})^2 ] \\
        = \mathbb{E}_{s \sim \pi^{\bar{\bm{\mu}}}, \bm{a} \sim \bar{\bm{\mu}}}[A_{f}^{\bm{\mu}}(s,\bm{a})] + \beta(\eta^{\bar{\bm\mu}} - \eta^{\bm\mu} )^2 .
        \label{eq:MVPDF-2}
    \end{equation}
    \label{lemma:J-difference}
\end{lemma}
\vspace{-2em}
\begin{lemma}[Performance Derivative Formula for MV-TSGs]
    Given any two joint policies $\bm{\mu},\bar{\bm{\mu}} \in \mathcal{U}$, we consider a mixed policy $\delta_{\bm\mu}^{\bar{\bm\mu}}$, 
    \begin{equation*}
        \delta_{\bm\mu}^{\bar{\bm\mu}}(\bm{a}|s) = (1-\delta)\bm{\mu}(\bm{a}|s)+\delta \bar{\bm{\mu}}(\bm{a}|s), \notag
    \end{equation*}
    where the joint action $\bm{a}$ follows $\bm{\mu}$ with probability $1-\delta$ and follows $\bar{\bm{\mu}}$ with probability $\delta$, $\delta \in [0,1]$. 
    We have
    \begin{equation*}
        \frac{\mathrm{d}J{(\delta_{\bm\mu}^{\bar{\bm\mu}})}}{\mathrm{d}\delta}\Big|_{\delta=0} = \mathbb{E}_{s\sim \pi^{\bm{\mu}}, \bm{a}\sim \bar{\bm{\mu}}}[A_{f}^{\bm{\mu}}(s,\bm{a})]. \notag
    \end{equation*}
    \label{lemma:J-derivative}
\end{lemma}
\vspace{-2em}
In Lemma~\ref{lemma:J-difference}, we can observe that the second term on the r.h.s of Equation~(\ref{eq:MVPDF-2}) is always positive. This result 
% This result indicates that standard dynamic programming methods, such as policy iteration, are inapplicable in MV-TSGs. Fortunately, Equation~(\ref{eq:MVPDF-1}) can be transformed into Equation (\ref{eq:MVPDF-2}), where the second term on the r.h.s is always positive. Equation~(\ref{eq:MVPDF-2})
implies that if we choose a joint policy $\bar{\bm{\mu}}$ that has a non-negative expected advantage function at every state $s$, i.e., $\sum\limits_{\bm{a}} \bar{\bm\mu}(\bm{a}|s)[A_{f}^{\bm{\mu}}(s,\bm{a})] \ge 0$, the joint policy is guaranteed to be improved. %or remain constant if the expected advantage is zero everywhere, since $\mathbb{E}_{s\sim \pi^{\bar{\bm{\mu}}}, a\sim \bar{\bm{\mu}}}[A_{f}^{\bm{\mu}}(s,\bm{a})]=0$ when $\bar{\bm{\mu}}=\bm{\mu}$. 
Lemma~\ref{lemma:J-derivative} describes the performance derivative at policy $\bm\mu$ towards another policy $\bar{\bm\mu}$. It demonstrates the local structure of the MV-TSG problem to guide the direction of policy optimization. Lemma~\ref{lemma:J-difference} and Lemma~\ref{lemma:J-derivative} establish analytical foundations for joint policy improvement, which subsequently motivate the development of optimization algorithms in later sections.

\subsubsection{Optimization method}
In stochastic games, for each agent, the policies of others are a part of its environment. Simultaneous policy updates of all agents make the environment non-stationary from the perspective of individual agents. To address the issue of non-stationarity, a sequential update mechanism is introduced, which allows agents to update their policies one by one in a given order. When one agent updates its policy, the policies of other agents remain fixed. 

We first provide the definition of local NEs and present the result on the existence of deterministic or pure NEs, where $\mu_i: \mathcal{S} \mapsto \mathcal{A}_i$ for each agent $i$. 

\begin{definition}[Local Nash Equilibrium]
    \label{def:local_NE}
    In a stochastic game, a joint policy $\bm{\mu}^*=(\mu^*_1,\cdots,\mu^*_N) \in \mathcal{U}$ is a local Nash equilibrium if $\exists \bar{\delta}\in (0,1]$, for all $\delta \in (0,\bar{\delta}]$, we have
    \begin{equation*}
        J(\mu^*_i,\bm\mu^*_{-i}) \ge J(\delta_{\mu^*_i}^{\mu_i},\bm\mu^*_{-i}), \quad \forall \mu_i \in \mathcal{U}_i, ~ i \in \mathcal{N}, \notag
    \end{equation*}
     where $\delta_{\mu^*_i}^{\mu_i} = (1-\delta)\mu_i^* + \delta \mu_i$. The equilibrium is called a strict local NE if the inequality holds strictly. Moreover, When $\bar{\delta}=1$, the local NE becomes an NE. 
\end{definition} 

\begin{remark}
    We note that the policy of each agent $i$ is a mapping $\mu_i:\mathcal{S} \mapsto \Delta(\mathcal{A}_i)$, which can be represented as a vector of dimension $|\mathcal{S}||\mathcal{A}_i|$. Definition~\ref{def:local_NE} is derived from the concept of a local optimum in $\mathbb{R}^n$ using the form of the directional derivative. Specifically, given a function $f:F\subseteq\mathbb{R}^n\to \mathbb{R}$, where $F$ is the domain of $f$, a point $x^* \in F$ is a local maximum if there exists $\epsilon>0$ such that for all $ p \in (0,\epsilon]$ and any feasible direction $v$, we have $f(x^*)\ge f(x^*+pv)$. Moreover, for a feasible direction $v$, the directional derivative holds that $\nabla_v f(x)=\frac{\text{d}g(p)}{\text{d}p}|_{p=0}$, where $g(p)=f(x+pv)$.
     For more details,  refer to \citet[Chapter 6]{chong2013introduction}.

%     % This definition is based on the local optimum in the form of the directional derivative. Given a function $f:F\subseteq\mathbb{R}^n\to \mathbb{R}$, where $F$ is the domain of $f$, a point $x^*$ is a local maximum if there exists $\epsilon>0$ such that for all $x\in F$ satisfying $\|x-x^* \|\le\epsilon$, we have $f(x^*)\ge f(x)$. In the directional derivative formulation, a point $x^*$ is a local maximum if there exists $\epsilon>0$ such that for all $ h \in (0,\epsilon]$ and feasible direction $v$, we have $f(x^*)\ge f(x+hv)$. For more details, refer to \cite{chong2013introduction}.
\end{remark}

