\begin{theorem}
    MV-TSGs at least have a deterministic (pure) Nash policy, which achieves the maximum of the mean-variance performance function. 
    \label{threm:deterministic NE}
\end{theorem}

The proof is presented in Appendix~\ref{sec:appd_threm1}. Theorem~\ref{threm:deterministic NE} indicates that solutions to MV-TSGs can be searched within a deterministic joint policy space $\mathcal{D}$. Subsequently, we propose an MV-MAPI algorithm for MV-TSGs based on Lemma~\ref{lemma:J-difference} and the sequential update mechanism. Let $i_{1:h}$ denote an ordered subset $\{i_1,\cdots,i_h  \}$ of $\mathcal{N}$, and let $-i_{1:h}$ refer to its complement. We write $i_k$ when we refer to the $k$th agent in the ordered subset. The MV-MAPI algorithm for MV-TSGs is stated in Algorithm~\ref{alg:MVMAPI}.

% With Proposition~\ref{prop:deterministic NE} and Equation (\ref{eq:MVPDF-2}), we propose the MV-MAPI algorithm for the MV-TSG based on the sequential update scheme, which is stated in Algorithm~\ref{alg:MVMAPI}.
To analyze Algorithm~\ref{alg:MVMAPI}, we define the first-order stationary point in the form of a mixed joint policy for MV-TSGs. Similar definitions of stationary points are also introduced by \cite{leonardos2022global} and \cite{zhang2024gradient} for the directly parameterized Markov potential games. Subsequently, we show the convergence of Algorithm~\ref{alg:MVMAPI} by Theorem~\ref{threm:MAPI_convergence}.

\begin{definition}[First-order Stationary Point]
    A joint policy $\tilde{\bm\mu}=(\tilde{\mu}_1,\cdots,\tilde{\mu}_N)$ is a first-order stationary point in MV-TSGs if for any $\mu_i\in \mathcal{U}_i$ and $\delta_{\tilde{\mu}_i}^{\mu_i}=(1-\delta)\tilde{\mu}_i + \delta \mu_i$, we have
    \begin{equation}
    \frac{\mathrm{d}J{(\delta_{\tilde{\mu}_i}^{\mu_i},\tilde{\bm\mu}_{-i})}}{\mathrm{d}\delta}\Big|_{\delta=0} \le 0, \quad \forall i \in \mathcal{N}.
        \label{eq:stationay_neq}
    \end{equation} 
    \label{def:statationary policy}
\end{definition}
\begin{algorithm}[H]
    \label{alg:MVMAPI}
    \caption{Mean-variance multi-agent policy iteration with monotonic improvement property}
    \SetAlgoLined
    \setstretch{0.9}

    Initialize a deterministic joint policy $\bm{\mu}^{(0)} = (\mu^{(0)}_1,\cdots,\mu^{(0)}_N)$.

    \For{$k=0,1,\cdots$}
    {

        Let $\hat{\bm{\mu}}^{(k,0)} =\bm{\mu}^{(k)} $.

        Draw a permutation $i_{1:N}$ of agents at random.

        \For{$h=1:N$}
        {
            For the policy $\hat{\bm{\mu}}^{(k,h-1)}$, compute the values of $\eta^{\hat{\bm{\mu}}^{(k,h-1)}}$,$f^{\hat{\bm{\mu}}^{(k,h-1)}}$,$J^{\hat{\bm{\mu}}^{(k,h-1)}}$,  respectively.

            Compute the values of $V_{f}^{\hat{\bm\mu}^{(k,h-1)}}(s)$ for all states $s$, $Q_{f}^{\hat{\bm\mu}^{(k,h-1)}}(s,\bm{a})$ and $A_{f}^{\hat{\bm\mu}^{(k,h-1)}}(s,\bm{a})$ for all state-action pairs $(s,\bm{a})$, respectively.

            Update the individual policy of agent $i_h$
            \begin{align}
                &\mu^{(k+1)}_{i_h}(s)=\mathop{\arg\max}\limits_{a_{i_h}} \big[A_{f}^{\hat{\bm{\mu}}^{(k,h-1)}}(s,a_{i_h},\bm{a}_{-i_h}) \big], \quad \bm{a}_{-i_h}\sim \hat{\bm{\mu}}^{(k,h-1)}_{-i_h},\forall s \in \mathcal{S}.
                \label{eq:max} \\
                &\text{(\small Let $\mu_{i_h}^{(k+1)}(s)=\mu_{i_h}^{(k)}(s)$ when $\mu_{i_h}^{(k)}(s) $ can already achieve max in (\ref{eq:max}).)} \notag
            \end{align}
            % $\mu^{(k+1)}_{i_h}(s)=\mathop{\arg\max}\limits_{a_{i_h}} \big[A_{f}^{\hat{\bm{\mu}}^{(k,h-1)}}(s,a_{i_h},\bm{a}_{-i_h}) \big], \quad \bm{a}_{-i_h}\sim \hat{\bm{\mu}}^{(k,h-1)}_{-i_h}$, $\forall s \in \mathcal{S}$. (Let $\mu_{i_h}^{(k+1)}(s)=\hat{\mu}_{i_h}(s)$ When $\hat{\mu}_{i_h}(s) $ can already achieve maximum.)

            Update the joint policy $\hat{\bm{\mu}}^{(k,h)} =(\mu^{(k+1)}_{i_1}, \cdots,\mu^{(k+1)}_{i_h},\mu^{(k)}_{i_{h+1}},\cdots,\mu^{(k)}_{i_N})$.
        }
        \eIf{$\mu_i^{(k)} == \hat{\mu}_i^{(k+1)}, \forall i \in \mathcal{N}$}
            {Done and break.}
            {$\bm{\mu}^{(k+1)} = \hat{\bm{\mu}}^{(k,N)}$.}
    }
    Return $\bm{\mu}^{(k)}$.
\end{algorithm}
\begin{theorem}
    Algorithm~\ref{alg:MVMAPI} converges to a first-order stationary point  monotonically.
    \label{threm:MAPI_convergence}
\end{theorem}
\proof{}
    We first prove the monotonic convergence properties of Algorithm~\ref{alg:MVMAPI}.
    With Lemma~\ref{lemma:J-difference}, in the sequential update process we have $J(\bm\mu^{(k)}) = J(\hat{\bm{\mu}}^{(k,0)}) \le J(\hat{\bm{\mu}}^{(k,1)}) \le \cdots \le J(\hat{\bm{\mu}}^{(k,N)}) = J(\bm\mu^{(k+1)})$. This result demonstrates the monotonicity of Algorithm~\ref{alg:MVMAPI}.  Furthermore, as the reward function is bounded, the average reward performance function $\eta^{\bm\mu}$ and variance performance function $\zeta^{\bm\mu}$ are bounded. Consequently, the mean-variance performance function $J^{\bm\mu}$ is bounded as well. Therefore, the monotonicity and convergence of Algorithm~\ref{alg:MVMAPI} are proved. 

    Subsequently, we show that the converged joint policy $\bm\mu = (\mu_{1},\cdots,\mu_{N})$ is a first-order stationary point. When Algorithm~\ref{alg:MVMAPI} converges to $\bm\mu$, for any agent $i$, we have
    \begin{equation}
        \mathbb{E}_{\bm{a}_{-i}\sim \bm\mu_{-i}} [A_{f}^{\mu_i,\bm\mu_{-i}}(s,a_i,\bm{a}_{-i})] \le 0, \quad \forall s \in \mathcal{S}, a_i \in \mathcal{A}_i.
        \label{eq:local_br_le0}
    \end{equation}
     Considering the mixed policy $\delta_{\mu_i}^{\bar{\mu}_i}=(1-\delta)\mu_i +\delta \bar{\mu}_i$, $\bar\mu_i \in \mathcal{U}_i$, Lemma~\ref{lemma:J-derivative} and Equation (\ref{eq:local_br_le0}) jointly imply $\frac{\text{d}J(\delta_{\mu_i}^{\bar{\mu}_i},\bm\mu_{-i})} {\text{d}\delta}\Big|_{\delta=0} \le 0$. These results hold for all agents and we can conclude that Algorithm~\ref{alg:MVMAPI} converges to a first-order stationary point according to Definition~\ref{def:statationary policy}.
\endproof
\begin{remark}
    All local NEs, including NEs and optimal joint policies, are first-order stationary points. However, the reverse is not true. More details  are investigated in Section~\ref{sec:analysis of stationary points}.
\end{remark}

Although Algorithm~\ref{alg:MVMAPI} converges to a first-order stationary point, MV-MAPI is expected to converge rapidly, similar to policy iteration in traditional MDP theory. However, deriving a specific analysis of the algorithmic complexity of Algorithm~\ref{alg:MVMAPI} is difficult. This is because the algorithmic complexity of classical policy iteration remains an open problem \citep{littman1995complexity}.



% Compared to policy iteration methods, policy-gradient methods require careful step size selection; otherwise, they may converge very slowly or fail to converge. 
% Policy iteration algorithms are more desirable in practice. For example, the Proximal Policy Optimization (PPO) \citep{schulman2017proximal}, a state-of-the-art RL algorithm, has been successfully applied to various optimization problems. PPO is derived from the trust region policy optimization method \citep{schulman2015trust}, which can be regarded as an approximate policy iteration method and guarantees a strict improvement with each policy update. Motivated by the PPO algorithm based on policy iteration in MDPs, we propose a MARL algorithm based on MV-MAPI and analyze its convergence properties in Section~\ref{sec:MV-MARL}.

\subsection{Analysis of Stationary Points in MV-TSGs}\label{sec:analysis of stationary points}
Different from the result that first-order stationary points of standard discounted or averaged TSGs are equivalent to NEs \citep{zhang2024gradient, cheng2024provable, lei2020asynchronous}, we show that the local geometry and landscape of stationary points in MV-TSGs are more complicated, as stated in the following theorem. 
\begin{theorem}
    For the first-order stationary point $\tilde{\bm\mu}$ in MV-TSGs, we have
    \begin{itemize}
        \item If $\tilde{\bm\mu}$ satisfies $\frac{\mathrm{d}J(\delta_{\tilde{\mu}_i}^{\mu_i},\tilde{\bm\mu}_{-i})}{\mathrm{d}\delta}\Big|_{\delta=0} < 0$ for any agent $i \in \mathcal{N}$ and $\delta_{\tilde{\mu}_i}^{\mu_i}=(1-\delta)\tilde{\mu}_i + \delta \mu_i$, $\mu_i \in \mathcal{U}_i$, then $\tilde{\bm\mu}$ is a strict local NE in MV-TSGs. 
        % More importantly, $\tilde{\bm\mu}$ is also a \textbf{strict local maximum} of the mean-variance performance function $J^{\bm\mu}$.
        \item If there exist some agents $i$ and mixed policies $\delta_{\tilde{\mu}_i}^{\bar{\mu}_i}=(1-\delta)\tilde{\mu}_i + \delta \bar\mu_i$, $\bar\mu_i\in \mathcal{U}_i$, satisfy $\frac{\mathrm{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\mathrm{d}\delta}\Big|_{\delta=0} = 0$, a necessary and sufficient  condition for the stationary point is a local NE is that: for these agents $i$ and $\bar\mu_i$,  $\exists \bar\delta \in (0,1], \forall \delta \in (0,\bar\delta]$, \textbf{the long-run average reward} holds that $\eta(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})=\eta(\tilde{\mu}_i,\tilde{\bm\mu}_{-i})$. 
    \end{itemize}
    \label{theorem:stationary policy}
\end{theorem}
\proof{}
The first-order stationary point $\tilde{\bm\mu}$ implies that for any agent $i$, $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\mu_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} \le 0$ along the direction of any $\mu_i \in \mathcal{U}_i$. At the stationary point, if for some agent $i$, $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} < 0$ holds along the direction of any other policy $\bar\mu_i$, we can infer that $\exists \bar\delta_i \in (0,1]$, such that $\forall \delta \in (0,\bar\delta_i]$, $J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\mu}_{-i}) < J(\tilde{\mu}_i,\tilde{\mu}_{-i})$. If for any agent Inequation~(\ref{eq:stationay_neq}) is always strictly holds, we can choose $\bar\delta=\min(\bar\delta_1,\cdots,\bar\delta_N)$. According to the Definition~\ref{def:local_NE}, we can conclude that the first-order stationary point is a strict local NE, and the first term of Theorem \ref{theorem:stationary policy} is proved.

However, if the first-order stationary point $\tilde{\bm\mu}$ satisfies the condition that there exists some agent $i$ and policy $\bar\mu_i$ such that  $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} = 0$, the analysis of such cases becomes more intricate. 
When $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} = 0$, according to Lemma~\ref{lemma:J-derivative}, we have
\begin{equation*}
    \frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} = \mathbb{E}_{s\sim \pi^{\tilde{\bm\mu}}, {a_i\sim \bar\mu_i, \bm{a}_{-i}\sim \tilde{\bm\mu}_{-i}}}[A_{f}^{\tilde{\bm\mu}}(s,a_i, \bm{a}_{-i})]=0.
\end{equation*}
Because the elements of steady-state distribution $\pi^{\tilde{\bm\mu}}$ are positive, 
and $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\mu_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} \le 0$ holds for any agent $i$ and policy direction $\mu_i \in \mathcal{U}_i$, 
we claim that
\begin{equation}
    \mathbb{E}_{a_i\sim \bar\mu_i, \bm{a}_{-i}\sim \tilde{\bm\mu}_{-i}} [A_{f}^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}}(s,a_i,\bm{a}_{-i})] = 0, \forall s \in \mathcal{S}.
    \label{eq:key_eq}
\end{equation}
We prove this claim by contradiction. If for some state $s$, $\mathbb{E}_{a_i\sim \bar\mu_i, \bm{a}_{-i}\sim \tilde{\bm\mu}_{-i}} [A_{f}^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}}(s,a_i,\bm{a}_{-i})] > 0$, we can construct a new policy $\mu_i'$ such that $\mu_i'(a_i|s)=\bar{\mu}_i(a_i|s),\forall a_i \in \mathcal{A}_i$, and in all other states, it follows the policy $\tilde{\mu}_i$. Let $\delta_{\tilde{\mu}_i}^{\mu_i'} = (1-\delta)\tilde{\mu}_i + \delta \mu_i'$, then we have $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\mu'_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} >0$, which contradicts with the fact that $\tilde{\bm\mu}$ is first-order stationary.

According to the performance difference of Lemma~\ref{lemma:J-difference}, we have 
\begin{align}
    J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}) - J(\tilde{\mu}_i,\tilde{\bm\mu}_{-i}) 
    =& \mathbb{E}_{s\sim \pi^{\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}}, \bm{a}\sim (\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})} [A_{f}^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}}(s,\bm{a})] + \beta(\eta^{\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}} - \eta^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}})^2 \notag\\
    =& (1-\delta)\mathbb{E}_{s\sim \pi^{\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}}, \bm{a}\sim (\tilde{\mu}_i,\tilde{\bm\mu}_{-i})} [A_{f}^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}}(s,\bm{a})] \notag\\
    & + \delta \mathbb{E}_{s\sim \pi^{\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}}, \bm{a}\sim (\bar\mu_i,\tilde{\bm\mu}_{-i})} [A_{f}^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}}(s,\bm{a})] \notag\\
    & + \beta(\eta^{\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}} - \eta^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}})^2  \notag\\
     =& \beta(\eta^{\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}} - \eta^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}})^2. \label{eq:perf_diff_stationary}
\end{align}
The second equality holds because  $\delta_{\tilde{\mu}_i}^{\bar{\mu}_i}(s,a_i)=(1-\delta)\tilde{\mu}(s,a_i) + \delta \bar\mu(s,a_i)$. The third equality is due to $\mathbb{E}_{\bm{a}\sim \tilde{\bm\mu}} [A_{f}^{\tilde{\bm\mu}}(s,\bm{a})]=0$ and $\mathbb{E}_{a_i \sim \bar{\mu}_i, \bm{a}_{-i}\sim \tilde{\mu}_{-i}} [A_{f}^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}}(s,a_i,\bm{a}_{-i})]=0$ (Equation~(\ref{eq:key_eq})). Equation (\ref{eq:perf_diff_stationary}) indicates that for arbitrarily small $\delta$, if $\eta^{\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}} \neq \eta^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}}$, then  $J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}) > J(\tilde{\mu}_i,\tilde{\bm\mu}_{-i})$. Therefore, when $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} = 0$ along the direction of some policy $\bar\mu_i$, the necessary and sufficient  condition for $\tilde{\mu}_i$ to be local optimal in the direction of $\bar\mu_i$ is that $\exists \bar\delta_i \in (0,1], \forall \delta \in (0,\bar\delta_i]$, we have $\eta^{\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i}} = \eta^{\tilde{\mu}_i,\tilde{\bm\mu}_{-i}}$. If the necessary and sufficient  condition holds for any agent $i$ and any policy $\bar\mu_i$ satisfying $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} = 0$, then the first-order stationary point is a local NE. Furthermore, applying Equation~(\ref{eq:perf_diff_stationary}) with $\delta=1$ directly leads to Corollary~\ref{coro:escape_saddle}.
\endproof

Theorem~\ref{theorem:stationary policy} implies that first-order stationary joint policies can be (strict) local NEs in some cases. The necessary and sufficient condition in the second term appears to be complex, but it provides a better understanding of the geometry of the problem. For example, if there exist some agent $i$ and policy $\bar{\mu}_i$ that satisfy $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} = 0$ and $\frac{\text{d}\eta(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} \neq 0$, the first-order stationary point $\tilde{\bm\mu}$ is not a local NE; in fact, it is an unstable saddle point. Moreover, inspired by the second term of Theorem~\ref{theorem:stationary policy}, we present Corollary~\ref{coro:escape_saddle}, which concerns the further improvement of the mean-variance performance of stationary points in some cases, even when they are saddle points.

\begin{corollary}
      For a first-order stationary point $\tilde{\bm\mu}$, if there exists some agent $i$ and policy $\bar{\mu}_i$, it holds that $\frac{\mathrm{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\mathrm{d}\delta}\Big|_{\delta=0} = 0$ and $ \eta(\tilde{\mu}_i, \tilde{\bm\mu}_{-i}) \neq \eta(\bar{\mu}_i, \tilde{\bm\mu}_{-i}) $, we can improve the joint policy by updating $\mu_i=\bar{\mu}_i$. 
    \label{coro:escape_saddle}
\end{corollary}

Corollary~\ref{coro:escape_saddle} can be derived by $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\bar{\mu}_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} = 0$ and Lemma~\ref{lemma:J-difference} directly based on the proof of Theorem~\ref{theorem:stationary policy}. Moreover, since Algorithm~\ref{alg:MVMAPI} searches policies in the finite set $\mathcal{D}$, Corollary~\ref{coro:escape_saddle} indicates an effective approach that prevents Algorithm~\ref{alg:MVMAPI} from getting trapped into certain stationary points $\tilde{\bm\mu}$ and leads to a better joint policy, as illustrated in Algorithm~\ref{alg:mod_MVMAPI}.

For a stationary point $\tilde{\bm\mu}$ obtained by Algorithm~\ref{alg:MVMAPI}, Algorithm~\ref{alg:mod_MVMAPI} searches the deterministic policy $\mu_i \in \mathcal{D}_i$ other than $\tilde{\mu}_i$ for each agent $i$ that satisfies $\frac{\text{d}J{(\delta_{\tilde{\mu}_i}^{\mu_i},\tilde{\bm\mu}_{-i})}}{\text{d}\delta}\Big|_{\delta=0} = 0$ and gets a policy set $\mathcal{D}_i^{\tilde{\bm\mu}}$. When there exists a policy $\hat{\mu}_{i} \in \mathcal{D}_i^{\tilde{\bm\mu}} $ such that  $\eta(\hat{\mu}_{i},\tilde{\bm\mu}_{-i}) \neq \eta(\tilde{\bm\mu})$, according to  Corollary~\ref{coro:escape_saddle}, $\tilde{\bm\mu}$ can be further improved by the joint policy $(\hat{\mu}_{i},\tilde{\bm\mu}_{-i})$. Finally, Algorithm~\ref{alg:mod_MVMAPI} obtains an improved joint policy $\tilde{\bm\mu}$ and sets  $\{\mathcal{D}_i^{\tilde{\bm\mu}}\}_{i=1,\cdots,N}$. 

\begin{algorithm}[H]
    \label{alg:mod_MVMAPI}
    \caption{Modified mean-variance multi-agent policy iteration}
    \SetAlgoLined
    \setstretch{0.9}
    Run Algorithm~\ref{alg:MVMAPI} and obtain a converged joint policy $\tilde{\bm\mu}$.

    \For{$i=1,\cdots$,N}
    {
        Find a policy set $\mathcal{D}_i^{\tilde{\bm\mu}} = \left\{\mu_i:\forall s\in \mathcal{S},\mu_i(s)= \arg\max\limits_{a_i} \mathbb{E}_{\bm{a}_{-i} \sim \tilde{\bm{\mu}}_{-i}}[A_{f}^{\tilde{\bm\mu}}(s,a_i,\bm{a}_{-i})] \Big|\mu_i \neq \tilde{\mu}_i \right\}$.

        \eIf{$\mathcal{D}_i^{\tilde{\bm\mu}}$ is empty}
            {Continue.}
            {\For{each $\hat{\mu}_i \in\mathcal{D}_i^{\tilde{\bm\mu}}$}
                {
                \If{$\eta(\hat{\mu}_{i},\tilde{\bm\mu}_{-i}) \neq \eta(\tilde{\bm\mu})$}
                    {Go to step 1 with an initial joint policy $(\hat{\mu}_{i},\tilde{\bm\mu}_{-i})$.}
                }
            }
    }

    Obtain $\tilde{\bm\mu}$ and $\{\mathcal{D}_i^{\tilde{\bm\mu}}\}_{i=1,\cdots,N}$.

\end{algorithm}

Before analyzing the joint policy $\tilde{\bm\mu}$ obtained by Algorithm~\ref{alg:mod_MVMAPI}, we give the definition of \emph{valid pruned joint policy space} $\widetilde{\mathcal{D}}$.

\begin{definition}
    A joint policy space $\widetilde{\mathcal{D}} \subset \mathcal{D}$ is a valid pruned joint policy space if an optimal joint policy of the MV-TSG can be obtained in $\widetilde{\mathcal{D}}$.
\end{definition}

Next, we describe the optimal properties of the converged joint policy of Algorithm~\ref{alg:mod_MVMAPI} in Theorem~\ref{threm:pruned_space}. 
\begin{theorem}
    For the joint policy $\tilde{\bm\mu}$ and sets $\{\mathcal{D}_i^{\tilde{\bm\mu}}\}_{i=1,\cdots,N}$ obtained by Algorithm~\ref{alg:mod_MVMAPI}, let $\mathcal{D}^{\tilde{\bm\mu}}:=\left\{ (\mu_i,\tilde{\bm\mu}_{-i}),\mu_i \in \mathcal{D}_i^{\tilde{\bm\mu}}, \forall i \in \mathcal{N} \right\}$. We have 
    \begin{itemize}
        \item $J({\tilde{\bm\mu}})=J({\bm\mu}), \forall \bm\mu \in \mathcal{D}^{\tilde{\bm\mu}}$. Moreover, the policy space defined by $\widetilde{\mathcal{D}}:=\mathcal{D}\setminus \mathcal{D}^{\tilde{\bm\mu}}$ is a valid pruned joint policy space. % 将确定性策略分为两部分，包括一个有效精简策略
        \item The converged joint policy $\tilde{\bm\mu}$ is a strict local NE in the mixed joint policy space induced by $\widetilde{\mathcal{D}}$. % 收敛到的联合策略在集合1 中是全局最优，在集合2中是局部NE
    \end{itemize}
    \label{threm:pruned_space}
\end{theorem}
\proof{}
    According to  Algorithm~\ref{alg:mod_MVMAPI} and Lemma~\ref{lemma:J-difference}, for each joint policy $\bm\mu \in \mathcal{D}^{\tilde{\bm\mu}}$, we have $\eta^{\tilde{\bm\mu}}=\eta^{\bm\mu}$ and $J^{\tilde{\bm\mu}}=J^{\bm\mu}$. Then, the joint policy in $D^{\tilde{\bm\mu}}$ is no better than $\tilde{\bm\mu}$, and $\widetilde{D}$ is a valid pruned joint policy space.

    Moreover, in the mixed policy space induced by $\widetilde{D}$, we always have $\frac{\text{d}J(\delta_{\tilde{\mu}_i}^{\mu_i},\tilde{\bm\mu}_{-i})}{\text{d}\delta}\Big|_{\delta=0} < 0$ for any agent $i \in \mathcal{N}$ and $\delta_{\tilde{\mu}_i}^{\mu_i}=(1-\delta)\tilde{\mu}_i + \delta \mu_i$, $(\mu_i,\tilde{\bm\mu}_{-i}) \in \widetilde{\mathcal{D}}$. According to Theorem~\ref{theorem:stationary policy}, we can conclude that $\tilde{\bm\mu}$ is a strict local NE in the mixed policy space induced by $\widetilde{D}$. The proof is complete.
\endproof

\begin{remark}
\label{remark:2}
    We claim that the set $\mathcal{D}^{\tilde{\bm\mu}}$ is usually empty since its elements $\bm\mu \in \mathcal{D}^{\tilde{\bm\mu}}$ must satisfy two conditions: (i) $\frac{\mathrm{d}J(\delta_{\tilde{\mu}_i}^{\mu_i},\tilde{\bm\mu}_{-i})}{\mathrm{d}\delta}\Big|_{\delta=0} = 0$ (for some agent $i$), and (ii) $\eta^{\tilde{\bm\mu}}=\eta^{\bm\mu}$.
    When $\mathcal{D}^{\tilde{\bm\mu}}$ is empty, we have $\widetilde{\mathcal{D}}=\mathcal{D}$ and the joint policy $\tilde{\bm\mu}$ obtained by Algorithm~\ref{alg:mod_MVMAPI} is a strict local NE in $\mathcal{U}$. Since  for any state $s$ and agent $i$, we have $\mathbb{E}_{\bm{a}_{-i}\sim \tilde{\bm\mu}_{-i}}A_f^{\tilde{\bm\mu}}(s,a_i,\bm{a}_{-i})<0$ when $a_i$ is not the action selected by $\tilde{u}_i$, therefore it follows that $\frac{\mathrm{d}J(\delta_{\tilde{\mu}_i}^{\mu_i},\tilde{\bm\mu}_{-i})}{\mathrm{d}\delta}\Big|_{\delta=0} = \mathbb{E}_{s\sim \pi^{\tilde{\bm\mu}}, a_i \sim \mu_i, \bm{a}_{-i}\sim \tilde{\bm\mu}_{-i}}[A_{f}^{\tilde{\bm\mu}}(s,a_i, \bm{a}_{-i})]<0$ for any $\mu_i \in \mathcal{U}_i$ other than $\tilde{\mu}_i$. 
\end{remark}

Additionally, we consider a specific scenario where $\eta$ is the same for all joint policies, as discussed in Corollary~\ref{coro:eq_eta_NE}. 

\begin{corollary}
    If the long-run average reward is the same for all joint policies $\bm\mu \in \mathcal{U}$ in the MV-TSG, that is, $\eta^{\bm\mu}$ is independent of $\bm\mu$, Algorithm~\ref{alg:MVMAPI} will converge to an NE.
    \label{coro:eq_eta_NE}
\end{corollary}

Corollary~\ref{coro:eq_eta_NE} holds because when $\eta^{\bm\mu}$ is the same for all joint policy $\bm\mu$, the second term in the r.h.s of Equation~(\ref{eq:MVPDF-2}) vanishes. When Algorithm~\ref{alg:MVMAPI} converges, for any agent $i$, $\mu_i$ is the best response respect to $\bm\mu_{-i}$. Then, the stationary point becomes an NE. One example satisfying the condition in Corollary~\ref{coro:eq_eta_NE} can be found in the experiment of Section~\ref{sec:exp_results}.

The above results suggest that the converged stationary points may usually be a (strict) local NE. However, the qualities of these local NEs are not specified. We characterize the qualities of strict local NEs and present the following theorem. Further investigation is needed for non-strict local NEs.
\begin{theorem}
    In MV-TSGs, a strict local NE $\bm\mu^*$ is equivalent to a \textbf{strict local maximum} of the mean-variance performance function, i.e., $\exists \bar\delta \in (0,1] , \forall \delta \in (0,\bar\delta]$ we have $J(\bm\mu^*) > J(\delta_{\bm\mu^*}^{\bm\mu})$,$\forall \bm\mu\in \mathcal{U}$.
    \label{theorem:strict local optima}
\end{theorem}
\proof{}

We assume that a strict local Nash joint policy is $\bm\mu^*=(\mu_1^*,\cdots,\mu_N^*)$ and any other joint policy is $\bar{\bm\mu}=(\bar{\mu}_1,\cdots,\bar{\mu}_N)$. Let $\delta_{\bm\mu^*}^{\bar{\bm\mu}}=(1-\delta)\bm\mu^* + \delta \bar{\bm\mu}$ and $\Delta_i = \bar{\mu}_i - \mu_i^*$, we have
\begin{align*}
    \frac{\text{d}J(\delta_{\bm\mu^*}^{\bar{\bm\mu}})}{\text{d}\delta}\Big|_{\delta=0} 
    &= \lim\limits_{\delta \to 0} \frac{J(\mu_1^*+\delta \Delta_1, \cdots, \mu_N^*+\delta \Delta_N) - J(\mu_1^*,\cdots,\mu_N^*)}{\delta} \\
    &= \sum\limits_{i=1}^N \frac{\partial J(\mu_i,\mu_{-i}^*)}{\partial \mu_i}\Big|_{\mu_i=\mu_i^*} \frac{\Delta_i}{|\Delta \bm\mu|} \\
    &< 0.
\end{align*}
The second equality holds for the calculation of directional derivative, and $|\Delta \bm\mu|$ indicates the magnitude of $\Delta \bm\mu$ (across all state-action pairs). The inequality holds because strict local Nash joint policies satisfy $\frac{\partial J(\mu_i,\mu_{-i}^*)}{\partial \mu_i}\Big|_{\mu_i=\mu_i^*} \frac{\Delta_i}{|\Delta_i|} < 0$ ( $|\Delta_i| \neq 0$) for all agents $i$. Thus, strict local NEs are strict local optima in MV-TSGs. 

Next, we demonstrate that the converse also holds. For a strict local optimal joint policy $\bm\mu^*$ and any mixed joint policy $\delta_{\bm\mu^*}^{\bm\mu}=(1-\delta)\bm\mu^* + \delta \bm\mu, \bm\mu\in \mathcal{U}$, we have $\frac{\text{d}J(\delta_{\bm\mu^*}^{\bm\mu})}{\text{d}\delta}\Big|_{\delta=0} < 0$. 
Given a policy $\bar\mu_i$ and $\bar{\bm\mu} = (\bar\mu_i, \bm\mu_{-i}^*)$, we can construct a mixed joint policy $\delta_{\bm\mu^*}^{\bar{\bm\mu}} = (\delta_{\mu_i^*}^{\bar{\mu}_i}, \bm\mu_{-i}^*) $. Then, $\frac{\text{d}J(\delta_{\bm\mu^*}^{\bar{\bm\mu}})}{\text{d}\delta}\Big|_{\delta=0}=\frac{\text{d}J(\delta_{\mu_i^*}^{\bar{\mu}_i}, \bm\mu_{-i}^*)}{\text{d}\delta}\Big|_{\delta=0}<0$. This suggests that for any agent $i$, $\frac{\text{d}J(\delta_{\mu_i^*}^{\bar{\mu}_i}, \bm\mu_{-i}^*)}{\text{d}\delta}\Big|_{\delta=0}<0$  along the direction of any policy $\bar\mu_i \in \mathcal{U}_i$. Then, strict local optimal joint policies are strict local NEs. And the proof is finished.
\endproof
Subsequently, we arrive at the following corollary directly with the second term in Theorem~\ref{threm:pruned_space} and Remark~\ref{remark:2}. The optimality of the joint policy obtained by Algorithm~\ref{alg:mod_MVMAPI} is illustrated in Figure~\ref{fig:divide_space}.
\begin{corollary}
    The joint policy $\tilde{\bm\mu} $ obtained by Algorithm~\ref{alg:mod_MVMAPI} is usually a strict local optimum in $\mathcal{U}$, and it is guaranteed to be a strict local optimum in the mixed joint policy space induced by the valid pruned joint policy space $\widetilde{\mathcal{D}}=\mathcal{D}\setminus \mathcal{D}^{\tilde{\bm\mu}}$, i.e., $\exists \bar{\delta}\in (0,1],~\forall \delta \in (0,\bar{\delta}]$ such that  $J(\tilde{\bm\mu})>J(\delta_{\tilde{\bm\mu}}^{\bm\mu}), \forall \bm\mu \in \widetilde{\mathcal{D}}$.
    % \huEdit{Algorithm~\ref{alg:mod_MVMAPI} converges to a strict local optimal joint policy in the mixed joint policy space induced by a valid pruned joint policy space $\widetilde{\mathcal{D}}$.}
\end{corollary}
