\subsection{Proof of Lemma~\ref{lemma:J-difference}}
\label{sec:appd_J-difference}
\proof{}
    Considering the update of the joint policy $\bm\mu$, we use the sensitivity-based optimization theory for Markov systems to derive some results guiding the policy optimization. We introduce a pseudo mean $\omega$ to decompose the policy performance with policy-dependent reward. 

    With a pseudo mean $\omega$, we transform the original MV-TSG problem into a standard TSG with a reward function
    \begin{equation*}
        f_{\omega}(s,\bm{a}) = r(s,\bm{a})- \beta(r(s,\bm{a})-\omega)^2, \quad \forall s \in \mathcal{S}, \bm{a} \in \mathcal{A}.
    \end{equation*}
So the optimizing objective of the pseudo-reward function can be given as 
    \begin{equation*}
        J_{\omega}^{\bm\mu}=\mathbb{E}_{s\sim \pi^{\bm\mu}, \bm{a} \sim \bm{\mu}}[f_\omega(s,\bm{a})].
    \end{equation*}
Since the pseudo reward is independent of the joint policy, the corresponding performance difference formula can be obtained directly according to \citet[Chapter 2]{cao2007stochastic}:
    \begin{equation}\label{eq:diff_pseudo}
        J_{\omega}^{\bar{\bm\mu}} - J_{\omega}^{\bm\mu}=\mathbb{E}_{s\sim \pi^{\bar{\bm\mu}}, \bm{a} \sim \bar{\bm\mu}}[A_{f_\omega}^{{\bm\mu}}(s,\bm{a})],
    \end{equation}
    where $A_{f_\omega}^{\bm\mu}(s,\bm{a})$ is the pseudo advantage with $f_\omega$ as the reward function. With Equation (\ref{eq:diff_pseudo}), we can derive the performance difference formula of $J$ as 
    \begin{align}
        J(\bar{\bm\mu})-J(\bm\mu) &= (J_{\omega}^{\bar{\bm\mu}}-J_{\omega}^{\bm\mu}) + (J^{\bar{\bm\mu}}-J_{\omega}^{\bar{\bm\mu}}) + (J_{\omega}^{\bm\mu}-J^{\bm\mu}) \notag\\
            & = \mathbb{E}_{s\sim \pi^{\bar{\bm\mu}}, \bm{a} \sim \bar{\bm\mu}}[A_{f_\omega}^{\bm\mu}(s,\bm{a})] - \beta \mathbb{E}_{s \sim \pi^{\bar{\bm\mu}}, \bm{a} \sim \bar{\bm\mu}} [(r(s,\bm{a})-\eta^{\bar{\bm\mu}})^2 - (r(s,\bm{a})-\omega)^2] \notag\\
            & \quad -\beta \mathbb{E}_{s \sim \pi^{\bm\mu}, \bm{a} \sim \bm\mu} [(r(s,\bm{a})-\omega)^2 - (r(s,\bm{a})-\eta^{\bm\mu})^2]. \notag
    \end{align}
    Finally, by letting $\omega=\eta^{\bm\mu}$, we arrive at 
    \begin{equation}
        J(\bar{\bm\mu}) - J(\bm\mu)=\mathbb{E}_{s \sim \pi^{\bar{\bm\mu}}, \bm{a} \sim \bar{\bm\mu}}[A_{f}^{\bm\mu}(s,\bm{a})] - \beta \mathbb{E}_{s \sim \pi^{\bar{\bm\mu}}, \bm{a} \sim \bar{\bm\mu}} [(r(s,\bm{a})-\eta^{\bar{\bm\mu}})^2 - (r(s,\bm{a})-\eta^{\bm\mu})^2].
        \label{eq:prf_MVPDF-1}
    \end{equation}
    % which is the same with Equation (\ref{eq:MVPDF-1}) if we explicitly calculate the advantage function with reward function $f_\omega$ and $\omega = \eta^{\bm\mu}$.

    Equation (\ref{eq:prf_MVPDF-1}) consists of two parts. The first term in Equation (\ref{eq:prf_MVPDF-1}) is a standard TSG with $f$ as the reward function, the second term is caused by the perturbation of the mean and it can be further derived as
    \begin{align}
        &\beta \mathbb{E}_{s \sim \pi^{\bar{\bm\mu}}, \bm{a} \sim \bar{\bm\mu}} [(r(s,\bm{a})-\eta^{\bar{\bm\mu}})^2 - (r(s,\bm{a})-\eta^{\bm\mu})^2] \notag\\
        &= \beta\sum\limits_s \pi^{\bar{\bm\mu}}(s) \sum\limits_{\bm{a}} \bar{\bm\mu}(\bm{a}|s) [(\eta^{\bar{\bm\mu}})^2-2r(s,\bm{a}) \eta^{\bar{\bm\mu}} +2r(s,\bm{a})\eta^{\bm\mu} - (\eta^{\bm\mu})^2] \notag\\
        &= \beta((\eta^{\bar{\bm\mu}})^2 - 2(\eta^{\bar{\bm\mu}})^2 + 2\eta^{\bm\mu} \eta^{\bar{\bm\mu}} - (\eta^{\bm\mu})^2) \notag\\
        &= - \beta(\eta^{\bar{\bm\mu}}-\eta^{\bm\mu})^2, \label{eq:prf_MVPDF-2}
    \end{align}
    where the second derivation uses the result $\sum\limits_s \pi^{\bar{\bm\mu}}(s) \sum\limits_{\bm{a}} \bar{\bm\mu}(\bm{a}|s) r(s,\bm{a}) =\eta^{\bar{\bm\mu}}$. Substituting Equation (\ref{eq:prf_MVPDF-2}) into Equation (\ref{eq:prf_MVPDF-1}), we arrive at the Equation (\ref{eq:MVPDF-2}).
\endproof

\subsection{Proof of Lemma~\ref{lemma:J-derivative}}
\label{sec:appd_J-derivative}
\proof{}
    By Lemma~\ref{lemma:J-difference}, we obtain the difference between $\bm\mu$ and $\delta_{\bm\mu}^{\bar{\bm\mu}}$,
    \begin{equation*}
        J(\delta_{\bm\mu}^{\bar{\bm\mu}}) - J(\bm\mu) =\mathbb{E}_{s \sim \pi^{\delta_{\bm\mu}^{\bar{\bm\mu}}}, \bm{a} \sim \delta_{\bm\mu}^{\bar{\bm\mu}}}[A_{f}^{\bm\mu} (s,\bm{a})] - \beta \mathbb{E}_{s \sim \pi^{\delta_{\bm\mu}^{\bar{\bm\mu}}}, \bm{a} \sim \delta_{\bm\mu}^{\bar{\bm\mu}}} [(r(s,\bm{a})-\eta^{\delta_{\bm\mu}^{\bar{\bm\mu}}})^2 - (r(s,\bm{a})-\eta^{\bm\mu})^2].
    \end{equation*}

Taking the derivative w.r.t. $\delta$ and letting $\delta \rightarrow 0$, we obtain the performance derivative formula. We denote 
\begin{align*}
    & l_1(\delta) = \mathbb{E}_{s \sim \pi^{\delta_{\bm\mu}^{\bar{\bm\mu}}}, \bm{a} \sim \delta_{\bm\mu}^{\bar{\bm\mu}}}[A_{f}^{\bm\mu} (s,\bm{a})] \\
    & l_2(\delta) = \mathbb{E}_{s \sim \pi^{\delta_{\bm\mu}^{\bar{\bm\mu}}}, \bm{a} \sim \delta_{\bm\mu}^{\bar{\bm\mu}}} [(r(s,\bm{a})-\eta^{\delta_{\bm\mu}^{\bar{\bm\mu}}})^2 - (r(s,\bm{a})-\eta^{\bm\mu})^2].
\end{align*}
Then $J(\delta_{\bm\mu}^{\bar{\bm\mu}}) - J(\bm\mu) = l_1(\delta)-\beta l_2(\delta)$. For $l_1(\delta)$ we have
    \begin{align*}
        l_1(\delta) &= \mathbb{E}_{s \sim \pi^{\delta_{\bm\mu}^{\bar{\bm\mu}}}} \Big\{(1-\delta) \mathbb{E}_{\bm{a} \sim \bm\mu}[A_{f}^{\bm\mu}(s,\bm{a})] + \delta \mathbb{E}_{\bm{a} \sim \bar{\bm\mu}}[A_{f}^{\bm\mu}(s,\bm{a})] \Big\} \\
                    &= \delta \mathbb{E}_{s \sim \pi^{\delta_{\bm\mu}^{\bar{\bm\mu}}}, \bm{a} \sim \bar{\bm\mu}}[A_{f}^{\bm\mu}(s,\bm{a})] ,
    \end{align*}
    where the last equality follows that $\mathbb{E}_{\bm{a} \sim \bm\mu}[A_{f}^{\bm\mu}(s,\bm{a})]=0$. Since $\lim_{\delta \rightarrow 0} \delta_{\bm\mu}^{\bar{\bm\mu}} =\bm\mu$, we obtain
    \begin{equation*}
        \frac{\text{d}l_1(\delta)}{\text{d}\delta} \Big|_{\delta=0}=\mathbb{E}_{s \sim \pi^{\bm\mu}, \bm{a} \sim \bar{\bm\mu}}[A_{f}^{\bm\mu}(s,\bm{a})].  
    \end{equation*}

    For $l_2(\delta)$, we have
    \begin{align*}
        \frac{\text{d}l_2(\delta)}{\text{d}\delta}\Big|_{\delta=0} 
        &= \lim\limits_{\delta \rightarrow 0} \frac{l_2(\delta)-l_2(0)}{\delta} \\
        &=\lim\limits_{\delta \rightarrow 0} \frac{1}{\delta} \sum\limits_s \pi^{\delta_{\bm\mu}^{\bar{\bm\mu}}}(s) \sum\limits_{\bm{a}} \delta_{\bm\mu}^{\bar{\bm\mu}}(\bm{a}|s)[(r(s,\bm{a})-\eta^{\delta_{\bm\mu}^{\bar{\bm\mu}}})^2 - (r(s,\bm{a}) - \eta^{\bm\mu})^2] \\
        &= \sum\limits_s \pi^{\bm\mu}(s) \sum\limits_{\bm{a}} \bm\mu(\bm{a}|s) \frac{\text{d}(r(s,\bm{a})-\eta^{\delta_{\bm\mu}^{\bar{\bm\mu}}})^2}{\text{d}\delta} \Big|_{\delta=0} \\
        &= \sum\limits_s \pi^{\bm\mu}(s) \sum\limits_{\bm{a}} \bm\mu(\bm{a}|s) \Big[-2(r(s,\bm{a})-\eta^{\bm\mu})\frac{\text{d}\eta^{\delta_{\bm\mu}^{\bar{\bm\mu}}}}{\text{d}\delta}\Big|_{\delta=0} \Big] \\
        &=0,
    \end{align*}
    where the last equality follows that $\sum\limits_s \pi^{\bm\mu}(s) \sum\limits_{\bm{a}}  \bm\mu(\bm{a}|s)r(s,\bm{a})=\eta^{\bm\mu}$, $\sum\limits_s \pi^{\bm\mu}(s)=1$ and $\sum\limits_{\bm{a}} \bm\mu(\bm{a}|s) =1$. Thus, we obtain
    \begin{align*}
        \frac{\text{d}J(\delta_{\bm\mu}^{\bar{\bm\mu}})}{\text{d}\delta} 
        &= \frac{\text{d}l_1(\delta)}{\text{d}\delta} - \beta \frac{\text{d}l_2(\delta)}{\text{d}\delta} \\
        &= \mathbb{E}_{s\sim \pi^{\bm\mu}, \bm{a} \sim \bar{\bm\mu}}[A_{f}^{\bm\mu}(s,\bm{a})].
    \end{align*}

    The above equality indicates that the performance derivative is related to the surrogate reward function $f^{\bm\mu}(s,\bm{a})=r(s,\bm{a}) -\beta (r(s,\bm{a})-\eta^{\bm\mu})^2$.
\endproof

\subsection{Proof of Theorem~\ref{threm:deterministic NE}}
\label{sec:appd_threm1}
\proof{}
    According to the definition, it is evident that the global optimal joint policy of the MV-TSG is an NE. We now show that there exists a global optimal joint policy that is deterministic. \cite{xia2020risk} has proven that a deterministic policy can achieve the optimum in mean-variance MDPs.
    Accordingly, we know that there exists a deterministic centralized joint policy
    \begin{equation*}
        \bm{\mu}^*(\bm{a}|s) = \bm{1} \{\bm{a}=(a^*_1(s),\cdots,a^*_N(s))  \}, \quad s\in \mathcal{S}    \end{equation*}
    that satisfies
    \begin{equation*}
        \bm{\mu}^*=\mathop{\arg\max}\limits_{\bm{\mu}} J^{\bm{\mu}}.
    \end{equation*}
    Let $\mu^*_i(a_i|s)=\bm{1} \{a_i=a^*_i(s) \},  s\in \mathcal{S}$ , we have
    \begin{equation*}
        \bm{\mu}^*(\bm{a}|s)=\prod_{i=1}^N \mu^*_i (a_i|s), \quad  s\in \mathcal{S}.
    \end{equation*}

    Since $\bm{\mu}^*$ globally maximizes the mean-variance performance function $J^{\bm\mu}$, the distributed deterministic policies $(\mu^*_1,\cdots,\mu^*_N)$ also maximize $J^{\bm\mu}$ globally, which completes the proof.
\endproof

