\subsection{Proof of Lemma~\ref{lemma:advantage decomposition}} \label{sec:apped_lemma4}
\proof{}
By the definition of multi-agent advantage function for MV-TSGs, for any agent subset $i_{1:h}$, we have
\begin{align*}
    A^{\bm\mu}_{f,i_{1:h}}(s,\bm{a}_{i_{1:h}})
    &=Q^{\bm\mu}_{f,i_{1:h}}(s,\bm{a}_{i_{1:h}})- V_f^{\bm\mu}(s) \\
    &=\sum\limits_{j=1}^h \left[ Q^{\bm\mu}_{f,i_{1:j}}(s,\bm{a}_{i_{1:j}}) -Q^{\bm\mu}_{f,i_{1:j-1}}(s,\bm{a}_{i_{1:j-1}}) \right] \\
    &=\sum\limits_{j=1}^h A^{\bm\mu}_{f,i_j}(s,\bm{a}_{i_{1:j-1}},a_{i_j}),
\end{align*}
which finished the proof. Similar results have been shown in \cite{zhong2024heterogeneous}.
\endproof

