  $parentCluster$ = findParentCluster($hierarchy$, $cluster$);\\
  \If {$parentCluster \; exists$ }{
   AddEdge($hierarchy$, $parentCluster$, $cluster$);\\}
   \Else{addRoot($hierarchy$, $cluster$)}
  }
 }
}
 $current_y -= \delta$;\\
}
