\begin{remark}
%This factorization underpins the multi-agent training procedure, where each agent’s policy is updated via advanced PPO steps, contingent on partial observations.
%This factorization forms the basis for multi-agent training, where each agent updates its policy using Proximal Policy Optimization (PPO) steps, contingent on its partial observability.
The explicit factorization significantly supports scalable training via PPO, allowing local and global policies to be updated independently. This modular structure ensures stable hierarchical control and adaptability in complex adversarial environments.
\end{remark}

\subsection{Generalized Advantage Estimation and PPO}

%Following \cite{gae_paper} and \cite{schulman_ppo}, each agent maintains a parametric policy $\pi_\theta$ with a value function $V_\theta(\mathbf{s})$. The \emph{advantage} of taking action $a$ in state $\mathbf{s}$ is $A_\theta(\mathbf{s},a) = Q_\theta(\mathbf{s},a) - V_\theta(\mathbf{s})$, estimated via a truncated GAE:
Following~\cite{gae_paper, schulman_ppo}, each agent maintains a parametric policy $\pi_\theta$ with an associated value function $V_\theta(\mathbf{s})$. The advantage function, which estimates how favorable an action is compared to the expected value of the state, is defined as:
\[
A_\theta(\mathbf{s},a) = Q_\theta(\mathbf{s},a) - V_\theta(\mathbf{s})
\]

To compute advantage estimates, we use the Generalized Advantage Estimation (GAE) technique:
\[
\hat{A}_t = \sum_{k=0}^{T-t-1} (\gamma\lambda)^k \delta_{t+k}, 
\quad
\delta_t = r_t + \gamma V(\mathbf{s}_{t+1}) - V(\mathbf{s}_t).
\]

\begin{theorem}[Convergence of PPO in Hierarchical-Adversarial MARL]
\label{thm:convergence}
Consider the Markov game $\mathcal{G}$ with $N+2$ agents, each employing PPO updates with GAE. Let $\theta_i,\phi,\psi$ be their respective parameters. If each agent’s policy improves according to the clipped objective in \cite{schulman_ppo} within a bounded trust region, under standard assumptions (bounded rewards, Markov mixing, sufficiently large batch data and exploration), the system converges to a stationary point $(\theta_i^*, \phi^*, \psi^*)$ that constitutes a local Nash equilibrium. Specifically:
\[
\nabla_{\theta_i} \mathcal{L}(\theta_i^*; \theta_{-i}^*, \phi^*, \psi^*) = 0, \]
\[
\nabla_{\phi} \mathcal{L}(\phi^*; \theta^*, \psi^*) = 0,
\] 
\[\nabla_{\psi} \mathcal{L}(\psi^*; \theta^*, \phi^*) = 0.
\]
\end{theorem}

