\section{Superposition-Attack Secure, Zero-Knowledge Argument for $\NP$}
\label{sec:zk-np}

\subsection{Secret Sharing Scheme Secure Against Superposition Attacks~\cite{DamgardFNS13}}

\begin{definition}[Party views]
Let $P_1, \ldots, P_n$ be parties in a secret sharing scheme $S$ where $s \in \bbS$ is the secret shared using randomness $r \in \cR$. Each party, $P_i$, receives a share $v_i(s; r) \in \zo^k$, also called its private view. For $A \subset [n]$, let $v_A(s; r) = \{v_i(s; r)\}_{i \in A}$ be the string containing the concatenation of views for
parties $P_i$ with $i \in A$.
\end{definition}


\begin{definition}[Perfect security]
\label{def:g-attacks}
Let $G$ be a family of subsets of $2^{[n]}$. A secret sharing scheme $S$ is perfectly secure
against classical $G$-attacks if for any $A \in G$, the distribution of shares $v_A(s; r) \in \zo^t$ does not depend on $s$.
\end{definition}

\begin{definition}[Adversary structure]
\label{def:adv-str}
The adversary structure of a secret sharing scheme is the maximal $G \subset 2^{[n]}$ for which the scheme is
perfectly secure against classical $G$-attacks (\cref{def:g-attacks}).
\end{definition}

\begin{definition}[Perfect security against superposition attacks]
\label{def:ps-sup}
A secret sharing scheme $S$ is perfectly secure against superposition $F$-attacks if, and only if, for all unitary matrices, \begin{equation*}
    U^{adv, F}_{query} \: : \: \cH_{env} \otimes \cH_{query} \to \cH_{env} \otimes \cH_{query}
\end{equation*}
and all possible pairs of inputs, $s, s' \in \bbS$ it holds that $\rho^{adv,F}_s = \rho^{adv,F}_{s'}$, where for $s^* \in \{s, s'\}$
\begin{align*}
    \rho^{adv,F}_{s^*} &= \sum_{r\in\cR}p_r\ket{\psi_{adv,F,s^*}}\allowbreak\bra{\psi_{adv,F,s^*}}, \text{ and} \\
    \ket{\psi_{adv,F,s^*}}& =
    U^{adv, F}_{query} \left( \sum_x \alpha_x \ket{x}_e \otimes \ket{0,0}_q\right)\\
    &=\sum_{x,A\in F,a\in\bits^t}\alpha_{x,A,a}\ket{x}_e\otimes\ket{A,a\oplus v_A(s^*,r)}_q.
\end{align*}
Here, $\cH_{env}$ is the environment in which the adversary can store auxiliary information. The dimension of this register is arbitrary, but finite. In the $\cH_{query}$ register, the adversary submits its queries and receives the corresponding responses from the oracle.
\end{definition}

\begin{remark}
    \label{rem:sss}
    If $S = (\mathsf{Share}, \mathsf{Reconstruct})$ is $t$-secure (as defined in \cref{def:sss}), then 
$S$ is secure against classical $G$-attacks where $G$ is the family of all subsets of size $t$ (\cref{def:g-attacks}).
\end{remark}






\begin{theorem}[{\cite[Theorem 1]{DamgardFNS13}}]
\label{thm:dfns}
Let $S$ be a secret sharing scheme with adversary structure $G$. If $F^2 \subseteq G$ where $F^2 \triangleq \{A \: \vert \: \exists B, C \in F \: :\: A = B \cup C\}$, then $S$ is perfectly secure against superposition $F$-attacks (\cref{def:ps-sup}).
\end{theorem}
For completeness, we refer the reader to \cref{app:dfns-thm1} for a full proof.


\subsection{Our Protocol}

We describe our protocol in \cref{fig:zk-for-np}. Our protocol draws upon the prior works of~\cite{IshaiKOS09} and~\cite{DamgardFNS13}.

