\noindent {$\underline{\textsc{Setup}(1^\lambda)}$}:
Let $\crs = (\ck_B, \ck, c)$ where two commitment keys and a commitment are sampled as follows: $\ck_B \gets \Gen_B(1^\lambda)$, $\ck \gets \Gen(1^\lambda)$, and $c \gets \Com(\ck, 0)$. Outputs $\crs$.

\vspace{0.2cm}

Let $\cR' = \left\{ ((x, c, \ck), (w, r)) \st (x, w) \in \cR \: \vee \: c \equiv \Com(\ck, 1; r) \right\}$. Let $\cC_\cR'$ be a circuit that on input $(x', (w_1, r_1), \ldots, (w_n, r_n))$ computes $\cR'(x', \xor_{i \in [n]} (w_i, r_i))$.
Let $(x, w) \in \cR$.

\vspace{0.3cm}

\noindent {$\underline{\sP_1(\crs, x, w)}$}:
\begin{itemize}
\item Samples $r \gets \{0,1\}^{\lambda}$ uniformly at random. Let $m$ be the size of witnesses to $\cR$. Sample witness shares $w_1', \ldots, w_n' \in \{0, 1\}^m \times \{0, 1\}^\lambda$ such that $\xor_{i \in [n]} w_i' = (w, r)$. 
\item Emulates an execution of $\Pi$ for $\cC_{\cR'}$ on input $(x', w_1', \ldots, w_n')$. Defines $V_1, \ldots, V_n$ to be the views of the $n$ players.
    \item Computes commitments $\alpha_i = \DualCom(\ck_B, V_i; r_i)$ with uniformly random $r_i$ for $i \in [n]$. Defines openings $\zeta_i = (V_i, r_i)$ for $i \in [n]$. 
\item Outputs $(\alpha = (\alpha_1, \ldots, \alpha_n), \zeta = (\zeta_1, \ldots, \zeta_n))$.
\end{itemize}



\noindent {$\underline{\sV_1(\crs, x, \alpha)}$}:
Outputs a set of $t/2$ parties: $\beta = (\beta_1, \ldots, \beta_{t/2})$ where $\beta_i \in [n]$ for $i \in [t/2]$.

\vspace{0.3cm}

\noindent {$\underline{\sP_2(\crs, x, w, \alpha, \beta, \zeta)}$}:
Outputs $\gamma = \{\zeta_{\beta_i}\}_{i \in [t/2]}$ with $\beta = (\beta_1, \ldots, \beta_{t/2})$ and $\zeta = (\zeta_1, \ldots, \zeta_n)$.

\vspace{0.3cm}

\noindent {$\underline{\sV_2(\crs, x, \alpha, \beta, \gamma)}$}:
Outputs $1$ if and only if the following checks pass:
\begin{itemize}
    \item The openings are valid, i.e.\ $\alpha_{\beta_i} \equiv \DualCom(\ck_B, V_{\beta_i}; r_{\beta_i})$ for $i \in [t/2]$.
    \item For $i \in [t/2]$, view $V_{\beta_i}$ has the $\beta_i$th party output $1$.
    \item The views $V_{\beta_i}$ and $V_{\beta_j}$ are consistent with respect to $\Pi$ and $x$ for $i, j \in [t/2]$.
\end{itemize}
Else, outputs $0$.

