\section{Proof of Security Against Superposition Attacks~\cite{DamgardFNS13}}
\label{app:dfns-thm1}

\begin{theorem}[\cref{thm:dfns}]
Let $S$ be a secret sharing scheme with adversary structure $G$. If $F^2 \subseteq G$ where $F^2 \triangleq \{A \: \vert \: \exists B, C \in F \: :\: A = B \cup C\}$, then $S$ will be perfectly secure against superposition $F$-attacks (\cref{def:ps-sup}).
\end{theorem}

\begin{proof}[Proof of \cref{thm:dfns}]

We consider the adversary's final state for any $s \in \bbS$,
\begin{align*}
    \rho^{adv, F}_s &= \sum_{r \in \cR} p_r \sum_{\substack{x, x' \in \cX \\ a, a' \in \zo^t\\ A, A' \in F}} \alpha_{x',A',a'}^* \: \alpha_{x,A,a} \: \ket{x'}_e\bra{x}_e \otimes \ket{A', a' \oplus v_{A'}(s; r)}_q\bra{A, a \oplus v_{A}(s; r)}_q\\
    &= \sum_{\substack{x, x' \in \cX \\ a, a' \in \zo^t\\ A, A' \in F}} \alpha_{x',A',a'}^* \: \alpha_{x,A,a} \: \ket{x'}_e\bra{x}_e \otimes \sum_{r \in \cR} p_r \ket{A', a' \oplus v_{A'}(s; r)}_q\bra{A, a \oplus v_{A}(s; r)}_q.
\end{align*}
We rewrite our state in the following form
\begin{align}
    \rho^{adv, F}_s &= \sum_{\substack{a, a' \in \zo^t\\ A, A' \in F}}\rho^{adv, F}_s\vert_{a,a',A,A'} \label{eqn:fins}
\end{align}
where we define
\begin{align}
    \rho^{adv, F}_s\vert_{a,a',A,A'} &= \sum_{\substack{x, x' \in \cX}} \alpha_{x',A',a'}^* \: \alpha_{x,A,a} \: \ket{x'}_e\bra{x}_e \otimes \sum_{r \in \cR} p_r \ket{A', a' \oplus v_{A'}(s; r)}_q\bra{A, a \oplus v_{A}(s; r)}_q. \label{eqn:flns1}
\end{align}

Let us fix any arbitrary $a,a' \in \zo^t$, and $A, A' \in F$. 
Temporarily consider the state in Equation~\ref{eqn:flns1} for some secret $s \in \bbS$.
We notice that only the second term depends on the secret $s$, so we focus on this term. This term contains information about the views of parties in $B= A' \cup A \in F^2 \subseteq G$. Since our secret sharing scheme $S$ has adversary structure $G$, $S$ is perfectly secure against classical $G$-attacks which ensures that the distribution of $v_B(s; r)$ does not depend on $s$. 
This, in turn, translates to the statement that for all $s, s' \in \bbS$, 
we will have
\begin{align*}
    \sum_{r \in \cR} p_r \ket{A', a' \oplus v_{A'}(s; r)}_q\bra{A, a \oplus v_{A}(s; r)}_q &= \sum_{r \in \cR} p_r \ket{A', a' \oplus v_{A'}(s'; r)}_q\bra{A, a \oplus v_{A}(s'; r)}_q
\end{align*}
which would then imply that
\begin{align*}
    &\rho^{adv, F}_s\vert_{a,a',A,A'} = \sum_{\substack{x, x' \in \cX}} \alpha_{x',A',a'}^* \: \alpha_{x,A,a} \: \ket{x'}_e\bra{x}_e \otimes \sum_{r \in \cR} p_r \ket{A', a' \oplus v_{A'}(s; r)}_q\bra{A, a \oplus v_{A}(s; r)}_q \\
    &= \sum_{\substack{x, x' \in \cX}} \alpha_{x',A',a'}^* \: \alpha_{x,A,a} \: \ket{x'}_e\bra{x}_e \otimes \sum_{r \in \cR} p_r \ket{A', a' \oplus v_{A'}(s'; r)}_q\bra{A, a \oplus v_{A}(s'; r)}_q = \rho^{adv, F}_{s'}\vert_{a,a',A,A'}.
\end{align*}
Observe that since we fixed arbitrary values for terms $s \in \bbS$, $a, a' \in \zo^t$, and $A,A' \in F$, the above argument will follow for any value. 

Furthermore, by our definition in Equation~\ref{eqn:fins}, we have for all $s, s' \in \bbS$
\begin{align*}
    \rho^{adv, F}_s &= \sum_{\substack{a, a' \in \zo^t\\ A, A' \in F}}\rho^{adv, F}_s\vert_{a,a',A,A'} = \sum_{\substack{a, a' \in \zo^t\\ A, A' \in F}}\rho^{adv, F}_{s'}\vert_{a,a',A,A'} = \rho^{adv, F}_{s'}.
\end{align*}
Thus proving that $S$ will be secure against superposition $F$-attacks.
\end{proof} 


