		\begin{align}
			R= \sum\limits_{i=1}^{r-1} \frac{\binom{\Lambda-t_a}{i} \sum\limits_{j=0}^{r-i-1} (-1)^j \binom{\Lambda-t_a-i}{j} \binom{\binom{\Lambda-t_a-i-j}{r-i-j}}{t_p+1}}{\binom{\binom{\Lambda-t_a}{r}}{t_p} \binom{t_a+i}{t_a}},
