\subsection{Approximation error bounds via contour integration \label{s:contour}}

Remarkably, extremely simple bounds on the discrepancy between $\OrthP_{\I}$
and $\SymP$ can be stated in terms of the \Nystrom{} errors (\ref{eq:errors}),
as follows:

% \begin{restate}{theorem}{th:dissipative}{Error bound for compression of dissipative dynamics}{ThDissipative}
\label{th:dissipative:section}
\ThDissipative*

We turn to a sketch of the proof of the theorem. The full proof is
given in \Cref{si:thm}. Before giving the sketch we will
state three useful lemmas.

% \begin{restate}{lemma}{lem:contour0}{Contour integral identity}{LemContour}
\label{lem:contour0:section}
\begin{restatable}[Contour integral identity \ProofLink{lem:contour0}]{lemma}{LemContour} \label{lem:contour0}
    Suppose that $A \in \R^{k \times k}$ has eigenvalues in the strict right half-plane and $U \in \R^{n\times k}$ has orthonormal columns. Then 
    \begin{eqn}
        U e^{-A} U^\t = \frac{1}{2\pi i} \oint_{\Contour} e^{-1/z} \,  (z \Id - U A^{-1} U^\t )^{-1} \, \odif z
    \end{eqn}
    for any contour $\Contour$ in the strict right half-plane enclosing the eigenvalues of $A^{-1}$.
\end{restatable}

% \begin{restate}{lemma}{lem:refactor}{Refactoring identity}{LemRefactor}
\label{lem:refactor:section}
\begin{restatable}[Refactoring identity \ProofLink{lem:refactor}]{lemma}{LemRefactor} \label{lem:refactor}
Given symmetric positive definite $K$ and $V = \Orth(K_{:,\I})$, the following identity holds: 
\begin{eqn}
    \label{eq:refactor}
    K_{:,\I} \Ki K_{\I,:} =V(V^{\t} K^\Mo V)^\Mo V^{\t}.
\end{eqn}
\end{restatable}

% \begin{restate}{lemma}{lem:polebound}{Resolvent bound}{LemPolebound}
\label{lem:polebound:section}
\begin{restatable}[Resolvent bound \ProofLink{lem:polebound}]{lemma}{LemPolebound} \label{lem:polebound}
Let $A$ be a real symmetric matrix and $z\in\mathbb{C}$
with $\im(z)\ne0$. Then 
\begin{eqn}
    \snorm{(z\Id-A)^\Mo} \leq \Abs{\im(z)}^\Mo .
\end{eqn}
\end{restatable}

Now we are equipped to give the sketch of Theorem \ref{th:dissipative}.
\begin{proof}
[Proof sketch for Theorem \ref{th:dissipative}.] Fix $t>0$, and
consider a connected contour $\mathcal{C}$ in the strict right half-plane that encloses
the spectrum of $L^{-1} / t$. Note that consequently it also encloses the spectrum of  $(V^{\top} L V)^{-1} / t$. We will discuss further details of the choice
of contour in the full proof. (To enclose the spectrum it must thread between $1/ ( t \Vert L\Vert_2 )$
and the origin, but for technical reasons we will consider a limit
in which the contour touches the origin.)


\begin{figure}
    \centering
    \includegraphics[width=3.3in]{./figures/contour.pdf}
    \vspace{-0.1in}
    \caption{
        % \ML{notation fixed throughout paper. $\mathcal{C}(T,0)$ in our notation \Cref{eq:contourdef0}. The splitting of the crossbar is defined in \Cref{eq:verticalcontourAB}. The angled parts are just $\mathcal{C}_{1}$ (no A/B), the near vertical piece is $\mathcal{C}_{2A}$, the far vertical piece is $\mathcal{C}_{2B}$ (disconnected)}
    Illustration of our limiting contour in the complex plane.
    Eigenvalues of $K / t$ are depicted as circles on the positive real axis.
    The contributions of $\Contour_{2A}$ and $\Contour_{2B}$ asymptotically vanish.
    \label{fig:contour}
    }
\end{figure}


We will apply Cauchy's integral formula: 
\begin{equation}
e^{-s^{-1}}=\frac{1}{2\pi i}\oint_{\Contour} \frac{e^{-1/z}}{z-s}\,\odif z.\label{eq:cauchy}
\end{equation}
 Since the contour encloses the spectrum of $(L t)^{-1}$, by substituting
$s\leftarrow (L t)^{-1} $ we obtain \cite{Higham_2008} the following exact expression for $\SymP(t)=e^{-Lt}$:
\begin{eqn} \label{eq:int1}
    \SymP(t)=\frac{1}{2\pi i}\oint_{\Contour} e^{-1/z} \,  \FullRes(z) \,\odif z,
\end{eqn}
where we define the resolvent function:
\begin{eqn}
    \label{eq:full-resolvent}
    \FullRes(z) \Eq (z \Id - K / t)^\Mo
\end{eqn}
and recall that $K = L^{-1}$.

Meanwhile, applying \Cref{lem:contour0} with $A = (V^\t L V) t$ and $U=V$ implies that 
% we would like to think of $\OrthP_{\I}(t)=Ve^{-V^{\top}(K/t)^{-1}V}V^{\top}$
% as equal to $e^{-S^{-1}}$ where $S$ is the singular matrix: 
% \begin{eqn}\label{eq:Sdef}
% S=V\left[V^{\top}(K/t)^{-1}V\right]^{-1}V^{\top}.
% \end{eqn}
% Despite the fact that $S$ is singular, this assertion should be
% understood by viewing $e^{-s^{-1}}=0$ for $s=0^{+}$, so the matrix
% function $e^{-S^{-1}}$ preserves the null space $\mathrm{span}(V)^{\perp}$
% of the argument $S$. 
% Following this intuition by plugging $S$ in place of $s$ within Cauchy's integral formula (\ref{eq:cauchy}),
% we obtain 
\begin{eqn} \label{eq:int2}
    \OrthP_{\I}(t) = \frac{1}{2\pi i} \oint_{\Contour} e^{-1/z} \,  \OrthRes(z) \, \odif z,
\end{eqn}
where we define:
\begin{eqn} \label{eq:orth-resolvent}
    \OrthRes(z) \Eq \left( z \Id - V ( V^\top K^{-1} V )^{-1} V^\top / t \right) ^\Mo.
\end{eqn}
% The legality of this move is established in \Cref{lem:contour0}.
Note that by \Cref{lem:refactor}, we can
alternatively write 
\begin{eqn} \label{eq:orth-resolvent2}
\OrthRes(z) = \left( z \Id - (\Kn)/t \right) ^\Mo.
\end{eqn}

Now by subtracting (\ref{eq:int1}) and (\ref{eq:int2}) we
deduce: 
\begin{eqn}
    \Norms{\SymP(t)-\OrthP_{\I}(t)} \leq \frac{1}{2\pi}\oint_{\Contour} \Abs{e^{-1/z}}\, \Norms{\FullRes(z)-\OrthRes(z)} \, \Abs{\odif z}.\label{eq:intbound}
\end{eqn}
%  where $\Vert\,\cdot\,\Vert$ is either the spectral norm or the trace
% norm.

Then by factoring 
\begin{eqn}
    \FullRes(z)-\OrthRes(z) = \FullRes(z) \left[\OrthRes(z)^\Mo - \FullRes(z)^\Mo\right] \OrthRes(z),
\end{eqn}
 we can bound 
\begin{eqn}
    \Norms{\FullRes(z)-\OrthRes(z)} \leq \snorm{\FullRes(z)} \, \snorm{\OrthRes(z)} \, \Norms{\OrthRes(z)^\Mo-\FullRes(z)^\Mo},\label{eq:intbound2}
\end{eqn}
where in the ``$\, * \, $" case we have used the general inequality $\Vert A B \Vert_* \leq \Vert A \Vert_2 \, \Vert B \Vert_*$, which follows from H\"{o}lder's inequality for the Schatten norms. 
Now by Lemma \ref{lem:polebound}, we have that $\snorm{\FullRes(z)}, \snorm{\OrthRes(z)} \leq \Abs{\im(z)}^\Mo$,
and by \Cref{eq:full-resolvent} and \Cref{eq:orth-resolvent2}, we also have that  
\begin{eqn} 
    \Norms{\OrthRes(z)^\Mo-\FullRes(z)^\Mo} = \frac{1}{t} \Norms{K - \Kn} = \frac{\Eps}{t},
\end{eqn}
hence
\begin{eqn}\label{eq:resdiffbound0}
    \Norms{\FullRes(z)-\OrthRes(z)} \leq \frac{\Eps}{t  \,  \vert\im{(z)}\vert^2 }.
\end{eqn}

%  where $\ve=\Es,\En$ is the suitable \Nystrom{} error
% (\ref{eq:errors}), depending on our choice of norm.

Finally, (\ref{eq:intbound}) and (\ref{eq:resdiffbound0}) imply that
\begin{eqn}
    \Norms{\SymP(t)-\OrthP_{\I}(t)} \leq \frac{\Eps}{2\pi t}\oint_{\mathcal{C}}\,\Abs{e^{-1/z}} \,\Abs{\im(z)}^{-2}\, \Abs{\odif z}.
\end{eqn}
 Now the contour integrand is independent of the problem, and by making
a suitable limiting choice of contour (\Cref{fig:contour}, which encloses all of $\mathbb{R}^{+}$
in the limit), we can achieve the numerical value of $\frac{3\sqrt{3}}{2\pi}$. 
(Note that the singularity of $\Abs{\im(z)}^{-2}$ on the real
axis is cancelled by the zero of $\Abs{e^{-1/z}}$ provided that
our limiting contour passes through the real axis at the origin.)
\end{proof}



\subsection{Extension to non-\Nystrom{} approximation}\label{s:non-nystrom}
% \{Here just extend the orthogonal compression result to recurrent Markov chain.
% We just take the limit and, assuming the stationary distribution is in the space of the compression, it works straightforwardly.
% }

In the following result, we extend the low-rank approximation bound of \Cref{th:dissipative} to cover constructions in which $V$ is an arbitrary matrix with orthonormal columns, not necessarily constructed as $\Orth(K_{:,\I})$. It recovers \Cref{th:dissipative} as a special case.

\label{th:non-nystrom:section}
\begin{restatable}[Non-\Nystrom{} compression error]{Theorem 1A}{ThNonNystrom}\label{th:non-nystrom}
% \begin{theorem}[note = Non-\Nystrom{} compression error, manual-num=1A] \label{th:non-nystrom}
% \begin{theorem}[Non-interpolative Markov chain approximation] \label{th:non-interpolative-markov}
    % Let $L$ be recurrent, $K = L^+$. \ML{Skip}
    \hypertarget{link.Theorem1A}{} Let $L$ be positive definite, let $V$ have orthonormal columns, and define $\NoninterpolativeP(t) \Eq V \expt{(V^\t L V)} V^\t$. Then 
    \begin{eqn}
        \Norms{ \SymP(t) - \NoninterpolativeP(t)} \leq \frac{3 \sqrt{3}}{2 \pi} \frac{\Nus}{t},
    \end{eqn}
    where $\Nus \Eq \Norms{K - V (V^\t L V)^{-1} V^\t}$.
\end{restatable}
\begin{proof}
    The proof is exactly the same as that of \Cref{th:dissipative}, except that we carry forward the expression \Cref{eq:orth-resolvent}, rather than substituting \Cref{eq:orth-resolvent2}.
\end{proof}

In fact, we can extend Theorem \hyperlink{link.Theorem1A}{1A} further to the setting where $L$ is only positive semidefinite. Crucially, the columns of $V$ must contain the null space of $L$ in their span.

\label{th:non-nystrom-sing:section}
\begin{restatable}[Singular non-\Nystrom{} compression error \ProofLink{th:non-nystrom-sing}]{Theorem 1B}{ThNonNystromSing} \label{th:non-nystrom-sing}
% \begin{theorem}[Non-interpolative Markov chain approximation] \label{th:non-interpolative-markov}
    % Let $L$ be recurrent, $K = L^+$. \ML{Skip}
    \hypertarget{link.Theorem1B}{} Let $L$ be positive semidefinite, let $V$ have orthonormal columns which contain the null space of $L$ in their span, and define 
    $\NoninterpolativeP(t) \Eq V \expt{(V^\t L V)} V^\t$. Then 
    \begin{eqn}
        \Norms{ \SymP(t) - \NoninterpolativeP(t)} \leq \frac{3 \sqrt{3}}{2 \pi} \frac{\Nus}{t},
    \end{eqn}
    where $\Nus \Eq \Norms{K - V (V^\t L V)^{+} V^\t}$.
\end{restatable}

It is interesting to contrast Theorem \hyperlink{link.Theorem1B}{1B} with the developments of the following sections, which focus specifically on the scenario where $L$ is obtained from a reversible Markov chain and possesses a one-dimensional null space due to the stationary distribution. Since  $L^{-1}$ does not exist, it is not trivial to define a notion $\Eps$ of \Nystrom{} error in this setting. We will do so by defining $L_\gamma := L + \gamma \Id$ and considering the limiting \Nystrom{} approximation of $K_\gamma := L_\gamma^{-1}$ as $\gamma \ra 0$. However, note with caution that the limiting \Nystrom{} error $\Eps$ obtained as $\gamma \ra 0$ does \emph{not} coincide with $\Nus$ furnished by Theorem \hyperlink{link.Theorem1B}{1B} with $V := \lim_{\gamma \ra 0} \mathrm{orth}( [K_\gamma]_{:,\I} )$. Importantly, it is $\ve_*$ that can be controlled directly via column selection \cite{Fornace2024-column}. We still highlight Theorem \hyperlink{link.Theorem1B}{1B} as a potentially useful tool for alternative constructions of reduced Markov models that are not tied to the \Nystrom{} framework. Indeed, the partitioning approaches \cite{Valmari2010-simple,Derisavi2003-optimal} used in some constructions of MSMs could be used to produce $V$ with orthonormal columns.




