\subsection{Relating error bounds to autocorrelation}\label{s:untransformed}
% Finally, we show how norm bounds on the approximation of $\SymP (t)$ may be interpreted in terms of the original, untransformed Markov chain dynamics $\FullP (t)$.


Finally, we show how norm bounds on the approximation of $\SymP (t)$ may be interpreted in terms of the original, untransformed Markov chain dynamics $\FullP (t)$. 
Autocorrelation analysis (e.g., \cite{Park2017-fundamentals,Frenkel2023-understanding}) offers an elegant perspective.

Given dynamics $\FullP$, the autocorrelation of a function on the state space, viewed as a vector $f \in \R^n$, is defined by 
\begin{eqn} \label{eq:acorr}
A_{t}(f, \FullP) \Eq \Ex \lrs{f_{X_0} f_{X_t} \mid X_0 \sim \pi, \,  X_t \sim \FullP_{X_0,\,:\,}(t)}.
\end{eqn}
More generally, the autocorrelation of vector-valued function, viewed as a matrix $F \in \R^{n \times m}$ for arbitrary $m$, is defined by 
\begin{eqn} \label{eq:acorr2}
A_{t}(F, \FullP) \Eq \Ex \lrs{F_{X_0,\,:\,}^\t \, F_{X_t,\,:\,} \mid X_0 \sim \pi, \, X_t \sim \FullP_{X_0,\,:\,}(t)}.
\end{eqn}
Note that the output is an $m \times m$ matrix.

A more proper definition of autocorrelation should assume that the functions have zero mean with respect to the stationary distribution $\pi$, but the following proposition, which relates our symmetric approximation error to autocorrelation discrepancies, is invariant to such a shift.

\label{th:autocorrelation:section}
\begin{restatable}[Approximation of autocorrelation \ProofLink{th:autocorrelation}]{proposition}{ThAutocorrelation} \label{th:autocorrelation}
Given dynamics $\FullQ(t)$ which approximate $\FullP(t)$ with $\SymQ(t) \Eq \Diag(h) \FullQ(t) \DiagI(h)$:
\begin{eqn}
    \label{eq:autocorrelation}
    \snorm{\SymP(t) - \SymQ(t)} &= \sup_{f \in \R^n} \lrb{ \Abs{A_t(f, \FullQ) - A_t(f, \FullP)} \;:\; \norm{f}_\pi = 1}, \\
    \nnorm{\SymP(t) - \SymQ(t)} &= \sup_{m \leq n, \, F \in \R^{n\times m} } \lrb{ \nnorm{A_t(F, \FullQ) - A_t(F, \FullP)} \;:\; F^\t \Diag(\pi) F = \Id}.
\end{eqn}
\end{restatable}

% \noindent Therefore, \Cref{th:ortho-markov} provides norm bounds which are (1) tractable for analysis and (2) naturally interpretable in terms of the underlying Markov chain and its stationary distribution $\pi$.

