\subsubsection{Bounding obliqueness via probabilistic interpretation}

% \Cref{th:oblique-sum-bound} gives strong error bounds on the approximation of the process using nuclear or spectral norms $\Eps$ and $\Obs$.
% In \Cref{s:experiments} we show that these bounds are relatively tight in practice given prechosen $\I$.
% However, in order to target the selection of $\I$ itself, we would like to target solely $\Eps$ in algorithms.
Next we turn toward showing that the obliqueness $\On$ appearing in Theorem \hyperlink{Theorem3*}{3*} can be controlled in terms of the nuclear norm \Nystrom{} error $\En$. In the language of the \Cref{s:structure-preserving} introduction, this argument converts an \emph{a posteriori} bound (which is empirically quite tight, cf., \Cref{s:experiments}) with a somewhat looser but still quite functional \emph{a priori} bound that can be controlled via nuclear column selection (cf. \Cref{s:algs}).
We rely on probabilistic arguments to achieve this proof.

% Our argument bounding $\On$ in terms of $\En$ is dependent on the Markov chain interpretation of 
% This is by no means assured.
% For general symmetric positive semidefinite operators, such good behavior is non-existent.
% It is only the structure of the Laplacian that ensures the tightness between $\On$ and $\En$.


In \Cref{th:recurrent-obliqueness}, we compute $\On$ in closed form in terms of $K$.
To leverage this result, we define the $n \times n$ matrix $H$ of hitting times (also known as mean first passage times):
\begin{eqn} \label{eq:hitting-time-def}
    H_{i,j} \Eq \Ex(\tau_\lrb{j} \mid X_0 = i)
 = \Ex(\min \lrb{t: t \geq 0, \, X_t = j} \mid X_0 = i).
\end{eqn}
With this definition we can obtain a remarkably simple expression for $\On$:


\label{th:obliqueness-from-hitting:section}
\begin{restatable}[Obliqueness in terms of first passage times \ProofLink{th:obliqueness-from-hitting}]{proposition}{ThObliquenessFromHitting} \label{th:obliqueness-from-hitting}
    % Consider the committor $\Cu$ induced by a non-empty subset $\I$, and
    % Consider a reversible and recurrent Markov chain $\FullChain$ with stationary distribution $\pi$.
    % Let $\Cu$ be the committor (\Cref{th:committor}) such that the probability of $\FullChain$ starting at state $j$ reaching state $i$ before states $\Iminus{i}$ is $\Cu_{i,j}$.
    Given $\On$ as in \Cref{def:obliqueness} and $H$ as in \cref{eq:hitting-time-def}:
    % Let $H$ be the hitting time matrix of $\FullChain$, such that $H_{j,i}$ is the mean first passage time for $\FullChain$ to reach state $i$ after starting in state $j$ (for all $i,j \in \Indices$). Then:
    \begin{eqn} \label{eq:nuclear-using-hitting}
        \On = \Tr[H_{:,\I}^\t  \Diag(\pi) \Cu].
    \end{eqn}
\end{restatable}


Using \Cref{th:obliqueness-from-hitting} and further probabilistic arguments, we bound the obliqueness $\On$ in terms of the \Nystrom{} approximation error in the nuclear norm:
% \begin{restate}{proposition}{th:probabilistic-obliqueness-factor}{Probabilistic bound on obliqueness}
\begin{proposition}[Bounding obliqueness in terms of the \Nystrom{} approximation error]
\label{th:probabilistic-obliqueness-factor}
    Given a non-empty subset $\I$, $\En (\I)$ as in \Cref{def:markov-epsilon}, and $\On = \On (\I)$ as in \Cref{def:obliqueness}:
    \begin{eqn}
        \On (\I) \leq \Ia  \, \En(\I).
    \end{eqn}
\end{proposition}

\noindent Observe that \Cref{th:probabilistic-obliqueness-factor}, together with Theorem \hyperlink{Theorem3*}{3*}, yields \Cref{th:sp-nuclear-bound} immediately.

% We conclude this section with a sketch of the proof of \Cref{th:probabilistic-obliqueness-factor}.

\begin{proof}
In the proof, we tackle each of the $\Ia$ contributions to the trace in \cref{eq:nuclear-using-hitting} separately. 
Indeed, observe that it suffices to show that $H_{:,i}^\t \Diag(\pi) \Cu_{:,i} \leq \En (\I)$ for each $i \in \I$. Therefore fix $i \in \I$, and consider the ratio:   
\begin{eqn}
    \frac{H_{:,i}^\t \Diag(\pi) \Cu_{:,i}}{\En (\I)} = \frac{\sum_{k \in \Ic} \pi_k H_{k,i} \Cu_{k,i}}{\sum_{k \in \Ic} (L_{\Ic,\Ic}^\Mo)_{k,k}}, 
\end{eqn}
where the denominator on the right-hand side is an alternative expression for $\En (\I)$ derived using Schur complement identities in \eqref{eq:killed-epsilon}.
Then in turn it suffices to show that $\pi_k H_{k,i} \Cu_{k,i} \leq (L_{\Ic,\Ic}^\Mo)_{k,k}$ for any $k \in \Ic$.

Therefore fix $k \in \Ic$ as well as $i \in \I$. 
In fact, we will show that the stronger condition  
\begin{eqn} \label{eq:obliqueWTS}
    \frac{ {\pi_k (H_{k,i} + H_{i,k}) \Cu_{k,i}}}{ (L_{\Ic,\Ic}^\Mo)_{k,k} } \leq 1
\end{eqn}
holds using a probabilistic technique.

