    \centering
    \includegraphics[width=5.5in]{./figures/marked-probabilistic-proof.pdf}
    \caption{
        \label{fig:timeline-equivalence}
        Decomposition of a trajectory into cycles for example states $k \notin \I$ and $i \in \I$.
        The middle timeline depicts each jump in the Markov chain according to the state being jumped to, with $k$ annotated in black, $i \in \I$ in green, $\Iminus{i}$ in gray, and all other states unlabeled.
        Cycles corresponding to $k \ra \I \ra k$ are demarcated on the top in red, while
        cycles corresponding to $k \ra i \ra k$  are demarcated on the bottom in blue.
        Observe that endpoints of the latter comprise a subset of endpoints of the former.
        In \Cref{th:probabilistic-obliqueness-factor}, the average lengths and probabilities of these cycle types are exploited in order to bound the the obliqueness norm $\On$ in terms of the \Nystrom{} error $\En$.
        % \red{elaborate on ``first of'' explanation}
    }
\end{figure}

We will define two key stopping times. The first is $\tau_{ i\ra k }$, ``the first return to $k$ after reaching $i$'': 
\begin{eqn} \label{eq:i-cycle-stop}
    \tau_{ i\ra k } = \min\lrb{t: t \geq \tau_{\{i\}}, \, X_t = k }.
\end{eqn}
The second is $\tau_{ \I \ra k }$, ``the first return to $k$ after reaching any state in $\I$'':
\begin{eqn} \label{eq:I-cycle-stop}
    \tau_{ \I \ra k } = \min\lrb{t: t \geq  \tau_{\I} , \,  X_t = k }.
\end{eqn}

We will think about the conditional expectations of these quantities given $X_0 = k$, which are the expected lengths of cycles $k \ra i \ra k$ and $k \ra \I \ra k$, respectively. 
We can directly compute the first of these, also known as the commute time: 
\begin{eqn} \label{eq:i-cycle}
    \Ex_{k} ( \tau_{ i \ra k }  ) = H_{k,i} + H_{i,k},
\end{eqn}
where we use $\Ex_k$ going forward to denote the expectation conditioned on $X_0 = k$.

A direct consequence of the renewal-reward theorem (cf. \cite{Aldous1995-reversible}, Proposition~2.3 for a statement) is that 
\begin{eqn}\label{eq:renewalreward}
\Ex_k ( \, \text{total time spent in $k$ before \ensuremath{\tau_{ \I \ra k }}} \, ) = \pi_k \, \Ex_k ( \tau_{ \I \ra k }  ).
\end{eqn}
It is also useful to realize that the left-hand side can alternatively be written as 
\begin{eqn}\label{eq:expectationtexts}
    \Ex_k ( \, \text{total time spent in $k$ before leaving \ensuremath{\Ic}} \, ),
\end{eqn}
since the stopping time $\tau_{ \I \ra k }$ occurs upon the \emph{first} return to $k$ after hitting $\I$. Then \Cref{eq:expectationtexts} can be computed as 
\begin{eqn}\label{eq:RRRHS}
    \int_0^\infty \Id_{k,:} \, e^{R_{\Ic,\Ic}t} \, \Id_{:,k}\, \odif t= -(R_{\Ic,\Ic}^{-1})_{k,k}= (L_{\Ic,\Ic}^{-1})_{k,k},
\end{eqn}
which furnishes the identity 
\begin{eqn} \label{eq:exstop2}
    \Ex_k ( \tau_{ \I \ra k }  ) = \frac{(L_{\Ic,\Ic}^{-1})_{k,k}}{\pi_k}
\end{eqn}
via \Cref{eq:renewalreward}.

% On the other hand, we can equate $(L_{\Ic,\Ic}^\Mo)_{k,k} / \pi_k$ to the expectation of the duration of the cycle $k \ra \I \ra k$ defined by the stopping time ``the first return to $k$ after reaching any of $\I$'':
% \begin{eqn} \label{eq:I-cycle}
%     (L_{\Ic,\Ic}^\Mo)_{k,k} / \pi_k = \Ex(\min\lrb{t: t \geq s, X_t = k, s = \min\{s' : s'\geq 0, X_{s'} \in \I\}} \mid X_0 = k).
% \end{eqn}
% Equations \cref{eq:i-cycle} and \cref{eq:I-cycle} thus define two types of cycles, which both start and end at $k$.

Now we consider segmenting a long trajectory of $\FullChain$ into either type of cycle (\Cref{fig:timeline-equivalence}). Concretely we fix $X_0 = k$ and let $T$ denote a trajectory length. By defining the renewal process whose inter-renewal time is distributed as $\tau_{i \ra k}$, we can apply the elementary renewal theorem \cite{Ross1983} to deduce that (almost surely) 
\begin{eqn}\label{eq:renewal1}
    \lim_{T \ra \infty} \frac{\# (\text{cycles $k \ra i \ra k$})}{ T } = \frac{1}{\Ex_k (\tau_{i\ra k} ) },
\end{eqn}
where on the left-hand side we understand the numerator to indicate the number of cycles completed before time $T$. Similarly, 
\begin{eqn}\label{eq:renewal2}
    \lim_{T \ra \infty} \frac{\# (\text{cycles $k \ra \I \ra k$})}{ T } = \frac{1}{\Ex_k (\tau_{\I\ra k} )}
\end{eqn}
holds almost surely.

Then by combining \Cref{eq:renewal1}, \Cref{eq:renewal2}, \Cref{eq:i-cycle}, and \Cref{eq:exstop2}, we see that (almost surely)
\begin{eqn} \label{eq:renewallim}
    \lim_{T \ra \infty} \ \frac{\# (\text{cycles $k \ra \I \ra k$})}{\# (\text{cycles $k \ra i \ra k$})}  = \frac{\pi_k (H_{k,i} + H_{i,k})}{(L_{\Ic,\Ic}^\Mo)_{k,k}}.
\end{eqn}
Meanwhile, by the law of large numbers: 
\begin{eqn}\label{eq:lln}
    \lim_{T\ra\infty}\frac{\#(\text{cycles \ensuremath{k\ra\I\ra k} including \ensuremath{i} first from \ensuremath{\I})}}{\#(\text{cycles \ensuremath{k\ra\I\ra k})}}= \Prob_k ( \,  \text{hit $i$ first from $\I$} \, )  = \tilde{C}_{k,i},
\end{eqn}
where $\Prob_k$ denotes the expectation conditioned on $X_0 = k$.

Then by multiplying the limits \Cref{eq:renewallim} and \Cref{eq:lln}, we deduce that 
\begin{eqn}\label{eq:almostdone}
    \frac{\pi_k (H_{k,i} + H_{i,k}) \Cu_{k,i}}{(L_{\Ic,\Ic}^\Mo)_{k,k}} = \lim_{T \ra \infty} \frac{ \#(\text{cycles $k \ra \I \ra k$ including $i$ first from $\I$})}{ \#(\text{cycles $k \ra i \ra k$})}.
\end{eqn}
Note that the cycles $k \ra i \ra k$ can be put in bijection with the subset of cycles $k \ra \I \ra k$ that include $i$. Indeed, every cycle $k \ra i \ra k$ is composed of one or more cycles $k \ra \I \ra k$, and it is precisely the last of these which is a cycle $k \ra \I \ra k$ that includes $i$. (See \Cref{fig:timeline-equivalence} for illustration.) Therefore we can rewrite the right-hand side of \Cref{eq:almostdone} as 
\begin{eqn}\label{eq:done}
    \lim_{T \ra \infty} \frac{ \#(\text{cycles $k \ra \I \ra k$ including $i$ first from $\I$})}{ \#(\text{cycles $k \ra \I \ra k$ including $i$})}.
\end{eqn}
On the right-hand side, since cycles satisfying the numerator condition automatically satisfy the denominator condition, the ratio is at most one. 
This establishes \Cref{eq:obliqueWTS}, as was to be shown, and concludes the proof.
\end{proof}


