\ThDissipative*
\begin{Proof}{th:dissipative}
Given \Cref{lem:contour0}, the identities (\ref{eq:int1}) and (\ref{eq:int2}) from the proof sketch rigorously establish that 
\begin{eqn}
    \SymP(t)-\OrthP_{\I}(t) = \frac{1}{2\pi}\oint_{\Contour} e^{-1/z} \, [\FullRes(z)-\OrthRes(z) ] \, {\odif z} \label{eq:intboundrecap}
\end{eqn}
for any contour $\mathcal{C}$ enclosing the eigenvalues of $K/t$.

Now we turn to the choice of contour. For $\delta \geq 0$,
define the triangular contour $\mathcal{C}=\mathcal{C}(T,\delta)$
by 
\begin{eqn}\label{eq:contourdef0}
\mathcal{C}(T,\delta)=\underbrace{\{\delta+\alpha t+i\beta t\,:\,t\in[0,T]\}\cup\{\delta+\alpha t-i\beta t\,:\,t\in[0,T]\}}_{=:\,\mathcal{C}_{1}(T,\delta)}\cup\underbrace{\{\delta+T+is\,:\,s\in[-T,T]\}}_{=:\,\mathcal{C}_{2}(T,\delta)}.
\end{eqn}
Assume that $T> \Vert K\Vert_2 /t$ and $\delta < 1/(\Vert L \Vert_2 t )$ so that the contour encloses the spectrum
of $K/t$ as required. Ultimately we will take $T\ra\infty$ to get
an infinite V-shaped contour, and we will argue that the vertical
crossbar segment $\mathcal{C}_{2}$ yields only a vanishing contribution
in this limit. Here $\alpha,\beta>0$ and we assume $\alpha^{2}+\beta^{2}=1$
so that $t\mapsto\delta+\alpha t\pm i\beta t$ is an arc-length parametrization. Refer to \Cref{fig:contour} for an illustration of the ensuing developments.


It is useful to note that if we write $z=a+ib$ for $a,b\in\R$, then
\begin{equation}
\vert e^{-1/z}\vert=e^{-\frac{a}{a^{2}+b^{2}}}.\label{eq:expidentity}
\end{equation}
 In particular, we have $\vert e^{-1/z}\vert\leq1$ on all of our
contours.

Now we will make the following moves in order: 
\begin{enumerate}
\item Take the limit $\delta\ra0^{+}$ of our contour integral, yielding
an exact expression for $\SymP(t)-P_{\I}(t)$ as a contour integral
over $\mathcal{C}(T,0)$. (\emph{A priori}, to apply Cauchy's integral
formula we must avoid touching the origin with our contour due to
the essential singularity of $e^{-1/z}$ at $z=0$, but we will see
that the limiting contour integral is nonetheless well-defined.)
\item Take the limit $T\ra\infty$ and argue that the contribution of the
vertical crossbar segment $\mathcal{C}_{2}$ vanishes.
\end{enumerate}

By \eqref{eq:intboundrecap} for $\mathcal{C} = \mathcal{C}(T,\delta)$, we deduce by changing variables that 
\begin{align*}
{ \SymP(t)-P_{\I}(t) } & = \frac{1}{2\pi i}\oint_{\mathcal{C}(T,0)}  e^{-1/(z+\delta)}  \, [ \mathcal{Q}_t (z+\delta)-\mathcal{R}_{t}(z+\delta) ] \, {\odif z}.
\end{align*}
 Note that the integrand $I_{\delta}(z):= e^{-1/(z+\delta)}  \, [ \mathcal{Q}_t (z+\delta)-\mathcal{R}_{t}(z+\delta)]$
converges pointwise to $I_{0}(z)$ on $\mathcal{C}(T,0)$ as $\delta\ra0^{+}$,
where we interpret $I_{0}(0) = 0$. 
Moreover, $\vert e^{-1/(z+\delta)}  \vert$  and $\vert  (z+\delta)^{-1} e^{-1/(z+\delta)}  \vert$ are uniformly bounded over the contour, independently of $\delta > 0$ sufficiently small, so the dominated convergence
theorem guarantees that we can take the limit as $\delta\ra0^{+}$
inside the integral to establish: 
\begin{eqn}\label{eq:contourT0}
{ \SymP(t)-P_{\I}(t) } =\frac{1}{2\pi i}\oint_{\mathcal{C}(T,0)}  e^{-1/z} [ \mathcal{Q}_t (z)-\mathcal{R}_{t}(z)] \, \odif z.
\end{eqn}
This completes step (1).

Now we recapitulate \Cref{eq:resdiffbound0}, which was established rigorously in the proof sketch: 
\begin{eqn}\label{eq:resdiffbound0recap}
    \Norms{\FullRes(z)-\OrthRes(z)} \leq \frac{\Eps}{t  \, \vert\im{(z)}\vert^2 }.
\end{eqn}
By plugging into \Cref{eq:contourT0} after separating the $\mathcal{C}_{1}$ and
$\mathcal{C}_{2}$ components, we get the bound 
\begin{equation}
\Vert \SymP(t)-P_{\I}(t)\Vert_{\{2,*\}} \leq \frac{\ve_{\{2,*\}} }{2 \pi t}\,\oint_{\mathcal{C}_{1}(T,0)}\frac{\vert e^{-1/z}\vert}{\vert\im (z) \vert^{2}}\, \Abs{\odif z} +\frac{1}{2\pi}\oint_{\mathcal{C}_{2}(T,0)}\Vert \mathcal{Q}_t (z)-\mathcal{R}_{t}(z) \Vert_{\{2,*\}} \, \Abs{\odif z}.\label{eq:contourbound}
\end{equation}
 We can split the vertical crossbar contour $\mathcal{C}_{2}(T,0)$
into two pieces, 
\begin{eqn}\label{eq:verticalcontourAB}
\mathcal{C}_{2A}(T):=\{T+is\,:\,\vert s\vert\leq\sqrt{T}\},\quad\mathcal{C}_{2B}(T):=\{T+is\,:\,\vert s\vert\geq\sqrt{T}\},
\end{eqn}
 one near and far from the real axis. Since $\Vert \mathcal{Q}_t (z)\Vert,\Vert \mathcal{R}_{t}(z)\Vert=O(T^{-1})$
on $\mathcal{C}_{2}(T,0)$ and the $\mathcal{C}_{2A}(T)$ contour
is of length $O(\sqrt{T})$, the $\mathcal{C}_{2A}$ contribution
vanishes as $T\ra\infty$.

Meanwhile, we can bound the $\mathcal{C}_{2B}$ contribution using
our less trivial bound \Cref{eq:resdiffbound0recap}: 
\begin{align*}
\frac{1}{2\pi}\oint_{\mathcal{C}_{2B}(T)}\Vert \mathcal{Q}_t (z)-\mathcal{R}_{t}(z) \Vert_{\{2,*\}} \, \Abs{\odif z} & \leq \frac{\ve_{\{2,*\}}}{2\pi t}\int_{\mathcal{C}_{2B}(T)}\frac{1}{\vert\mathrm{Im}(z)\vert^{2}}\,\Abs{\odif z}.
\end{align*}
 Then compute 
\begin{eqn}\label{eq:C2Bint}
\int_{\mathcal{C}_{2B}(T)}\frac{1}{\vert\mathrm{Im}(z)\vert^{2}}\, \Abs{\odif z} =2\int_{\sqrt{T}}^{T}\frac{1}{s^{2}}\,ds=2\frac{\sqrt{T}-1}{T}\ra0
\end{eqn}
 as $T\ra\infty$, so the $\mathcal{C}_{2B}$ contribution vanishes
as well.

Therefore by taking the limit as $T\ra\infty$ of our bound (\ref{eq:contourbound}),
we deduce that 
\begin{equation}
\Vert \SymP(t)-P_{\I}(t)\Vert_{\{2,*\}} \leq \frac{\ve_{\{2,*\}} }{2 \pi t}\ \lim_{T\ra\infty}\oint_{\mathcal{C}_{1}(T,0)}\frac{\vert e^{-1/z}\vert}{\vert\im(z)\vert^{2}}\, \Abs{\odif z}.\label{eq:contourbound2}
\end{equation}
Note that for $z=\alpha t\pm i\beta t\in\mathcal{C}_{1}(T,0)$ where
$\alpha^{2}+\beta^{2}=1$, following (\ref{eq:expidentity}) we can
write 
\[
\frac{\vert e^{-1/z}\vert}{\vert\im(z)\vert^{2}}=\frac{e^{-\frac{\alpha}{t}}}{\beta^{2}\,t^{2}},
\]
 hence 
\[
\lim_{T\ra\infty}\oint_{\mathcal{C}_{1}(T,0)}\frac{\vert e^{-1/z}\vert}{\vert\im(z)\vert^{2}}\, \Abs{\odif z}=\frac{2}{\beta^{2}}\int_{0}^{\infty}\frac{e^{-\frac{\alpha}{t}}}{t^{2}}\, \Abs{\odif t} =\frac{2}{\alpha\beta^{2}}.
\]
 We want to optimize the last expression subject to $\alpha^{2}+\beta^{2}=1$.
The optimal choice is given by $\alpha=\frac{1}{\sqrt{3}}$, which
yields $\frac{2}{\alpha\beta^{2}}=3\sqrt{3}$.

Putting everything together in (\ref{eq:contourbound2}), we have
\[
\Vert \SymP(t)-P_{\I}(t)\Vert_{\{2,*\}} \leq\frac{3\sqrt{3}}{2\pi}\,\frac{\ve_{\{2,*\}} }{t}.
\]
This completes step (2) and concludes the proof.
\end{Proof}

