\subsection{Proofs of lemmas for Theorem \ref{th:dissipative} \label{si:lemmas}}

First we prove \Cref{lem:contour0}:

\LemContour*
\begin{Proof}{lem:contour0}
Let $\tilde{U}$ complete the columns of $U$ to an orthonormal basis of $\R^{n}$.
By considering blocks with respect to the $[U,\tilde{U}]$
basis, we can rewrite: 
% \begin{eqn}\label{eq:altersolve}
% (z \Id - V A^{-1} V^\t )^{-1} 
% =
% V\left(z\Id- A^{-1}\right)^{-1}V^{\top}+z^{-1}UU^{\top}.
% \end{eqn}
\begin{eqn} \label{eq:altersolve}
(z\Id-UA^{-1}U^{\top})^{-1} & \ \leftrightarrow \ \left(z\Id-\left[\begin{array}{cc}
A^{-1} & 0\\
0 & 0
\end{array}\right]\right)^{-1}\\
 & \ = \ \left[\begin{array}{cc}
(z\Id-A^{-1})^{-1} & 0\\
0 & z^{-1}\Id
\end{array}\right]\leftrightarrow U(z\Id-A^{-1})^{-1}U^{\top}+z^{-1} \tilde{U} \tilde{U}^{\top},
\end{eqn}
where we use ``$\leftrightarrow$'' to indicate the suitable changes of basis. 

By Cauchy's
integral theorem for matrices \cite{Higham_2008}, we have that  
\begin{eqn}\label{eq:cauchy1}
e^{-A}=\oint_{\mathcal{C}}e^{-1/z}\left(z\Id-A^{-1}\right)^{-1}\,\odif z.
\end{eqn}
 We also have that 
\begin{eqn}\label{eq:cauchy2}
\oint_{\mathcal{C}}e^{-1/z} \, z^{-1} \, \tilde{U} \tilde{U}^{\top}\,\odif z=0,
\end{eqn}
since $e^{-1/z}z^{-1}$ is holomorphic on the interior of $\mathcal{C}$.

Then by taking the contour integral of both sides of \Cref{eq:altersolve} against $e^{-1/z} \, \odif z$ and using \Cref{eq:cauchy1,eq:cauchy2}, we conclude the proof.
\end{Proof}


Then we prove Lemma \ref{lem:refactor}:

\LemRefactor*
\begin{Proof}{lem:refactor}
We will prove a more general result.
Let $X$ be a tall rectangular matrix of full rank, and let $V=KX(X^{\top}K^{2}X)^{-1/2}$.
Expanding,
\[
V^{\top}K^{-1}V=(X^{\top}K^{2}X)^{-1/2}(X^{\top}KX)(X^{\top}K^{2}X)^{-1/2},
\]
 hence 
\[
(V^{\top}K^{-1}V)^{-1}=(X^{\top}K^{2}X)^{1/2}(X^{\top}KX)^{-1}(X^{\top}K^{2}X)^{1/2},
\]
 and in turn 
\[
V(V^{\top}K^{-1}V)^{-1}V^{\top}=KX(X^{\top}KX)^{-1}X^{\top}K.
\]
The desired statement in \cref{eq:refactor} follows from the choice of $X \Eq \Id_{:,\I}$.
\end{Proof}

Then to prove Lemma \ref{lem:polebound}, we first prove an even simpler
lemma.
\begin{lemma}
Let $B$ be a real symmetric matrix. Then $\Vert(\Id-iB)^{-1}\Vert_2 \leq1$. 
\end{lemma}
\begin{proof}
$\Id-iB$ is not Hermitian, but it is a normal operator (i.e.,
it commutes with its adjoint $\Id+iB$). Therefore $\Id-iB$
can be unitarily diagonalized by the spectral theorem, and it follows
that $\Vert(\Id-iB)^{-1}\Vert_2 $ is the spectral radius of $(\Id-iB)^{-1}$.
Since $B$ is real symmetric, the eigenvalues of $(\Id-iB)^{-1}$
all have the form $(1-i\lambda)^{-1}$, where $\lambda\in\R$ is an
eigenvalue of $B$. For any such $\lambda$, we have $\vert(1-i\lambda)^{-1}\vert=\vert1-i\lambda\vert^{-1}\leq1$.
\end{proof}

Then Lemma \ref{lem:polebound} is restated and proved as follows.

\LemPolebound*
\begin{Proof}{lem:polebound}
Write $z=a+ib$ and unpack: 
\begin{align*}
(z\Id-A)^{-1} & =(ib\Id+a\Id-A)^{-1}\\
 & =\frac{1}{ib}(\Id-ib^{-1}[a\Id-A])^{-1},
\end{align*}
 so the desired conclusion follows from the preceding lemma.
\end{Proof}

\subsection{Proof of Theorem 1B}

\ThNonNystromSing*
\begin{Proof}{th:non-nystrom-sing} 
    Let $\Pi$ be the orthogonal projector onto the null space of $L$, and define $L^{(\gamma)} := L + \gamma \Pi$ for $\gamma > 0$. Then $L^{(\gamma)}$ is positive definite, and we can further define $K^{(\gamma)} := [L^{(\gamma)}]^{-1} = K + \gamma^{-1} \Pi$. Moreover, define ${P}^{(\gamma)} (t) := e^{-L^{(\gamma)} t}$ and 
    $\tilde{P}^{(\gamma)}(t) := V e^{- (V^\t L^{(\gamma)} V) t} V^\t$. Then 
    Theorem \hyperlink{link.Theorem1A}{1A} implies that 
    \begin{eqn}
        \Norms{ \SymP^{(\Kill)}(t) - \tilde{\SymP}^{(\Kill)}(t) } \leq \frac{3 \sqrt{3}}{2 \pi} \Nus^{(\Kill)}
    \end{eqn}
    where $\Nus^{(\Kill)} := \Norms{K^{(\gamma)} - V (V^\t L^{(\gamma)} V)^\Mo V^\t}$. 

    Evidently, for any $t\geq 0$, both ${P}^{(\gamma)} (t) \ra {P} (t)$ and $\tilde{P}^{(\gamma)}(t) \ra \tilde{P}(t)$ as $\gamma \ra 0$. Therefore it suffices to show that 
    \begin{eqn}
        \lim_{\Kill \ra 0} \Nus^{(\Kill)} =  \Nus.
    \end{eqn}

    Now since the columns of $V$ contain the null space of $L$, it follows that  $VV^\t \Pi = \Pi  VV^\t = \Pi$. It also follows that $V^\t \Pi V$ is the orthogonal projector onto the the null space of $V^\t L V$, so in turn  $(V^\t L V)^+ = (V^\t L V + \Kill V^\t \Pi V )^\Mo - \Kill^\Mo V^\t \Pi V$ for any $\Kill > 0$. We can use these facts to compute: 
    \begin{eqn}
        \lim_{\Kill \ra 0} \left[ K^{(\gamma)} - V (V^\t L^{(\gamma)} V)^\Mo V^\t \right] &= \lim_{\Kill \ra 0} \left[   K + \Kill^\Mo \Pi - V ( V^\t [L + \Kill \Pi ] V)^\Mo V^\t \right] \\   
         &= \lim_{\Kill \ra 0} \left[   K - V \left\{  ( V^\t [L + \Kill \Pi ] V)^\Mo - \gamma^{-1} V^\t \Pi V \right\} V^\t \right] \\   
        &= \lim_{\Kill \ra 0} \left[   K - V (V^\t L V)^+ V^\t \right] \\    
        &=  K - V (V^\t L V)^+ V^\t.
    \end{eqn}
    By taking norms we complete the proof.
\end{Proof}

