\subsection{Closed-form expressions using the fundamental matrix}

In the next proposition, we provide a probabilistic proof of a closed form expression for the committor $\Cu$ induced by states $\I$ in terms of $K$, the pseudoinverse of $L$. An alternative linear-algebraic proof is sketched in the main text after the definition of the killed committor (\Cref{def:killed-committor}).

\begin{proposition}[Committor functions from fundamental matrix] \label{th:committor}
    For a reversible Markov chain associated to Laplacian $L$, fundamental matrix $K \Eq L^+$, and non-empty set $\I \subset \Indices$:
    \begin{eqn}
        \Cu = \DiagI(h) \lrp{\frac{h - K_{:,\I} \Ki \hi}{\hi^\t \Ki \hi} \hi^\t + K_{:,\I}} \Ki \Diag(\hi).
        \label{eq:committor}
    \end{eqn}
    The stationary expectation of the committor is:
    \begin{eqn}
        \pr = \Cu^\t \pi = \frac{\hi^\t \Ki \Diag(\hi)} {\hi^\t \Ki \hi}.
        \label{eq:committor-pi}
    \end{eqn}
\end{proposition}
\begin{proof}
\newcommand{\TimeToI}[1]{H^{\I}_{#1}}
Let $S \Eq \DiagI(h) K \DiagI(h)$.
Since $K$ is symmetric and $K h = \Zero$, $S$ is symmetric and $S \pi = \Zero$ (recall $\pi = h^{2}$).
Let $\TimeToI{j} = \Ex[\tau_{\I} \mid X_0 = j]$ be the average time for the Markov chain starting in state $j$ to first reach any of $\I$ (so that $\TimeToI{j} = 0$ for $j \in \I$), $H_{i,j} = \Ex[\tau_\lrb{j} \mid X_0 = i]$ be the average time for the Markov chain starting in state $i$ to reach state $j$, and $T^{k}_{i,j}$ be the average time spent in state $k$ for the Markov chain in state $i$ run until reaching state $j$. 
%

For any $j \in \Indices$, we will next consider the path starting at $j$ with stopping time ``the first return to $j$ after hitting any one of $\I$''(a path $j \ra \I \ra j$) in order to establish a linear system yielding $\Cu$.
To proceed, for any $i \in \I$,
% Let $H_{k,j}$ be the mean hitting time from $k$ to $j$ and $\E_k(t_i \text{ before } T_j)$ \ML{What is $t_i$?} be the expected time the random walk from $k$ spends in $i$ before first reaching $j$.
application of Proposition~2.3 of \cite{Aldous1995-reversible} yields:
%
\begin{eqn}
    \label{eq:committor-measure}
    \p_i \pp{\TimeToI{j} + \sum_{k \in \I} \Cu_{j,k} H_{k,j}}
    &= \sum_{k \in \I} \Cu_{j, k} T^i_{k, j}
\end{eqn}
%
where the left-hand side is the expected duration of such a path (weighted by $\p_i$), and the right-hand side is the expected occupancy time in $i$ of such a path.\footnote{
We can explain the intuition in more detail. 
Consider an infinitely long trajectory of the Markov chain from a stationary start and break it into intervals based on the cycles as defined ($j \ra \I \ra j$).
The average time of such a cycle is $\TimeToI{j}$ plus the sum over $k \in \I$ of $H_{k,j}$, weighted by the probability that $k$ was the first state in $\I$ encountered (i.e., the committor).
Meanwhile, the time spent in $i$ during such a cycle is just the sum over $k \in \I$ of $T^i_{k, j}$ weighted by the committor, because no time is spent in $i$ before reaching $\I$, by definition.
Now, the fraction of time spent in $i$ for an infinitely long trajectory must just be $\pi_i$, so multiplying the average cycle time by $\pi_i$ must be the same as the average time spent in $i$ during such a cycle, giving \cref{eq:committor-measure}.
}
\cref{eq:committor-measure} gives us one equation involving the unknown probabilities $\Cu_{j,:}$ for each $i \in \I$ with $\TimeToI{j}$ as an additional unknown.

Now, substitute $H_{i,j} = S_{j,j} - S_{i,j}$ (\cite{Aldous1995-reversible}, Lemma~2.12) and $T^i_{k, j} = \pi_i (S_{j,j} - S_{k,j} - S_{j,i} + S_{k,i})$ (\cite{Aldous1995-reversible}, Lemma~2.9) to find that:
%
\begin{eqn}
    \label{eq:committor-column-i}
    \TimeToI{j} + \sum_{k \in \I} \Cu_{j,k} (S_{j,j} - S_{k,j}) &=
    \sum_{k \in \I} \Cu_{j,k} (S_{j,j} - S_{k,j} - S_{j,i} + S_{k,i}). \\
\end{eqn}
By collecting equations \cref{eq:committor-column-i} for each $i \in \I$ and simplifying, we find:
\begin{eqn}
    (\TimeToI{:}) \One^\t &= \Cu S_{\I, \I} - S_{:,\I}.
  \label{eq:committor-system}
\end{eqn}
%
For each $j \in \Indices$, this provides $\Ia$ equations for the $\Ia+1$ unknowns $\Cu_{j,:}$ and $\TimeToI{j}$.
Another constraint is gained from normalization of probability,
%
% \begin{eqn}
  $\Cu \One = \One$,
%   \label{eq:committor-system-b}
% \end{eqn}
%
such that solving the system of equations gives:
% Then the expectation of the first passage time from state $j$ to reach any of $\I$ is:
%&= \p_i^{-1} \frac{\p_i - \G_{i, \I} \G_{\I,\I}^{-1} \p}{\p^\t \G_{\I,\I}^{-1} \p}
% \end{eqn}
% And the committor probability of reaching one state $i$ before any of $\Iminus i$ can be written as:
%
% \begin{eqn}
\begin{eqn}
    \Cu = \pp{\frac{\One -S_{:, \I} S_{\I, \I}^{-1} \One}{\One^\t S_{\I, \I}^{-1} \One} \One^\t + S_{:, \I}} S_{\I,\I}^{-1}, \qquad
    \TimeToI{:} = \frac{\One - S_{:, \I} S_{\I,\I}^{-1} \One}{\One^\t S_{\I,\I}^{-1} \One},
    \label{eq:committor-column}
\end{eqn}
which implies \cref{eq:committor} by substitution via the definition of $S$.
Finally, \cref{eq:committor-pi} follows from computation of $\Cu^\t \pi$ with simplifications since $S \pi = \Zero$.
\end{proof}


