\subsection{Analysis of killed chain and limit $\gamma \ra 0$}

In this section we detail how analysis of the killed chain leads to \Cref{th:projective-compression}. First, for motivation and future reference, we prove the probabilistic interpretation of the killed committor suggested in the main text. 
\newcommand{\Xa}{X^{\Kill}}
\begin{lemma}[Probabilistic interpretation of killed committor] \label{th:killed-committor-prob}
For $\Kill > 0$, consider the (irreversible) Markov chain on the space $[n]\cup \{x\}$, augmented by a single cemetery state $x$, with rate matrix given by
\begin{eqn}
    R^{(\Kill)} \Eq \begin{bmatrix}
        R - \Kill \Id & \Kill \One \\
        \Zero & 0
    \end{bmatrix}.
\end{eqn}
Let $\Process{\Xa}$ be the associated stochastic process with initialization $\Xa_0 \sim [\pi^\t, 0]^\t$.
Then for any $i \in \Indices$, $j \in \I$, and with $\Cu_{\Kill}$ as in \Cref{th:killed-committor}:
\begin{eqn} \label{eq:killed-committor-prob}
    (\Cu_{\Kill})_{i,j} = \Prob(\Xa_{\tau_{\I \cup \lrb{x}}} = j \mid \Xa_0 = i).
\end{eqn}
\end{lemma}
\begin{proof}
The probability evolution outside of $\I \cup \{ x \}$ is given by $\exp((R_{\Ic,\Ic} - \gamma \Id) t)$, while the rates of entering the selected states from unselected states are $R_{\Ic,\I}$.
Therefore the committor probability from any state $i \notin \I \cup \lrb{x}$ to any state $j \in \I$ is:
\begin{eqn}
    \Prob(\Xa_{\tau_{\I \cup \lrb{x}}} = j \mid \Xa_0 = i) &= \int_0^\infty  \Id_{i,\Ic} \exp((R_{\Ic, \Ic} - \Kill \Id)t) R_{\Ic, j} \odif t \\
    &= \Minus \Id_{i, \Ic} (R_{\Ic, \Ic} - \Kill \Id)^\Mo R_{\Ic, j} \\
    &= \Minus \frac{h_j}{h_i} \Id_{i, \Ic} ( (\La)_{\Ic,\Ic} )^\Mo (\La)_{\Ic, j} \\
    &= \frac{h_j}{h_i} (\Ka)_{i, \I} (\Ka)_{\I,\I}^\Mo \Id_{\I,j} \\
\end{eqn}
where the third line follows from the definition of $\La$, and the last line follows from the general identity $A_{\Ic,\Ic}^{-1} A_{\Ic,\I} = -B_{\Ic,\I} B_{\I,\I}^{-1}$ for arbitrary $A = B^{-1}$, which in turn can be seen from the block matrix inversion formula. 
Additionally, we know automatically that $\Prob(\Xa_{\tau_{\I \cup \lrb{x}}} = j \mid \Xa_0 = i) = \delta_{i,j}$ for any $i \in \I$. Therefore $\Prob(\Xa_{\tau_{\I \cup \lrb{x}}} = j \mid \Xa_0 = i)$ matches the $(i,j)$ entry of $\Cu_\Kill \Eq \Diag(1/h) (\Ka)_{:,\I} (\Ka)_{\I,\I}^\Mo \Diag(\hi)$ (\Cref{def:killed-committor}) for all $i \in [n]$ and $j \in \I$, as was to be shown.
\end{proof}



