\subsection{Relating symmetric and asymmetric approximations}

\ThAutocorrelation*
\begin{Proof}{th:autocorrelation}
Given the definition of autocorrelation \cref{eq:acorr,eq:acorr2}, since the initial state $X_0$ is sampled out of $\pi$, we compute: 
\begin{eqn}
    A_t(f, \FullP) &= f^\t \Diag(\pi) \FullP(t) f = f^\t \Diag(h) \SymP(t) \Diag(h) f, \\
    A_t(F, \FullP) &= F^\t \Diag(\pi) \FullP(t) F = F^\t \Diag(h) \SymP(t) \Diag(h) F.
\end{eqn}
Analogous relations hold for $\FullQ$, $\SymQ$.

From standard properties of the spectral norm:
\begin{eqn}
    \snorm{\SymP(t) - \SymQ(t)} &= \sup_{g \in \R^n} \lrb{ \Abs{g^\t (\SymP(t) - \SymQ(t)) g} \;:\; \norm{g}_2 = 1}
\end{eqn}
and \cref{eq:acorr} follows from defining $f \Eq \DiagI(h) g$.

Next we consider the nuclear norm bound. Note that for $m \leq n $ and a general  matrix $G \in \R^{n \times m}$ satisfying $G^\t G = \Id$, we have (by considering the SVD) that $\Vert G \Vert_2 = 1$, and therefore $\Vert G^\t A G \Vert_* \leq \Vert A \Vert_*$ for any $A \in \R^{n\times n}$ by H\"{o}lder's inequality for the Schatten $p$-norms. Moreover, equality is attained by simply taking $G = \Id$. Therefore, by substituting $A = P(t) - Q(t)$, we deduce that 
\begin{eqn}
    \nnorm{\SymP(t) - \SymQ(t)} &= \sup_{m \leq n, \, G \in \R^{n\times m} } \lrb{ \nnorm{G^\t (\SymP(t) - \SymQ(t)) G} \;:\; G^\t G = \Id}.
\end{eqn}
and \cref{eq:acorr2} follows from defining $F \Eq \DiagI(h) G$.
\end{Proof}








