\subsection{Induced chain formulation}

\newcommand{\DiagRat}[2]{\Diag\lrp{\tfrac{#1}{#2}}}

\begin{lemma}[Marking time from a stationary start] \label{th:timescale}
    The time to get to $\I$ from a stationary start satisfies:
    \begin{eqn}
        \Ex[\tau_{\I}] = (\hi^\t \Ki \hi)^\Mo.
    \end{eqn}    
\end{lemma}
\begin{proof}
    Trajectories starting in $\I$ contribute 0 to this expectation, whereas the probability distribution of the chain started in $\Ic$ and run until reaching $\I$ is governed by $R_{\Ic,\Ic}$.
    Therefore we compute:
    \begin{eqn}
        \Ex[\tau_{\I}] = \int_0^\infty \pi_{\Ic}^\t \ert{R_{\Ic,\Ic}} \One_{\Ic} \odif t 
        &= -\pi^\t_{\Ic} R_{\Ic,\Ic}^\Mo \One_{\Ic}
        = h_{\Ic}^\t L_{\Ic,\Ic}^\Mo h_{\Ic}.
    \end{eqn}
    Then we derive that $h_{\Ic}^\t L_{\Ic,\Ic}^\Mo h_{\Ic} = (\hi^\t \Ki \hi)^\Mo$ by Schur complement computations.
\end{proof}
\noindent We henceforth define for convenience:
\begin{eqn} \label{eq:omega}
    \TimeScale \Eq \Ex[\tau_{\I}] = (\hi^\t \Ki \hi)^\Mo.
\end{eqn}

\begin{proposition}[Induced chain in terms of fundamental matrix] \label{th:induced-from-k}
    Given the definitions in \Cref{eq:reduced-h-L-K} and \Cref{eq:simple-induced}, in the unsymmetrized rate matrix formulation, we derive that:
    \begin{eqn} \label{eq:induced-R-from-K}
        \pr &= \TimeScale \Diag(\hi) \Ki \hi, \\
        \Rr &= \TimeScale^\Mo \One \pr^\t - \DiagRat{\hi}{\pr} \Ki \Diag(\hi).
    \end{eqn}
    In the symmetrized formulation, letting $\hr = \pr^\Oh$:
    \begin{eqn}
        \Lr &= \DiagRat{\hi}{\hr} \Ki \DiagRat{\hi}{\hr} - \TimeScale^\Mo \hr \hr^\t, \\
        \Kr &= \DiagRat{\hr}{\hi} K_{\I,\I} \DiagRat{\hr}{\hi} - \TimeScale \hr \hr^\t.
    \end{eqn}
    $\Lr$ and $\Kr$ are symmetric matrices with $\Kr = \Lr^+$.
\end{proposition}
\begin{proof}
    We first verify the formula for $\pr$:
    \begin{eqn}
        \pr &= \Cu^\t \pi = \Diag(\hi) \Ki \lrs{\frac{\hi (h^\t - \hi^\t \Ki K_{\I,:}) }{\hi^\t \Ki \hi} + K_{\I,:}} h
        = \frac{\Diag(\hi) \Ki  \hi}{\hi^\t \Ki \hi}
    \end{eqn}
    where the last equality follows from $K h = 0$ and $h^\t h = 1$.

    We next verify the formula for $\Lr$ following its definition \cref{eq:L-h-def} and $\TimeScale$ as above:
    \begin{eqn}
        \Lr &= \Co^\t L \Co \\
        &= \DiagRat{\hi}{\hr} \Ki \lrs{\frac{\hi (h^\t - \hi^\t \Ki K_{\I,:}) }{\hi^\t \Ki \hi} + K_{\I,:}} L \lrs{\frac{(h - K_{:,\I} \Ki \hi) \hi^\t}{\hi^\t \Ki \hi} + K_{:,\I}} \Ki \DiagRat{\hi}{\hr} \\
        &= \DiagRat{\hi}{\hr} \Ki \DiagRat{\hi}{\hr} - (\hi^\t \Ki \hi) \hr \hr^\t
    \end{eqn}
    where simplifications are yielded by considering that $L h = 0$ and $K L K = K$.
    The formula for $\Rr$ is straightforwardly shown via the relation $\Rr = \Minus \DiagI(h) L \Diag(h)$.

    Finally, we verify the formula for $\Kr$ by showing:
    \begin{eqn}
        \Lr \Kr &= \lrs{\DiagRat{\hi}{\hr} \Ki \DiagRat{\hi}{\hr} - (\hi^\t \Ki \hi) \hr \hr^\t} \lrs{\DiagRat{\hr}{\hi} K_{\I,\I} \DiagRat{\hr}{\hi} - (\hi^\t \Ki \hi)^\Mo \hr \hr^\t} \\
        &= \Id - \hr \hr^\t,
    \end{eqn}
    implying that $\Kr = \Lr^+$ since $\hr$ is the zero eigenvector of $\Lr$.
\end{proof}

