\ThInducedBasics*
\begin{Proof}{th:induced-basics}
    First, reversibility is implied since the matrix
    \begin{eqn} \label{eq:diagpiR}
        \Diag(\pr) \Rr = \Cu^\t \Diag(\pi) R \Cu
    \end{eqn}
    is symmetric and negative semidefinite by inspection. 
    (Recall that the original chain being reversible implies that $\Diag(\pi) R$ is symmetric and negative semidefinite.)
    Therefore $\Rr$ has nonpositive eigenvalues.

    We next verify that $\pr$ does in fact define the stationary distribution, recalling that $\pr \Eq \Cu^\t \pi$. 
    By the probabilistic formulation of $\Cu$ \cref{eq:committor-prob-def},
    \begin{eqn}
        \pr_i = \sum_{k \in \Indices} \Prob(X_{\tau_{\I}} = i \mid X_0 = k) \pi_k.
    \end{eqn}
    Therefore $\pr_i > 0$ for all $i \in \I$, and, since $\Cu \One = \One$, moreover we have that $\One^\t \pr = 1$.
    Again using $\Cu \One = \One$ and the stationarity of the original rate matrix $R$, we compute:
    \begin{eqn}
        \Rr \One &= \DiagI(\pr) \Cu^\t \Diag(\pi) R \Cu \One = \Cu^\t \Diag(\pi) R \One = \Zero \\
        \Rr^\t \pr &= \Cu^\t R^\t \Diag(\pi) \Cu \DiagI(\pr) \pr = \Cu^\t R^\t \Diag(\pi) \Cu \One = \Cu^\t R^\t \pi = \Zero,
    \end{eqn}
    verifying that $\pr$ is the stationary distribution and moreover that $\Rr \One  = \Zero$.

    Next, we establish that the offdiagonal elements are nonnegative, i.e., $\Rr_{i,j} \geq 0$ for all $i \neq j$.
    By \Cref{eq:diagpiR}, it suffices to prove the same about the matrix $\Cu^\t \Diag(\pi) R \Cu$.
    By \cref{eq:laplace-equation}, for any $i \in \I$, $\Delta \Cu_{:,i} = \Minus \Diag(\pi) R \Cu_{:,i}$ is zero on all rows except $\I$. 
   Then 
    \begin{eqn}
        \Cu^\t \Diag(\pi) R \Cu = \Cu^\t \Id_{:, \I} \Id_{\I, :} \Diag(\pi) R \Cu = \Diag(\pi_{\I}) R_{\I,:} \Cu, 
    \end{eqn}
    where we have additionally used the identity that $\Id_{\I,:}\Cu = \Cu_{\I,:} = \Id$.
    Therefore it suffices to show that $R_{i,:} \Cu_{:,j} \geq 0$ for all $i,j \in \I, i \neq j$.
    Using the fact that the rows of $R$ sum to 0, we compute that
    \begin{eqn}
        R_{i,:} \Cu_{:,j} = \sum_{k \neq i} R_{i,k} (\Cu_{k,j} - \Cu_{i,j}) = \sum_{k \neq i} R_{i,k} \Cu_{k,j}
    \end{eqn}
    where the last equality follows from $\Cu_{i,j} = 0$, since $\Prob(X_{\tau_{\I}} = i \mid X_0 = i) = 1$.
    The final right-hand side is nonnegative since (1) $R_{i,k} \geq 0$ for any $i \neq k$ by the definition of the original chain's rate matrix and (2) $\Cu$ is entrywise nonnegative via its probabilistic definition.

    To guarantee irreducibility, consider that $\Cu_{k,i}$ is positive for all states $k \in \Indices$ which connect to $i$ via a path not involving $\Iminus{i}$.
    Therefore $\Rr_{i,j}$ is nonzero for any $i \neq j$ where $i$ and $j$ are connected in the adjacency graph of $R$ by a path not involving $\I \setminus \lrb{i,j}$.
    Thus $i$ and $j$ are connected in $\Rr$ if there is any path connecting them in the adjacency graph of $R$.
    Considering that the adjacency graph of $R$ is connected (since $R$ is irreducible), then it follows that the adjacency graph of $\Rr$ must be connected. 
    Therefore $\Rr$ is irreducible.

    Given that $\Rr$ is irreducible, the stationary distribution is unique.
    Together with the negative semidefiniteness of $\Diag(\pr) \Rr$, this implies that the diagonal of $\Diag(\pr) \Rr$ (and therefore $\Rr$) is strictly negative.
\end{Proof}

\ThInducedInterpretation*
\begin{Proof}{th:induced-interpretation}
    For claim 1, we compute:
    \begin{eqn}
        \Prob(\tau_{\Iminus{i}} > t \mid X_0 = i) = \Id_{i,:} \Ert{R_{\Ic \cup \lrb{i},\Ic \cup \lrb{i}}} \One.
    \end{eqn}
    It simplifies the linear algebra to express this quantity as the limit:
    \begin{eqn}
        \Prob(\tau_{\Iminus{i}} > t \mid X_0 = i) = \lim_{\beta \ra 0} \Id_{i,:} \Ert{(R - \beta \One \pi^\t)_{\Ic \cup \lrb{i},\Ic \cup \lrb{i}}} \One.
    \end{eqn}
    Then by \Cref{lem:expalpha}, we express the expected time via a limit $\alpha \ra \infty$ of a perturbed probability evolution where the chain is killed instantly on reaching $\Iminus{i}$.
    Given this approach, the probability of the chain not having reached $\Iminus{i}$ at time $t$ is: 
    \begin{eqn}
        \Prob(\tau_{\Iminus{i}} > t \mid X_0 = i) = \lim_{\Shift \ra 0} \lim_{\alpha \ra \infty} \Id_{i,:} \Ert{(R - \Shift \One \pi^\t - \alpha \Id_{:,\Iminus{i}} \Id_{:,\Iminus{i}}^\t)} \One.
    \end{eqn}
    So, integrating to find the expected lifetime of such a process:
    \begin{eqn}
        \Ex(\tau_{\Iminus{i}} \mid X_0 = i) &= \lim_{\Shift \ra 0} \lim_{\alpha \ra \infty} \int_0^\infty \Id_{i,:} \Ert{(R - \Shift \One \pi^\t - \alpha \Id_{:,\Iminus{i}} \Id_{:,\Iminus{i}}^\t)} \One \odif t.
    \end{eqn}
    Then we compute the right-hand integral for finite $\Shift > 0$ and $\alpha > 0$ to find that:
    \begin{eqn}
        \Ex(\tau_{\Iminus{i}} \mid X_0 = i) &= \lim_{\Shift \ra 0} \lim_{\alpha \ra \infty} \Minus \Id_{i,:} (R - \Shift \One \pi^\t - \alpha \Id_{:,\Iminus{i}} \Id_{:,\Iminus{i}}^\t)^\Mo \One \\
        &= \lim_{\Shift \ra 0} \lim_{\alpha \ra \infty} h_i^\Mo \Id_{i,:} (L + \Shift h h^\t + \alpha \Id_{:,\Iminus{i}} \Id_{:,\Iminus{i}}^\t)^\Mo h
    \end{eqn}
    where the last line follows from the definition of $L$, $h$, and $\pi$.
    Next, let $\Kb \Eq (L + \Shift h h^\t)^\Mo = K + \Shift^\Mo h h^\t$. 
    Then, by use of the Woodbury matrix identity, we find that:
    \newcommand{\Kbi}{((\Kb)_{\I,\I}^\Mo)}
    \begin{eqn} \label{eq:Rii-shift-limit}
        \Ex(\tau_{\Iminus{i}} \mid X_0 = i) &= \lim_{\Shift \ra 0} \frac{h^\t (\Kb)_{:,\I} \Kbi_{:,i} }{h_i \Kbi_{i,i}}.
    \end{eqn}
    Invoking the Sherman-Morrison formula and taking the limit $\Shift \ra 0$, we compute that:
    \begin{eqn}
        \Ex(\tau_{\Iminus{i}} \mid X_0 = i) &= h_i^\Mo \lrp{ \Ki \hi - \frac{(\hi^\t \Ki \hi) (\Ki)_{i,i}}{(\Ki)_{i,:} \hi} }^\Mo \\
        &= \Mo / \Rr_{i,i}
    \end{eqn}
    with the last line following by comparison to \cref{eq:induced-R-from-K} in \Cref{th:induced-from-k}.

    For claim 2, we use the same limiting approach, but now we measure the accumulated flux of the perturbed chain into states $\Iminus{i}$ by the following integral:
    \begin{eqn}
        \Prob(X_{\tau_{\Iminus{i}}} = j \mid X_0 = i) = \lim_{\Shift \ra 0} \lim_{\alpha \ra \infty} \int_0^\infty \Id_{i,:} \Ert{(R - \Shift \One \pi^\t - \alpha \Id_{:,\Iminus{i}} \Id_{:,\Iminus{i}}^\t)} (R - \Shift \One \pi^\t)_{:,j} \odif t
    \end{eqn}
    Again computing the integral, we compute that:
    \begin{eqn}
        \Prob(X_{\tau_{\Iminus{i}}} = j \mid X_0 = i) &= \lim_{\Shift \ra 0} \lim_{\alpha \ra \infty} 
            \Minus \Id_{i,:} \lrp{R - \Shift \One \pi^\t - \alpha \Id_{:,\Iminus{i}} \Id_{:,\Iminus{i}}^\t}^\Mo (R - \Shift \One \pi^\t)_{:,j} \\
            &= \lim_{\Shift \ra 0} \lim_{\alpha \ra \infty} \Minus \frac{h_j}{h_1} \Id_{i,:} \lrp{(L + \Shift h h^\t) + \alpha \Id_{:,\Iminus{i}} \Id_{:,\Iminus{i}}^\t}^\Mo (L + \Shift h h^\t)_{:,j}.
    \end{eqn}
    By further use of the Woodbury matrix identity, we find that:
    \begin{eqn}
        \Prob(X_{\tau_{\Iminus{i}}} = j \mid X_0 = i) &= \lim_{\Shift \ra 0} \Minus \frac{h_j \Kbi_{j,i}}{h_i \Kbi_{i,i}}
        % &= \lim_{\Shift \ra 0} \Minus \frac{h_j \Kbi_{j,i}}{h_i \Kbi_{i,i}}
    \end{eqn}
    so that by invoking \cref{eq:Rii-shift-limit},
    \begin{eqn}
        \Prob(X_{\tau_{\Iminus{i}}} = j \mid X_0 = i) &= \Minus \Rr_{i,i}^\Mo \lim_{\Shift \ra 0} \Minus \frac{\Diag(\hi) \Kbi_{:,i}}{h^\t (\Kb)_{:,\I} \Kbi_{:,i}}.
    \end{eqn}
    Then, evaluating the limit gives:
    \begin{eqn}
        \Prob(X_{\tau_{\Iminus{i}}} = j \mid X_0 = i) &= \Minus \Rr_{i,i}^\Mo \cdot h_j \lrp{ \Kbi_{j,:} \hi - \frac{\hi^\t (\Kb)_{\I,\I}^\Mo \hi}{\Kbi_{i,:} \hi} \Kbi_{i,j} }
        &=  \Minus \frac{\Rr_{i,j}}{\Rr_{i,i}}
    \end{eqn}
    with the last line again by comparing to entry $\Rr_{i,j}$ from \cref{eq:induced-R-from-K} in \Cref{th:induced-from-k}.

    Finally, for claim 3, we much more simply compute that:
    \begin{eqn}
        \pr_i = \sum_{j} \pi_j \Cu_{j,i} = \sum_{j} \pi_j \Prob(X_{\tau_{\I}} = i \mid X_0 = j) = \Prob(X_{\tau_{\I}} = i).
    \end{eqn}
\end{Proof}

\begin{corollary}[Preservation of mean first passage times] \label{th:hitting-times-preserved}
For states $i, j \in \I$, consider the mean first passage time for $\FullChain$ (respectively $\InducedChain$) started in $i$ to reach $j$ and denote it $H_{i,j}$ (respectively $\hat{H}_{i,j}$).
        % Consider the mean first passage time for the induced chain started in state $i$ to reach $j$, and denote this $\hat{H}_{i,j}$.
        Then $H_{i,j} = \hat{H}_{i,j}$.
\end{corollary}
\begin{proof}
    Let $S \Eq \DiagI(h) K \DiagI(h)$ and $\Sr \Eq \DiagI(\hr) \Kr \DiagI(\hr)$, where $\Kr \Eq \Lr^+$.
    Then from Lemma~2.12 of \cite{Aldous1995-reversible},
    \begin{eqn}
        H_{i,j} = S_{j,j} - S_{i,j}, \qquad \hat{H}_{i,j} = \Sr_{j,j} - \Sr_{i,j}.
    \end{eqn}
    Recalling our definition $\TimeScale := (\hi^\t \Ki \hi)^\Mo$ \Cref{eq:omega} and substituting the formula for $\Kr$ from \Cref{th:induced-from-k}:
    \begin{eqn}
        \Sr &= \DiagI(\hr) \lrs{\Diag(\hr / \hi) K_{\I,\I} \Diag(\hr / \hi) - \TimeScale \hr \hr^\t} \DiagI(\hr) \\
        &= \DiagI(\hi) K_{\I,\I} \DiagI(\hi) - \TimeScale \One \One^\t \\
        &= S_{\I,\I} - \TimeScale \One \One^\t.
    \end{eqn}
    This implies $\hat{H}_{i,j} = H_{i,j}$, since the constant matrix $\TimeScale \One \One^\t$ vanishes when subtracting $\Sr_{j,j} - \Sr_{i,j}$.
\end{proof}


\ThInducedFlow*
\begin{Proof}{th:induced-flow}
    For the first statement, we rearrange terms:
    \begin{eqn} \label{eq:flow-1}
        \lim_{t \ra 0} \frac{1}{2t} \Ex \lrs{ (\Id_{X_t,:} - \Id_{X_0,:})^\t (\Id_{X_t,:} - \Id_{X_0,:})  } &= 
        \lim_{t \ra 0} \frac{1}{2t} \Ex \lrs{ \Id_{X_0,:}^\t (\Id_{X_0,:} - \Id_{X_t,:})
        + \Id_{X_t,:}^\t (\Id_{X_t,:} - \Id_{X_0,:}) } \\
        &= \lim_{t \ra 0} \frac{1}{t} \Ex \lrs{ \Id_{X_0,:}^\t (\Id_{X_0,:} - \Id_{X_t,:}) }
    \end{eqn}
    where the second line follows from reversibility.
    Then:
    \begin{eqn} \label{eq:flow-2}
        \lim_{t \ra 0} \frac{1}{t} \Ex \lrs{ \Id_{X_0,i} (\Id_{X_0,j} - \Id_{X_t,j}) }
        &= \Prob(X_0 = i) \cdot \lim_{t \ra 0} \frac{1}{t} \Ex \lrs{ \Id_{X_0,j} - \Id_{X_t,j} \mid X_0 = i}  \\
        &= \Prob(X_0 = i) \cdot (\Minus R_{i,j}) = \Minus \pi_i R_{i,j}.
    \end{eqn}
    The second statement follows by the exact same procedure. 
    For the third statement, by insertion of identity and use of \cref{eq:flow-1,eq:flow-2}:
    \begin{eqn}
        \lim_{t \ra 0} \frac{1}{2t} \Ex \lrs{ (\Cu_{X_t,:} - \Cu_{X_0,:})^\t (\Cu_{X_t,:} - \Cu_{X_0,:})  }
        &= \lim_{t \ra 0} \frac{1}{2t} \Ex \lrs{ \Cu^\t (\Id_{X_t,:} - \Id_{X_0,:})^\t (\Id_{X_t,:} - \Id_{X_0,:}) \Cu  } \\
        &= \Cu^\t \lim_{t \ra 0} \frac{1}{2t} \Ex \lrs{ (\Id_{X_t,:} - \Id_{X_0,:})^\t (\Id_{X_t,:} - \Id_{X_0,:}) } \Cu \\
        &= \Minus \Cu^\t \Diag(\pi) R \Cu
    \end{eqn}
\end{Proof}



