\subsection{Features of structure-preserving compression \label{a:sp-features}}

\ThInducedIsLaplacian*
\begin{Proof}{th:induced-is-laplacian}
    This a corollary of \Cref{th:induced-basics}.
    First, observe that 
    \begin{eqn}
        \Lr = \Minus \Diag(\hr) \Rr \DiagI(\hr) = \Minus\DiagI(\hr) \Cu^\t \Diag(\pi) R \Cu \DiagI(\hr).
    \end{eqn}
    Since $\Diag(\pi) R$ is symmetric by the reversibility of the original chain, $\Lr$ is therefore symmetric.
    Moreover, since $\hr$ is entrywise positive, it follows from \Cref{th:induced-basics} that $\Lr_{i,j} \leq 0$ for all $i \neq j$ and $\Lr_{i,i} > 0$ for all $i$.

    Next, since $\Lr$ is obtained from $\Minus\Rr$ by a similarity transform, it has the same eigenvalues as $\Minus\Rr$.
    This shows that $\Lr$ is positive semidefinite with a single zero eigenvalue.

    Finally, observe that $\snorm{\hr} = 1$ since $\One^\t \hr^2 = \One^\t \pr = 1$.
    Therefore we verify that the zero eigenvalue corresponds to eigenvector $\hr$ by computing that $\Lr \hr = \Minus\Diag(\hr) \Rr \DiagI(\hr) \hr = \Minus\Diag(\hr) \Rr \One = \Zero$.
\end{Proof}

