\ThSpNonnegativity*
\begin{Proof}{th:sp-nonnegativity}
    To prove entrywise nonnegativity, we expand the definition of $\NonSymObliqueP_{\I}(t)$:
    \begin{eqn}
        \NonSymObliqueP_{\I}(t) = \Cu \ert{\Rr}  \DiagI(\pr) \Cu^\t \Diag(\pi).
    \end{eqn}
    $\Cu$ is entrywise nonnegative by its probabilistic construction, while $\p$ and $\pr$ are entrywise positive (the latter by its definition in \cref{eq:stationary-chp}).
    Since $\Rr$ is nonnegative outside of its diagonal (by \Cref{th:induced-basics}), $\ert{\Rr}$ is entrywise nonnegative.
    Therefore $\NonSymObliqueP_{\I}(t)$ is entrywise nonnegative, and $\ObliqueP_{\I}(t)$ is as well, since the latter is obtained as a similarity transformation of the former via $\Diag(h) \cdots \DiagI(h)$.

    Next, since $\ert{\Rr}$ is the solution of the probability evolution of a Markov chain with rate matrix $\Rr$, it follows that $\ert{\Rr} \One = \One$.
    Therefore, since $\pr \Eq \Cu^\t \pi$ and $\Cu \One = \One$:
    \begin{eqn}
        \Cu \ert{\Rr}  \DiagI(\pr) \Cu^\t \Diag(\pi) \One = \Cu \ert{\Rr} \One = \Cu \One = \One,
    \end{eqn}
    showing that $\NonSymObliqueP_{\I}(t)$ is row stochastic.

    Finally, by the convergence theorem for irreducible Markov chains, $\lim_{t \ra \infty} \ert{\Rr} = \One \pr^\t$.
    Since $\expt{\Lr} = \Diag(\hr) \ert{\Rr} \DiagI(\hr)$ by the definition of $\Lr$, this shows that 
    $\lim_{t \ra \infty} \expt{\Lr} = \hr \hr^\t$.
    Therefore $\lim_{t \ra \infty} \ObliqueP_{\I}(t) = \Co \hr \hr^\t \Co^\t = h h^\t$ by direct computation.
    Since $\Lr$ is symmetric, $\NonSymObliqueP_{\I}(t)$ is symmetric by inspection of \cref{eq:oblique-p}.
\end{Proof}

\ThSpIntegral*
\begin{Proof}{th:sp-integral}
    Using $\Ca \Eq \KA_{:, \I} \KA_{\I,\I}^\Mo \Diag\lrp{\tfrac{\hi}{\ha}}$ (\Cref{def:killed-committor}), we compute:
    \begin{eqn}
        % \ObliqueP_{\I,\Kill}(0) &= \Ca \Ca^\t \\
        % \ObliqueP_{\I,\Kill}(0) &= \Ca \Ca^\t \\
        \int_0^\infty \ObliqueP_{\I,\Kill}(t) \; \odif t 
        &= \int_0^\infty \Ca \expt{\Ca^\t \La \Ca} \Ca^\t \; \odif t \\
        &= \Ca (\Ca^\t \La \Ca)^\Mo \Ca^\t \\
        &= \KA_{:, \I} \KA_{\I,\I}^\Mo \Diag\lrp{\tfrac{\hi}{\ha}} \lrs{\Diag\lrp{\tfrac{\hi}{\ha}} \KA_{\I,\I}^\Mo \Diag\lrp{\tfrac{\hi}{\ha}}}^\Mo \Diag\lrp{\tfrac{\hi}{\ha}} \KA_{\I,\I}^\Mo \KA_{\I,:} \\
        &= \KA_{:, \I} \KA_{\I,\I}^\Mo \KA_{\I,:}.
    \end{eqn}
\end{Proof}

