Here we provide proofs of the fundamental linear-algebraic properties satisfied by $\Co$ (the committor), $\Qo$ (the projection to position space), and $\So$ (the projection to marking space).
We must also consider the analogous killed operators $\Ca$ (\Cref{def:killed-committor}) and $\Qa$, $\Sa$ defined as follows:

\begin{definition}[Formulation of marked chain operators including killing] \label{def:killed-projections}
For a killing rate $\Kill > 0$ and $\Ca$ as in \Cref{def:killed-committor}, define:
\begin{eqn}
    \pea & \  \Eq \  \begin{bmatrix} \pi_{\I} \\ \mathrm{vec}(\Diag(\pi_{\Ic}) (\Cu_\Kill)_{\Ic, :}) \end{bmatrix}, \qquad
    &\hea & \  \Eq \  \pea^{1/2}, \\
    \Qa & \  \Eq \  \Diag(\hea) \Qu \DiagI(h), \qquad
    &\Sa & \  \Eq \ \Diag(\hea) \Su \DiagI(\ha).
\end{eqn}
Under the same indexing convention as in \Cref{eq:pealt}, since $(\tilde{C}_\gamma)_{\I,:} = \Id_{\I,\I}$, we can write 
\begin{eqn} \label{eq:pealt2}
(\pea)_{(i,j)} = (\tilde{C}_{\gamma})_{j,i} \, \pi_j,
\end{eqn}
extending the above specification by zeros to the impossible states.
\end{definition}

