Next, both $\Qo$ and $\So$ are entrywise non-negative matrices with orthonormal columns.
On the other hand, in the killed case for $\gamma > 0$, $\Sa$ has orthonormal columns, while $\Qa$ only satisfies $\snorm{\Qa} = 1$ but does not have orthonormal columns. 
These results are stated in the next two lemmas.

\begin{lemma}[Basic properties of $\Qo$ and $\Qa$] \label{th:q-contraction}
    % \ML{adjust title / statement} $\Qo$ and $\Qa$ are contractions.
    Given $\Qo$ as specified in \Cref{eq:marked-projections}: 
    % $ \snorm{\Qo} = 1 $ for all $\Kill \geq 0 $ and $ \Qo^\t \Qo = \Id \text{ if } \Kill = 0 $.
    \begin{eqn}
        \Qo^\t \Qo = \Id, \qquad \Qo \Qo^\t \he = \he. %, \qquad \snorm{\Qo} = 1
    \end{eqn}
    Meanwhile, for any $\Kill > 0$, with $\Qa$ as defined in \Cref{def:killed-projections}:
    \begin{eqn}
        \snorm{\Qa} = 1.
    \end{eqn}
\end{lemma}
\begin{proof}
    % \ML{Modified this proof a bit to be more careful about indexing. It seems to keep coming up later you should have a look} 
    Recall (cf. \Cref{eq:tildeproj} and the ensuing discussion) that $\Qu$ is the indicator matrix which yields the position space representation of a state in the augmented space, i.e., $\Qu_{(k,l),i} = \delta_{i,l}$ for all $(k,l)$ in the augmented space and $i \in [n]$. For this discussion, it is convenient to index the augmented space by $(k,l) \in \I \times [n]$, and (abusing notation slightly) to extend matrices and vectors by zeros for the omitted ordered pair indices $(k,l)$ for which $k,l \in \I$ but $k\neq l$.

    Note that marginalizing the stationary distribution of the marked chain over the marking space implies that $\pi = \Qu^\t \pe$, or under our indexing convention,  $\pi_i = \sum_{(k,l)} \Qu_{(k,l),i} \pe_{(k,l)} = \sum_{k \in \I} \pe_{(k,i)}$. (Algebraically, this identity can be confirmed from \Cref{eq:pealt} using the fact that $\tilde{C} \One = \One$.)

    Moreover, compute: 
    \begin{eqn}
        \Qo_{:,i}^\t \Qo_{:,j} &= h_i^\Mo h_j^\Mo \Qu_{:,i}^\t \Diag(\pe) \Qu_{:,j} = 
        h_i^\Mo h_j^\Mo
        \sum_{(k,l)} \Qu_{(k,l),i} \, \pe_{(k,l)} \, \Qu_{(k,l),j} \\
        &=
        h_i^\Mo h_j^\Mo \delta_{i,j} \sum_{k \in \I} \pe_{(k,i)} = h_i^\Mo h_j^\Mo \pi_i \delta_{i,j} = \delta_{i,j},
    \end{eqn}
    i.e., $Q^\t Q = \Id$ as was to be shown.

    To show the second conclusion:
    \begin{eqn}
        \Qo \Qo^\t \he &= \Diag(\he) \Qu \DiagI(\pi) \Qu^\t \Diag(\he) \he \\
        &= \Diag(\he) \Qu \DiagI(\pi) \Qu^\t \pe \\
        &= \Diag(\he) \Qu \One \\
        &= \he 
    \end{eqn}
    where the third line is implied by $\pi = \Qu^\t \pe$ and the fourth by $\Qu \One = \One$ (since each row of $\Qu$ consists of a single 1, corresponding to the position of the state).
    % $\Qo^\t \Qo$ is diagonal since there is no overlap of position indexing. 
    % For $i \in \I$, $\Qo^\t_{:,i} \Qo_{:,i} = 1$ no matter the killing.
    % For $i \notin \I$, $\Qo^\t_{:,i} \Qo_{:,i} < 1$ if killed otherwise 1. \MF{elaborate}

    It remains to show that $\Vert Q_\gamma \Vert_2 = 1$. Note that by the probabilistic interpretation of $\tilde{C}_\gamma$ (\Cref{th:killed-committor-prob}), $\tilde{C}_\gamma \One \leq \One$ (entrywise).
    Thus, by the specification \Cref{eq:pealt2} of $\pea$: % and $\Cu_\Kill$ \Cref{eq:killed-chp}:
    \begin{eqn} \label{eq:killed-sums}
        \sum_{k \in \I} (\pea)_{(k,i)} = \sum_{k \in \I} \pi_i (\Cu_\Kill)_{i,k} = \pi_i \Cu_{i,:} \One \leq \pi_i.
    \end{eqn}
    Note that equality holds when $i \in \I$. Therefore, computation of $\Qa^\t \Qa$ yields:
    \begin{eqn}
        (\Qa)_{:,i}^\t (\Qa)_{:,j} &= h_i^\Mo h_j^\Mo \Qu_{:,i}^\t \Diag(\pea) \Qu_{:,j} = 
        h_i^\Mo h_j^\Mo
        \sum_{(k,l)} \Qu_{(k,l),i} \, (\pea)_{(k,l)} \, \Qu_{(k,l),j} \\
        &=
        h_i^\Mo h_j^\Mo \delta_{i,j} \sum_{k \in \I} (\pea)_{(k,i)} \leq h_i^\Mo h_j^\Mo \pi_i \delta_{i,j} = \delta_{i,j},
    \end{eqn}
    using \Cref{eq:killed-sums} for the middle inequality.
    Therefore $\Qa^\t \Qa$ is a diagonal matrix upper-bounded by $\Id$ entrywise.
    Furthermore, the diagonal entries in the $\I$ block are 1, yielding the strict equality of $\snorm{\Qa} = 1$.
    % The spectral norm $\snorm{\Qa^\t \Qa} = 1$ may be 
\end{proof}

\begin{lemma}[Basic properties of $\So$ and $\Sa$] \label{th:s-orthogonality}
    For any $\Kill \geq 0$:
    \begin{eqn}
        \So^\t \So &= \Id, \qquad \snorm{\So} = 1 \\
        \qquad \Sa^\t \Sa &= \Id, \qquad \snorm{\Sa} = 1
    \end{eqn}
    and
    \begin{eqn}
        \So \So^\t \he = \he .
    \end{eqn}
\end{lemma}
\begin{proof}
    Recall (cf. \Cref{eq:tildeproj} and the ensuing discussion) that $\Su$ is the indicator matrix which yields the marking space representation of a state in the augmented space, i.e., that 
    $\Su_{(l,k),i} = \delta_{i,l}$ for all $(l,k)$ in the augmented space, $i \in \I$. We use the same indexing convention for the augmented space as in the proof of \Cref{th:q-contraction}.

    Direct computation (using the specification \Cref{eq:pealt} for $\pe$) yields that $\Su^\t \pe = \Cu^\t \pi = \pr$, the latter equality following from the definition of $\pr$.
    % Proceeding, a state in the augmented space only has one marking, so $\So_{:,i}^\t \So_{:,j}$ is 0 unless $i = j$.
    % For the diagonal elements,
    (In our indexing convention, one may equivalently write that $\sum_{k \in \Indices} \pe_{(i,k)} = \pr_i$.)
    Moreover, compute: 
    \begin{eqn}
        \So_{:,i}^\t \So_{:,j} &= \hr_i^\Mo \hr_j^\Mo \Su_{:,i}^\t \Diag(\pe) \Su_{:,j} 
        = \hr_i^\Mo \hr_j^\Mo \sum_{(l,k)} \Su_{(l,k),i} \,  \pe_{(l,k)} \,  \Su_{(l,k),j} \\
        &= \hr_i^\Mo \hr_j^\Mo \delta_{i,j} \sum_{k \in \Indices} \pe_{(i,k)}  = \delta_{i,j} \hr_i^\Mo \hr_j^\Mo \pr_i = \delta_{i,j}.
    \end{eqn}
    For the killed case, analogously, direct computation (using the specification \Cref{eq:pealt2} for $\pea$) yields that $\Su^\t \pea = \Cu_{\Kill}^\t \pi = \pa$, the latter by the definition of $\pa$ \Cref{eq:killed-chp}. 
    Then:
    \begin{eqn}
        (\Sa)_{:,i}^\t (\Sa)_{:,j} &= (\ha)_i^\Mo (\ha)_j^\Mo \Su_{:,i}^\t \Diag(\pea) \Su_{:,j} 
        = (\ha)_i^\Mo (\ha)_j^\Mo \sum_{(l,k)} \Su_{(l,k),i} \,  (\pea)_{(l,k)} \,  \Su_{(l,k),j} \\
        &= (\ha)_i^\Mo (\ha)_j^\Mo \delta_{i,j} \sum_{k \in \Indices} (\pea)_{(i,k)} = \delta_{i,j} (\ha)_i^\Mo (\ha)_j^\Mo (\pa)_i = \delta_{i,j}.
    \end{eqn}
    % owing to the physical interpretations of $\pe$ and $\pr$.

    To show the second conclusion:
    \begin{eqn}
        \So \So^\t \he &= \Diag(\he) \Su \DiagI(\pr) \Su^\t \Diag(\he) \he \\
        &= \Diag(\he) \Su \DiagI(\pr) \Su^\t \pe \\
        &= \Diag(\he) \Su \One \\
        &= \he
    \end{eqn}
    where the third line is implied by $\pr = \Su^\t \pe$ and the fourth by $\Su \One = \One$ (since each row of $\Su$ consists of a single 1, corresponding to the marking of the state).
\end{proof}

