The committor $\Co$ may be related to $\Qo$ and $\So$ as follows: 
\begin{lemma}[Relating marked chain projection to the committor] \label{th:q-s-equals-c}
    With $\Qo$, $\So$, and $\Co$ as in \Cref{eq:marked-projections} and \Cref{th:committor}:
    \begin{eqn}
        \Qo^\t \So = \Co.
    \end{eqn}
    In the killed case, for $\Kill > 0$ and $\Qa$, $\Sa$, and $\Ca$ as in \Cref{def:killed-projections} and \Cref{def:killed-committor}:
    \begin{eqn}
        \Qa^\t \Sa = \Ca.
    \end{eqn}
\end{lemma}
\begin{proof}
    First compute: 
    \begin{eqn}
        \Qo^\t \So = \Diag(h) \Qu^\t \Diag(\pe) \Su \Diag(1/\hr).
    \end{eqn}
    Then, by expanding the blockwise definitions of $\Qu$ and $\Su$:
    \begin{eqn}
        \Qu^\t \Diag(\pe) \Su &= \Id_{:,\I} \Diag(\pi_{\I}) + 
        \Id_{:,\Ic} (\One_{\I} \otimes \Id_{\Ic,\Ic})^\t \Diag(\mathrm{vec}(\Diag(\pi_{\Ic}) \Cu_{\Ic,:})) (\Id_{\I,\I} \otimes \One_{\Ic}) \\
        &= \Id_{:,\I} \Diag(\pi_{\I}) + \Id_{:,\Ic} \Diag(\pi_{\Ic}) \Cu_{\Ic,:} \\
        &= \Diag(\pi) \Cu.
    \end{eqn}
    Finally, substituting back in yields 
    \begin{eqn}
        \Qo^\t \So = \Diag(1/h) \Diag(\pi) \Cu \Diag(1/\hr) = \Co
    \end{eqn}
    using the definitions of $h$, $\pi$, and $\Co$.

    The exact same logic applies above for the killed case, with $\pea$, $\hea$, and $\Cu_{\Kill}$ replacing $\pe$, $\he$, and $\Cu$, respectively.
\end{proof}

\begin{lemma}[Original Laplacian in terms of the marked chain] \label{th:qlq}
    With $\Qo$ as in \cref{eq:marked-projections} and $\Le$ as in \Cref{def:marked-laplacian}:
    \begin{eqn}
        \Qo^\t \Le \Qo = L.
    \end{eqn}
    In fact $\Qo$ defines an invariant subspace of $\Le$ in that $\Le \Qo = \Qo L$.
\end{lemma}
\begin{proof}
    Note that it suffices to show that $\Le \Qo = \Qo L$, which implies the first statement via left-multiplication by $\Qo^\t$ (since $\Qo$ has orthonormal columns). In turn, by unraveling the similarity transformations of \Cref{def:marked-laplacian} and \Cref{eq:marked-projections}  used to define $\Le$ and $\Qo$ in terms of $\Rex$ and $\Qu$, respectively, we see that it suffices to show that $\Rex \Qu = \Qu R$. Then by substituting the blockwise expressions \Cref{eq:expanded-R} and \Cref{eq:tildeproj} for $\Rex$ and $\Qu$, we verify by direct computation that 
    \begin{eqn}
        \Rex\tilde{Q}=\left[\begin{array}{cc}
R_{\I,\I} & R_{\I,\Ic}\\
\mathbf{1}_{\I}\otimes R_{\Ic,\I} & \mathbf{1}_{\I}\otimes R_{\Ic,\Ic}
\end{array}\right]=\tilde{Q} R.
    \end{eqn}
    \end{proof}


\begin{lemma}[Induced Laplacian in terms of the marked chain] \label{th:sls}
    With $\So$ as in \cref{eq:marked-projections}, $\Le$ as in \Cref{def:marked-laplacian}, and $\Lr$ as in \cref{eq:oblique-p}:
    \begin{eqn}
        \So^\t \Le \So = \Lr.
    \end{eqn}
    Furthermore, for any $\Kill > 0$, with $\Sa$ as in \Cref{def:killed-projections} and $\Lea$ as in \Cref{eq:Lea}:
    \begin{eqn}
        \Sa^\t \Lea \Sa = \Lr_\Kill.
    \end{eqn}
\end{lemma}
\begin{proof}
We tackle the first statement first. By unraveling the diagonal transformations
\Cref{def:marked-laplacian} and \Cref{eq:marked-projections}
used to define $\mathring{L}$ and $W$ in terms of $\mathring{R}$
and $\tilde{W}$, respectively, we see that it suffices to show that
\[
\tilde{W}^{\top}\mathrm{diag}(\mathring{\pi})\mathring{R}\tilde{W}=\mathrm{diag}(\hat{\pi})\hat{R}.
\]
 Recall from \Cref{eq:simple-induced} that 
\[
\hat{R}=\mathrm{diag}^{-1}(\hat{\pi})\tilde{C}^{\top}\mathrm{diag}(\pi)R\tilde{C},
\]
 so in turn it suffices to show that 
\begin{equation}
\tilde{W}^{\top}\mathrm{diag}(\mathring{\pi})\mathring{R}\tilde{W}=\tilde{C}^{\top}\mathrm{diag}(\pi)R\tilde{C}.\label{eq:LHSRHS}
\end{equation}

Let us simplify the right-hand side of \Cref{eq:LHSRHS}.
By the Laplace equation \Cref{eq:laplace-equation}, we know that $(R\tilde{C})_{\Ic,:}=0$.
(Note that this can also be verified by direct computation, as we
explicitly demonstrate below in the killed $\gamma>0$ case.) Moreover,
$(\tilde{C})_{\I,:}=\Id_{\I,\I}$. Therefore 
\begin{equation}
\tilde{C}^{\top}\mathrm{diag}(\pi)R\tilde{C}=\left[\begin{array}{c}
\Id_{\I,\I}\\
0
\end{array}\right]^{\top}\mathrm{diag}(\pi)\left[\begin{array}{c}
(R\tilde{C})_{\I,:}\\
0
\end{array}\right]=\mathrm{diag}(\pi_{\I})R_{\I,:}\tilde{C}.\label{eq:RHS}
\end{equation}
 Now by reversibility, $\mathrm{diag}(\pi)R$ is symmetric, so the
left-hand side of \Cref{eq:RHS} is symmetric, hence
so is the right-hand side, and in summary, for the proof it suffices
to show that 
\begin{equation}
\tilde{W}^{\top}\mathrm{diag}(\mathring{\pi})\mathring{R}\tilde{W}=\left[\mathrm{diag}(\pi_{\I})R_{\I,:}\tilde{C}\right]^{\top}.\label{eq:LHSRHS2}
\end{equation}

Now we turn to the left-hand side of \Cref{eq:LHSRHS}.
It is useful to adopt the same indexing convention as in the proof
of \Cref{th:q-contraction}. Within this convention, recall from \eqref{eq:pealt} that $\mathring{\pi}_{(i,j)}=\tilde{C}_{j,i}\pi_{j}$.
Moreover, for any ordered pair $(i,j)$ that is \emph{possible}
(i.e., not omitted from the augmented space), we have that 
\begin{equation}
\mathring{R}_{(i,j),(i',j')}=\begin{cases}
\delta_{i',j'}R_{j,j'}, & j'\in\I\\
\delta_{i,i'}R_{j,j'}, & j'\in\Ic.
\end{cases}\label{eq:ReEntrywise}
\end{equation}
 The first line follows from the fact that during a transition to
a position state $j'\in\I$, we must pick up the new marking $j'$.
The second line follows from the fact that during a transition to
a position state $j'\in\Ic$, we must retain our old marking.

Now since the expression $\mathring{\pi}_{(i,j)}=\tilde{C}_{j,i}\pi_{j}$
extends by zeros to all impossible states, in turn the expression
\begin{equation}
\left(\mathrm{diag}(\mathring{\pi})R\right)_{(i,j),(i',j')}=\begin{cases}
\tilde{C}_{j,i}\pi_{j}\delta_{i',j'}R_{j,j'}, & j'\in\I\\
\tilde{C}_{j,i}\pi_{j}\delta_{i,i'}R_{j,j'}, & j'\in\Ic,
\end{cases}\label{eq:piRcon}
\end{equation}
 extends $\mathrm{diag}(\mathring{\pi})R$ by zeros and satisfies
our indexing convention.

Then we expand the left-hand side of \Cref{eq:LHSRHS2}
and insert $\tilde{W}_{(i,j),k}=\delta_{i,k}$ to compute, for $k,k'\in\I$:
\begin{align*}
\left(\tilde{W}^{\top}\mathrm{diag}(\mathring{\pi})\mathring{R}\tilde{W}\right)_{k,k'} & =\sum_{i,i'\in\I,\,j,j'\in[n]}\tilde{W}_{(i,j),k}\left(\mathrm{diag}(\mathring{\pi})R\right)_{(i,j),(i',j')}\tilde{W}_{(i',j'),k'}\\
 & =\sum_{j,j'\in[n]}\left(\mathrm{diag}(\mathring{\pi})R\right)_{(k,j),(k',j')}\\
 & =\sum_{j\in[n],\,j'\in\I}\left(\mathrm{diag}(\mathring{\pi})R\right)_{(k,j),(k',j')}+\sum_{j\in[n],\,j'\in\Ic}\left(\mathrm{diag}(\mathring{\pi})R\right)_{(k,j),(k',j')}\\
 & \overset{(*)}{=}\sum_{j\in[n],\,j'\in\I}\tilde{C}_{j,k}\pi_{j}\delta_{k',j'}R_{j,j'}+\sum_{j\in[n],\,j'\in\Ic}\tilde{C}_{j,k}\pi_{j}\delta_{k,k'}R_{j,j'}\\
 & =\sum_{j\in[n]}\tilde{C}_{j,k}\pi_{j}R_{j,k'}+\delta_{k,k'}\sum_{j\in[n],\,j'\in\Ic}\tilde{C}_{j,k}\pi_{j}R_{j,j'}\\
 & \overset{(\star)}{=}\sum_{j\in[n]}\pi_{k'}R_{k',j}\tilde{C}_{j,k}+\delta_{k,k'}\sum_{j\in[n],\,j'\in\Ic}\pi_{j'}R_{j',j}\tilde{C}_{j,k}\\
 & =\pi_{k'}(R\tilde{C})_{k',k}+\delta_{k,k'}\sum_{j'\in\Ic}\pi_{j'}(R\tilde{C})_{j',k},
\end{align*}
where in the $(*)$ equation we have substituted \Cref{eq:piRcon} and in the $(\star)$ equation we have used reversibility: $\pi_i R_{i,j} = \pi_j R_{j,i}$ for all $i,j$.
 Now in the last expression, $(R\tilde{C})_{j',k}=0$ for $j'\in\Ic$,
again by the Laplace equation \Cref{eq:laplace-equation}. So we conclude that 
\[
\left(\tilde{W}^{\top}\mathrm{diag}(\mathring{\pi})\mathring{R}\tilde{W}\right)_{k,k'}=\pi_{k'}(R\tilde{C})_{k',k}
\]
 for all $k,k'\in\I$, which means precisely that \Cref{eq:LHSRHS2}
holds, as desired.

This concludes the proof of the first statement. For the second statement,
we want to show that $W_{\gamma}^{\top}\mathring{L}_{\gamma}W_{\gamma}=\hat{L}_{\gamma}$,
where $\gamma>0$. Recall that $\hat{L}_{\gamma}=C_{\gamma}^{\top}L_{\gamma}C_{\gamma}$,
so by unraveling the diagonal transformations (cf. \Cref{def:killed-committor},
\Cref{eq:Lea}, and \Cref{eq:marked-projections})
used to define $C_{\gamma}$, $\mathring{L}_{\gamma}$, and $W_{\gamma}$
in terms of $\tilde{C}_{\gamma}$, $\mathring{R}_\gamma$, and $\tilde{W}$,
we see that it suffices to show that 
\begin{equation}
\tilde{W}^{\top}\mathrm{diag}(\mathring{\pi}_{\gamma})\mathring{R}_{\gamma}\tilde{W}=\tilde{C}_{\gamma}^{\top}\mathrm{diag}(\pi)R_{\gamma}\tilde{C}_{\gamma},\label{eq:LHSRHSgamma}
\end{equation}
 % where $\mathring{R}_{\gamma}:=\mathring{R}-\gamma\Id$ nad $R_{\gamma}:=R-\gamma\Id$,
similar to \Cref{eq:LHSRHS}. The proof of \Cref{eq:LHSRHSgamma}
is the same as that of \Cref{eq:LHSRHS}, given the
ingredients: 
\begin{enumerate}
\item $\mathrm{diag}(\pi)R_{\gamma}$ is symmetric, following directly from
the same fact for $\mathrm{diag}(\pi)R$, since $R_\gamma = R - \gamma \Id$.
\item The entrywise formula $\left(\mathrm{diag}(\mathring{\pi}_{\gamma})R_{\gamma}\right)_{(i,j),(i',j')}$
is the same as \Cref{eq:piRcon}, upon substitution
of $\tilde{C}_{\gamma}$ for $\tilde{C}$ (based on the entrywise
expression \Cref{eq:pealt2} for $\mathring{\pi}_{\gamma}$) and $R_{\gamma}=R-\gamma\Id$
for $R$ (based on the fact that this reproduces the effect of subtracting
$\gamma\Id$ from $\mathring{R}$ in the blockwise formula \Cref{eq:expanded-R} for
$\mathring{R}$).
\item The ``killed Laplace equation'' is satisfied by the killed commitor on $\Ic$, i.e., $[R_{\gamma}\tilde{C}_{\gamma}]_{\Ic,:}=0$. We verify this last point below.
\end{enumerate}
Then it only remains to show $[R_{\gamma}\tilde{C}_{\gamma}]_{\Ic,:}=0$.
To see this, recall the formula (\Cref{def:killed-committor})
\[
\tilde{C}_{\gamma}= \mathrm{diag}^{-1}(h)(K_{\gamma})_{:,\I} \ \cdots,
\]
 where ``$\,\cdots\,$'' indicates an omitted matrix factor. 
 Then since $K_{\gamma}=-\mathrm{diag}(h)R_{\gamma}^{-1}\mathrm{diag}^{-1}(h)$,
it follows that 
\[
[R_{\gamma}\tilde{C}_{\gamma}]_{\Ic,:}=-(R_{\gamma})_{\Ic,:}(R_{\gamma}^{-1})_{:,\I} \ \cdots
\]
But $(R_{\gamma})_{\Ic,:}(R_{\gamma}^{-1})_{:,\I}=\Id_{\Ic,\I}=0$,
which completes the proof.
\end{proof}

