\begin{lemma}\label{th:resolvent-sqrt}
    Let $B$ be a real symmetric positive definite matrix and $z \in \mathbb{C}$, $\re(z) > 0$. 
    Then
    \begin{eqn}
    \snorm*{\frac{(B^\Mo - z B)^\Mo}{z^{1/2}}} \leq 2^{\Mo/2} \lrp{1 - \frac{\re(z)}{\Abs{z}}}^\Mh \Abs{z}^\Mo. \\
    % \frac{\snorm{(A^\Mo - z A)^\Mo}}{\Abs{z}^{1/2}} \leq \lrp{2 - 2 \frac{\re(z)}{\Abs{z}}}^\Mh \Abs{z}^\Mo
    \end{eqn}
\end{lemma}
% \SqrtResolventNorm*
\begin{proof}
    Let $\lambda_i > 0$ denote the eigenvalues of $B$, which are in particular real. Now $B^\Mo - z B$ is a normal matrix, so it can be orthogonally diagonalized by the spectral theorem, and therefore 
    \begin{eqn}
        \norm{(B^\Mo - z B)^\Mo}_2 = \max_i \; \Abs{\lambda_i^\Mo - z \lambda_i}^\Mo .
    \end{eqn}
Let $z = a + b i$ for real $a,b$ with $a > 0$. Then 
\begin{eqn}
    \frac{\Abs{\lambda_i^\Mo - z \lambda_i}^\Mo}{\Abs{z}^{1/2}} = \lrp{a^2 + b^2}^{-1/4} \lrp{b^2 \lambda_i^2 + (\lambda_i^\Mo - a \lambda_i)^2}^\Mh \eqqcolon f(a,b,\lambda_i).
\end{eqn}
Consider $a,b$ fixed. Then $f(a,b,\lambda_i)$ is upper bounded as follows:
\begin{eqn}
    f(a,b,\lambda_i) \leq \max_{\lambda > 0} \{ f(a,b,\lambda) \}  = 2^\Mh \lrp{1 - \frac{a}{\sqrt{a^2 + b^2}}}^\Mh (a^2 + b^2)^\Mh
\end{eqn}
with the maximum achieved at $\lambda = (a^2 + b^2)^{-1/4} = \Abs{z}^{-1/2}$.
\end{proof}


