\begin{lemma}\label{th:obliqueness-equivalence}
     Let $\La$ be a killed Laplacian with committor $\Ca$ as in \Cref{def:killed-committor}, $z \in \mathbb{C}$ with $\re(z) > 0$, 
    $\OrthRes^\Kill$ as in \cref{eq:orth-res-def}, and
    $\ObliqueRes^\Kill$ as in \Cref{th:oblique-cauchy}. Then:
\begin{eqn}
    \label{eq:oblique-resolvent-diff}
    \ObliqueRes^\Kill(z) - \OrthRes^\Kill(z) = \Ca \,
    \SqrtResolvent_z [\Ca^\t \La \Ca]
    \, \Phi_\Kill \,
  \SqrtResolvent_z [\Va^\t \La \Va] \,
 \Va^\t / t,
\end{eqn}
where  $\Va = \Ca (\Ca^\t \Ca)^\Mh$ (cf. \Cref{def:killed-committor}), and moreover we define
\begin{eqn}
    \SqrtResolvent_z[A] \Eq \frac{(A^\Mh - z A^{1/2})^\Mo}{z^{1/2}}
\end{eqn}
and 
\begin{eqn}
    \Phi_\Kill \Eq (\Ca^\t \La \Ca)^\Mh \big[ (\Ca^\t \Ca)^\Mh - (\Ca^\t \Ca)^{1/2} \big] (\Va^\t \La \Va)^\Mh.
\end{eqn}
\end{lemma}
\begin{proof}
    Applying the Woodbury matrix identity to both $\OrthRes^\Kill(z)$ and $\ObliqueRes^\Kill(z)$, we deduce that 
    \begin{eqn}
        \OrthRes^\Kill(z) &= z^\Mo \lrp{\Id - \Ca (\Ca^\t \Ca - z \Lrk t)^\Mo \Ca^\t} \\
        \ObliqueRes^\Kill(z) &= z^\Mo \lrp{\Id - \Ca (\Id - z \Lrk t)^\Mo \Ca^\t}
    \end{eqn}
    so that upon rearrangement,
    \begin{eqn}
        \ObliqueRes^\Kill(z) - \OrthRes^\Kill(z) \ \ = \ \ & z^\Mo \Ca \left[ (\Ca^\t \Ca - z \Lrk t)^\Mo - (\Id - z \Lrk t)^\Mo \right] \Ca^\t \\
        = \ \ & z^\Mo \Ca (\Ca^\t \Ca - z \Ca^\t \La \Ca t)^\Mo (\Id - \Ca^\t \Ca) (\Id - z \Ca^\t \La \Ca t)^\Mo \Ca^\t \\
        = \ \ & z^\Mo \Ca 
            \left[ (\Ca^\t \La \Ca t)^\Mh - z (\Ca^\t \La \Ca t)^{1/2} \right]^\Mo \\
            & \qquad (\Ca^\t \La \Ca)^\Mh
         \big[ (\Ca^\t \Ca)^\Mh - (\Ca^\t \Ca)^{1/2} \big]
         (\Va^\t \La \Va)^\Mh \\
         & \qquad  \left[ (\Va^\t \La \Va t)^\Mh - z (\Va^\t \La \Va t)^{1/2} \right]^\Mo 
         \Va^\t / t\\
         = \ \ & \Ca  \, 
            \SqrtResolvent_z [\Ca^\t \La \Ca] \\
            & \qquad (\Ca^\t \La \Ca)^\Mh
         \big[ (\Ca^\t \Ca)^\Mh - (\Ca^\t \Ca)^{1/2} \big] 
         (\Va^\t \La \Va)^\Mh \\
         & \qquad  \SqrtResolvent_z [\Va^\t \La \Va ] \, 
         \Va^\t / t.
         \label{eq:resolvent-difference-forms}
    \end{eqn}
\end{proof}


