Finally, we are able to directly invoke $\Obs^\Kill$ in the bounding of $\ObliqueRes^\Kill(z) - \OrthRes^\Kill(z)$ via:
\begin{lemma}[Obliqueness norm identity] \label{th:obliqueness-norm}
    Consider a nonempty subset $\I$, $\La$ with $\Kill > 0$, $\Ca$ as in \Cref{th:killed-committor}, and $\Va = \Ca (\Ca^\t \Ca)^\Mh$ (as before).
    Then with $\Ob_\Kill$ and $\Obs^\Kill$ as in \Cref{def:obliqueness} and $\Phi_\Kill$ as in \Cref{th:obliqueness-equivalence}:
    \begin{eqn}
        \Norms{\Phi_\Kill} = \Obs^\Kill.
    \end{eqn}
\end{lemma}
% \ObliquenessNormIdentity*
\begin{proof}
    Straightforward computation yields:
    \begin{eqn}
        \Phi_\Kill \Phi_\Kill^\t
        & \ =  \ \ (\Ca^\t \La \Ca)^\Mh \big[ (\Ca^\t \Ca)^\Mh - (\Ca^\t \Ca)^{1/2} \big] (\Va^\t \La \Va)^\Mo
         \\ 
         & \qquad \qquad \big[ (\Ca^\t \Ca)^\Mh - (\Ca^\t \Ca)^{1/2} \big] (\Ca^\t \La \Ca)^\Mh \\
         & \ =  \ \   (\Ca^\t \La \Ca)^\Mh (\Id - \Ca^\t \Ca) (\Ca^\t \La \Ca)^\Mo
         (\Id - \Ca^\t \Ca) (\Ca^\t \La \Ca)^\Mh \\
         & \ =  \ \  \left[ (\Ca^\t \La \Ca)^\Mh (\Id - \Ca^\t \Ca) (\Ca^\t \La \Ca)^\Mh \right]^2 = \Ob_\Kill^2.
    \end{eqn}
    Since $\Ob_\Kill$ is symmetric positive semidefinite, it follows that 
    \begin{eqn}
        \snorm{\Phi_\Kill} &= \snorm{\Phi_\Kill \Phi_\Kill^\t}^{1/2} = \snorm{\Ob_\Kill} \\
        \nnorm{\Phi_\Kill} &= \nnorm{(\Phi_\Kill \Phi_\Kill^\t)^{1/2}} = \nnorm{\Ob_\Kill},
    \end{eqn}
    by expanding identities for the nuclear and spectral norms.
\end{proof}

