        \Norms{\ObliqueRes^\Kill(z) - \OrthRes^\Kill(z)} & \ \leq  \ 
        \snorm{\Ca}
        \cdot \snorm{\SqrtResolvent_z[\Ca^\t \La \Ca]}  \cdot 
        \Norms{\Phi_\Kill}  \cdot 
        \snorm{\SqrtResolvent_z[\Va^\t \La \Va]}
        \cdot \snorm{\Va} / t
        % \\
        % &\hspace{2.0em}\cdot \Norms{(\Co^\t \La \Co)^{1/2} \big[(\Co^\t \Co)^\Mh - (\Co^\t \Co)^{1/2}\big] (\Va^\t \La \Va)^\Mh} \\
        % &\hspace{2.0em}\cdot 
    %  &\hspace{.1in}\cdot \frac{\snorm{\lrp{(\Co^\t \La \Co)^\Mh - z (\Co^\t \La \Co)^{1/2}}^\Mo}}{\Abs{z}^{1/2}} 
    %  &\hspace{.1in}\cdot \frac{\snorm{\lrp{(\Va^\t \La \Va)^\Mh - z (\Va^\t \La \Va)^{1/2}}^\Mo}}{\Abs{z}^{1/2}} & 
    %  &\hspace{.1in}\cdot \snorm{\SqrtResol\Vaent_z \Va^\t \La \Va)} & 
    %  \hspace{-1in} 
    %  \lrs{\leq \lrp{2 - 2 \re(z) / \Abs{z}}^\Mh \Abs{z}^\Mo  \text{ by \Cref{th:resolvent-sqrt}}} \\
    \end{eqn}
    following the notation of \Cref{th:obliqueness-equivalence}. 

    We deal with the factors in their order of appearance as follows: 
    \begin{eqn}
        \snorm{\Ca} &\leq 1 
            & \hspace{-0.1in}\text{by \Cref{th:committor-norm}} \\
        \snorm{\SqrtResolvent_z [\Ca^\t \La \Ca]} &\leq 2^\Mh \lrp{1 - \re(z) / \Abs{z}}^\Mh \Abs{z}^\Mo 
            & \hspace{-0.1in}\text{by \Cref{th:resolvent-sqrt}} \\
