\subsection{Probabilistic derivations related to obliqueness}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We begin with the following general lemma which allows us to write the obliqueness norms $\Obs^\Kill$ in terms of $\Ka$.
\begin{lemma}
    \label{th:norm-switch}
    Let $A$ and $B$ be real symmetric positive definite matrices and $C$ be real. Then
\begin{eqn}
    \Norms{C B (B A B)^\Mh} = \Norms{C A^\Mh}.
\end{eqn}
\end{lemma}
\begin{proof}
    For any real $M$, $\snorm{M} = \snorm{M M^\t}^{1/2}$ and $\nnorm{M} = \nnorm{(M M^\t)^{1/2}}$.
    With $M = C B (B A B)^\Mh$,
\begin{eqn}
    M M^\t = [C B (B A B)^\Mh] [C B (B A B)^\Mh]^\t = C B (B A B)^\Mo B C^\t = C A^\Mo C^\t
\end{eqn}
so that $\snorm{M M^\t}^{1/2} = \snorm{C A^\Mo C^\t}^{1/2}  = \snorm{C A^\Mh}$ and $\nnorm{(M M^\t)^{1/2}} = \nnorm{(C A^\Mo C^\t)^{1/2}} = \nnorm{C A^\Mh}$.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Using this lemma and the definition of $\Ca$ (\Cref{def:killed-committor}), we obtain the following:
\begin{lemma}[Obliqueness in terms of $\Ka$] \label{th:obliqueness-using-k}
    For the killed chain $\La$, $\Ka = \La^\Mo$, $\pa$ as in \Cref{def:killed-committor}, and $\Obs^\Kill$ as in \Cref{def:obliqueness}:
    \begin{eqn}
        \label{eq:obliqueness-using-k}
        \Obs^\Kill = \Norms*{\KA_{\I,\I}^\Mh \KA_{\I,:} \left[ \Id_{:,\I} \Diag \lrp{\frac{\pa}{\pi_{\I}}} \Id_{\I,:} - \Id \right] \KA_{:,\I} \KA_{\I,\I}^\Mh}.
    \end{eqn}
\end{lemma}
\begin{proof}
From direct use of \Cref{def:killed-committor}, we compute that:
\begin{eqn}
    \Ca^\t \La \Ca &= \Diag(\hi / \ha) [\KA_{\I,\I}]^\Mo \Diag(\hi / \ha), \\
    \Ca^\t \Ca &= \Diag(\hi / \ha) \KA_{\I,\I}^\Mo (\Ka^2)_{\I,\I} \KA_{\I,\I}^\Mo \Diag(\hi / \ha).
\end{eqn}
Then by substitution, with $\Ob_\Kill$ as defined as in \Cref{def:obliqueness},
\begin{eqn}
    \Ob_\Kill \ &= \ (\Ca^\t \La \Ca)^\Mh (\Id - \Ca^\t \Ca) (\Ca^\t \La \Ca)^\Mh \\
    &= \ \left[ \DiagRat{\hi}{\ha}  \KA_{\I,\I}^\Mo \DiagRat{\hi}{\ha} \right] ^\Mh \DiagRat{\hi}{\ha} \\ 
    &\hspace{3em} \KA_{\I,\I}^\Mo  \left[ \KA_{\I,\I} \DiagRat{\ha^2}{\hi^2} \KA_{\I,\I} - (\Ka^2)_{\I,\I} \right] \KA_{\I,\I}^\Mo  \\
 &\hspace{3em} \DiagRat{\hi}{\ha} \left[ \DiagRat{\hi}{\ha} \KA_{\I,\I}^\Mo \DiagRat{\hi}{\ha} \right]^\Mh.
\end{eqn}
Finally, by application of \Cref{th:norm-switch} once on the left and once on the right (with $A=\KA_{\I,\I}^\Mo$, $B=\DiagRat{\hi}{\ha}$, $C$ the rest), we compute that:
\begin{eqn}
    \Norms{\Ob_\Kill} &= \Big\Vert \left[  \KA_{\I,\I}^\Mo \right] ^\Mh \KA_{\I,\I}^\Mo  \left[ \KA_{\I,\I} \DiagRat{\ha^2}{\hi^2} \KA_{\I,\I} - (\Ka^2)_{\I,\I} \right] \\ 
    & \hspace{3em} \KA_{\I,\I}^\Mo \DiagRat{\hi}{\ha} \left[ \DiagRat{\hi}{\ha} \KA_{\I,\I}^\Mo \DiagRat{\hi}{\ha} \right]^\Mh \Big\Vert_{\lrb{2,*}} \\
    &= \Big\Vert \left[  \KA_{\I,\I}^\Mo \right] ^\Mh \KA_{\I,\I}^\Mo  \left[ \KA_{\I,\I} \DiagRat{\ha^2}{\hi^2} \KA_{\I,\I} - (\Ka^2)_{\I,\I} \right] \KA_{\I,\I}^\Mo \left[ \KA_{\I,\I}^\Mo \right]^\Mh \Big\Vert_{\lrb{2,*}}
\end{eqn}
and therefore upon simplification:
\begin{eqn}
    \Obs^\Kill = \Norms*{\KA_{\I,\I}^\Mh  \lrp{\KA_{\I,\I} \Diag\lrp{\tfrac{\ha^2}{\hi^2}} \KA_{\I,\I} - (\Ka^2)_{\I,\I}} \KA_{\I,\I}^\Mh}.
\end{eqn}
Then \cref{eq:obliqueness-using-k} follows by rearrangement and the facts that $\pi=h^2$, $\pa=\ha^2$.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Next we demonstrate how the obliqueness norms converge and may be computed in the $\Kill \ra 0$ in closed form.
\begin{proposition}[Obliqueness in the $\Kill \ra 0$ limit] \label{th:recurrent-obliqueness}
    With $\Obs^\Kill$ as defined in \Cref{def:obliqueness}, $\On^\Kill$ converges in the $\Kill \ra 0$ limit as:
    \begin{eqn}  \label{eq:obliqueness-nuclear-limit}
        \lim_{\Kill \ra 0} \On^\Kill &= \TimeScale \Tr\left[K_{\I,\I} \Diag\lrp{\tfrac{\Ki \hi}{\hi}}\right] 
        +\TimeScale \hi^\t \Ki (K^2)_{\I,\I} \Ki \hi
        -  \Tr[(K^2)_{\I,\I} \Ki] 
    \end{eqn}
    and $\Os^\Kill$ converges as
    \begin{eqn} \label{eq:obliqueness-spectral-limit}
        \lim_{\Kill \ra 0} \Os^\Kill &= \rho\lrp{\TimeScale \lrp{ K_{\I,\I} \Diag\lrp{\tfrac{\Ki \hi}{\hi}} + (K^2)_{\I,\I} \Ki \hi \hi^\t \Ki } - (K^2)_{\I,\I} \Ki},
    \end{eqn}
    where $\TimeScale = 1 / \hi^\t \Ki \hi$ as in \Cref{eq:omega} and $\rho(\, \cdot \, )$ is the spectral radius.
\end{proposition}
\begin{proof}
Define the following (asymmetric) obliqueness matrix:
\begin{eqn}
    \ObAsym_\Kill &\Eq \left[ \KA_{\I,\I} \Diag \lrp{\tfrac{\pr}{\pi_{\I}}} \KA_{\I,\I} - (\Ka^2)_{\I,\I} \right] \KA_{\I,\I}^\Mo
    \label{eq:obliqueness-asym}
\end{eqn}
Since $\ObAsym_\Kill$ is a similarity transform of $\Ob_\Kill$, it follows that
% The nuclear norm is easier to target as cyclic permutation simplifies its trace definition.
 $
    \On^\Kill 
    % &= \Tr[\KA_{\I,\I}^\Mh \KA_{\I,:} \lrp{\Id_{:,\I} \Diag \lrp{\tfrac{\pr}{\pi_{\I}}} \Id_{\I,:} - \Id} \KA_{:,\I} \KA_{\I,\I}^\Mh] \\
    = \Tr[\ObAsym_\Kill]
$ and $\Os^\Kill = \rho(\ObAsym_\Kill)$.
Therefore we proceed to computing $\ObAsym \Eq \lim_{\Kill \ra 0} \ObAsym_\Kill$.
If this limit exists, then the limits of $\On^\Kill$ and $\Os^\Kill$ do as well, since the trace and spectral radius are continuous functions.

% Furthermore, since the trace and spectral radius are continuous functions, $\On = \lim_{\Kill \ra 0} \Tr[\ObAsym_\Kill]$
% \begin{eqn}
%     \lim_{\Kill \ra 0} \lrp{\KA_{\I,\I} \Diag \lrp{\tfrac{\pr}{\pi_{\I}}} \KA_{\I,\I} - (\Ka^2)_{\I,\I}} \KA_{\I,\I}^\Mo
%     \\ = \lim_{\Shift \ra 0} \lrp{(\Kb)_{\I,\I} \Diag \lrp{\tfrac{\pr}{\pi_{\I}}} (\Kb)_{\I,\I} - (\Kb^2)_{\I,\I}} (\Kb)_{\I,\I}^\Mo
% \end{eqn}
% which is shown as consequence of \red{xxx} \MF{need to use similar shift/kill lemma like before}.

% Recall that $\La \Eq L + \Kill \Id$ and $\Ka \Eq \La^\Mo$ and moreover that $K := L^+$. 

As in the proof of \Cref{th:markov-norm-limits}, it is useful to define a matrix $\tilde{K}_\gamma := K_\gamma - \gamma^{-1} hh^\t$, suppress the $\gamma$-dependence from the notation $\tilde{K} = \tilde{K}_\gamma$, and view $K_\gamma = \tilde{K} + \gamma^{-1} hh^\t$ as a rank-one update. 
Then using the Sherman-Morrison formula, the right-hand side of \Cref{eq:obliqueness-asym} may be simplified to show that:
\begin{eqn}
    \ObAsym \Eq \lim_{\Kill \ra 0} \ObAsym_\Kill &= \TimeScale \lrp{ K_{\I,\I} \Diag\lrp{\tfrac{\Ki \hi}{\hi}} + (K^2)_{\I,\I} \Ki \hi \hi^\t \Ki } - (K^2)_{\I,\I} \Ki.
    \label{eq:obliqueness-asym-limit}
\end{eqn}
    % \red{Tedious use of Sherman-Morrison-Woodbury formula formula and rearrangements give the first line}.
    % Take limit of this:
% \begin{eqn}
%     \ObAsym^\Kill(L) &\Eq K_{\I,:} \lrp{\Id_{:,\I} \Diag \lrp{\frac{\pr}{\pi_{\I}}} \Id_{\I,:} - \Id} K_{:,\I} K_{\I,\I}^\Mo \text{ where } K = \La^\Mo
% \end{eqn}
Taking the spectral radius of $\ObAsym$ yields \Cref{eq:obliqueness-spectral-limit} immediately, while taking its trace and rearranging yields \cref{eq:obliqueness-nuclear-limit}.
\end{proof}

