\ThObliquenessFromHitting*
\begin{Proof}{th:obliqueness-from-hitting}
    First, let $S \Eq \DiagI(h) K \DiagI(h)$. 
    Then $S$ is symmetric with $S \pi = \Zero$.
    From Lemma~2.12 of \cite{Aldous1995-reversible}, $H_{j,i} = S_{i,i} - S_{j,i}$ for all $i,j$, so we may write:
    \begin{eqn}\label{eq:hitting-time}
        H = \One \Diag(S)^\t - S.
    \end{eqn}
    Then we compute the diagonal entries of $H_{:,\I}^\t \Diag(\pi) \Cu$.
    For $i \in \I$,
    \begin{eqn}
        H_{:,i}^\t \Diag(\pi) \Cu_{:,i} &= (S_{i,i} \One - S_{:,i})^\t \Diag(\pi) \DiagI(h) \lrp{\frac{(h - K_{:,\I} \Ki \hi^\t) \hi^\t}{\hi^\t \Ki \hi} + K_{:,\I}} (\Ki)_{:,i} \, h_i  \\
        &= (K_{i,i} h_i^\Mo h^\t - K_{i,:}) \lrp{\frac{(h - K_{:,\I} \Ki \hi^\t) \hi^\t}{\hi^\t \Ki \hi} + K_{:,\I}} (\Ki)_{:,i} \\
        &=  \lrp{K_{i,i} h_i^\Mo + (K^2)_{i,\I} \Ki \hi} \frac{(\Ki)_{i,:} \hi}{\hi^\t \Ki \hi} - (K^2)_{i,\I} (\Ki)_{:,i} \\
        &= \omega \lrp{K_{i,i} (\Ki)_{i,:} \hi h_i^\Mo  + (K^2)_{i,\I} \Ki \hi \hi^\t (\Ki)_{:,i}}   - (K^2)_{i,\I} (\Ki)_{:,i}
    \end{eqn}
    by use of the symmetry of $K$, the fact that $K h = \Zero$, and the definition \Cref{eq:omega} of $\TimeScale$.
    Summing and comparing to \Cref{th:recurrent-obliqueness} yields the desired result.
\end{Proof}


