\section{Matrix perturbation lemma}\label{s:matpert}

In this section we prove an elementary lemma pertaining to the perturbation of a block of a matrix with a shift by a large multiple of the identity. Although the result is intuitive, we are not aware of a standard reference.

\begin{lemma}[Exponential of block perturbation] \label{lem:expalpha}
For $\alpha\geq0$, consider the matrix 
\[
A_{\alpha}=\left(\begin{array}{cc}
A_{11} & A_{12}\\
A_{21} & A_{22}+\alpha\Id
\end{array}\right).
\]
 Then 
\[
\lim_{\alpha\ra\infty}e^{-A_{\alpha}}=\left(\begin{array}{cc}
e^{-A_{11}} & 0\\
0 & 0
\end{array}\right).
\]

\end{lemma}

\begin{proof}
Let $z_{0}=\left(\begin{array}{c}
x_{0}\\
y_{0}
\end{array}\right)$ be arbitrary. It suffices to show that 
\[
\lim_{\alpha\ra\infty}e^{-A_{\alpha}}z_{0}=\left(\begin{array}{c}
e^{-A_{11}}x_{0}\\
0
\end{array}\right).
\]
 We can express 
\[
e^{-A_{\alpha}}z_{0}=z_{\alpha}(1),
\]
 where $z_{\alpha}(t)=\left(\begin{array}{c}
x_{\alpha}(t)\\
y_{\alpha}(t)
\end{array}\right)$ is the solution of the ODE: 
\[
z_{\alpha}'(t)=-A_{\alpha}z_{\alpha}(t),\qquad z(0)=z_{0}.
\]

First we want to show an \emph{a priori} bound of the form $\Vert z_{\alpha}(t)\Vert\leq C$
that is uniform in $\alpha\geq0$, $t\in[0,1]$. (In the following
discussion, for simplicity, we use $\Vert\,\cdot\,\Vert$ to denote
the vector 2-norm and the induced spectral norm.) To achieve this
\emph{a priori} bound, we write ODEs for $\Vert x_{\alpha}(t)\Vert^{2}$
and $\Vert y_{\alpha}(t)\Vert^{2}$ and bound their right-hand sides:
\begin{align*}
\frac{d}{dt}\Vert x_{\alpha}(t)\Vert^{2} & \ =\ -2x_{\alpha}(t)\cdot[A_{11}x_{\alpha}(t)+A_{12}y_{\alpha}(t)]\\
 & \ \leq\ 2\Vert A_{11}\Vert\,\Vert x_{\alpha}(t)\Vert^{2}+2\Vert A_{12}\Vert\,\Vert x_{\alpha}(t)\Vert\,\Vert y_{\alpha}(t)\Vert\\
 & \ \leq\ 2\Vert A_{11}\Vert\,\Vert x_{\alpha}(t)\Vert^{2}+\Vert A_{12}\Vert\,(\Vert x_{\alpha}(t)\Vert^{2}+\Vert y_{\alpha}(t)\Vert^{2})\\
 & \ =\ 2\Vert A_{11}\Vert\,\Vert x_{\alpha}(t)\Vert^{2}+\Vert A_{12}\Vert\,\Vert z_{\alpha}(t)\Vert^{2},
\end{align*}
 and similarly 
\begin{align*}
\frac{d}{dt}\Vert y_{\alpha}(t)\Vert^{2} & \ =\ -2\alpha\Vert y_{\alpha}(t)\Vert^{2}-2y_{\alpha}(t)\cdot[A_{21}x_{\alpha}(t)+A_{22}y_{\alpha}(t)]\\
 & \ \leq\ -2y_{\alpha}(t)\cdot[A_{21}x_{\alpha}(t)+A_{22}y_{\alpha}(t)]\\
 & \ \leq\ 2\Vert A_{22}\Vert\,\Vert y_{\alpha}(t)\Vert^{2}+\Vert A_{21}\Vert\,\Vert z_{\alpha}(t)\Vert^{2}.
\end{align*}
 Summing the bounds yields 
\[
\frac{d}{dt}\Vert z_{\alpha}(t)\Vert^{2}\leq C'\,\Vert z_{\alpha}(t)\Vert^{2}
\]
 for a suitably defined constant $C'>0$, independent of $\alpha,t$.
Then Gr\"{o}nwall's inequality yields the \emph{a priori} bound
$\Vert z_{\alpha}(t)\Vert\leq C$ for suitable $C>0$, as we aimed
to show.

Now examine the dynamics $y_{\alpha}(t)$ individually, 
\[
y_{\alpha}'(t)=-\alpha y_{\alpha}(t)+\underbrace{\left[-A_{21}x_{\alpha}(t)-A_{22}y_{\alpha}(t)\right]}_{=:\,b_{\alpha}(t)}.
\]
 We can view the bracketed term as an inhomogeneous contribution in
Duhamel's principle to deduce that 
\[
y_{\alpha}(t)=e^{-\alpha t}y_{0}+\int_{0}^{t}e^{-\alpha(t-s)}b_{\alpha}(s)\,\odif s.
\]
 Then taking norms we see that 
\[
\Vert y_{\alpha}(t)\Vert\leq e^{-\alpha t}\Vert y_{0}\Vert+C''\int_{0}^{t}e^{-\alpha(t-s)}\,\odif s
\]
for suitable $C''$, via our uniform bound on $\Vert z_{\alpha}(t)\Vert$,
which implies a uniform bound on $\Vert b_{\alpha}(t)\Vert$. We can
compute $\int_{0}^{t}e^{-\alpha(t-s)}\,\odif s=\alpha^{-1}[1-e^{-\alpha t}]\leq\alpha^{-1}$
to deduce that 
\begin{equation}
\Vert y_{\alpha}(t)\Vert\leq e^{-\alpha t}\Vert y_{0}\Vert+C''\alpha^{-1}\leq C'''(e^{-\alpha t}+\alpha^{-1})\label{eq:ybound}
\end{equation}
 for suitable $C'''$.

Then examine the dynamics for $x_{\alpha}(t)$ individually: 
\[
x_{\alpha}'(t)=-A_{11}x_{\alpha}(t)-A_{12}y_{\alpha}(t),
\]
 and again viewing the second term as an inhomogeneous contribution
using Duhamel's principle we deduce that 
\[
x_{\alpha}(t)=e^{-A_{11}t}x_{0}-\int_{0}^{t}e^{-(t-s)A_{11}}A_{12}y_{\alpha}(s)\,\odif s.
\]
 Now $\Vert e^{-\tau A_{11}}A_{12}\Vert$ is uniformly bounded over
$\tau\in[0,1]$, and recalling (\ref{eq:ybound}) it follows that
there exists $C''''>0$ such that 
\begin{align*}
\Vert x_{\alpha}(1)-e^{-A_{11}}x_{0}\Vert & \leq C''''\int_{0}^{1}(e^{-\alpha s}+\alpha^{-1})\,\odif s=O(\alpha^{-1}).
\end{align*}
 Hence $\lim_{\alpha\ra\infty}x_{\alpha}(1)=e^{-A_{11}}x_{0}$. Moreover,
(\ref{eq:ybound}) implies that $\lim_{\alpha\ra\infty}y_{\alpha}(1)=0$.
In other words, $\lim_{\alpha\ra\infty}z_{\alpha}(1)=\left(\begin{array}{c}
e^{-A_{11}}x_{0}\\
0
\end{array}\right)$, as was to be shown.
\end{proof}




