Then with a view toward proving Theorem \hyperlink{Theorem4B}{4B}, we prove the following lemma: 
\begin{lemma}\label{lem:dppstuff}
For any positive integer $k$, there exists a subset $\I$ of size $k$ such that
\begin{eqn}
    {\ve}_{*} (\I) \leq \left( 1 + \frac{r+1}{k-r} \right) (\Tr[K]- \Tr^{(k)}[K]).
\end{eqn}
\end{lemma}
\begin{proof}
   Consider performing $k$-DPP sampling on $\tilde{K}_\gamma := (L+\gamma hh^{\top})^{-1}=K+\gamma^{-1}hh^{\top}$. 
    For symmetric positive semidefinite matrices $M$, $\DPPfunction_k(M)$ is Schur concave in the eigenvalues of $M$ (see, e.g., \cite{Schur1923-uber}, Theorem~10 of \cite{Fornace2024-column}).
    Therefore replacing any subset of the eigenvalues of $\tilde{K}_\gamma$ with repeated copies of its average value can only increase the value of  $\DPPfunction_k$.
    It follows that $\DPPfunction_k(\tilde{K}_\gamma) \leq \DPPfunction_k(\Diag(\hat{\lambda}_\gamma))$, where 
    \begin{eqn}
        \hat{\lambda}_\gamma \Eq 
        [\hat{\lambda}, \gamma^{-1}] :=
        \Bigg[ \underbrace{\frac{t}{r}, \dots, \frac{t}{r}}_{r \text{ times}},  \, 
        \underbrace{\frac{T-t}{n-r-1}, \dots, \frac{T-t}{n-r-1}}_{n-r-1 \text{ times}}, \, \gamma^\Mo \Bigg]
    \end{eqn}
    with $t := \Tr^{(r)} [K]$  and $T:= \Tr[K]$.

    Now by \Cref{eq:dppclassical}, we know that 
    \[
    \mathcal{E}_{k}^{\mathrm{DPP}}(\mathrm{diag}(\hat{\lambda}_{\gamma}))=(k+1)\frac{e_{k+1}(\hat{\lambda}\cup\{\gamma^{-1}\})}{e_{k}(\hat{\lambda}\cup\{\gamma^{-1}\})},
    \]
     and in the small $\gamma$ limit, only products including $\gamma^{-1}$
    dominate the symmetric polynomials, so 
    \begin{align*}
    \mathcal{E}_{k}^{\mathrm{DPP}}(\mathrm{diag}(\hat{\lambda}_{\gamma})) & =(k+1)\frac{e_{k}(\hat{\lambda})}{e_{k-1}(\hat{\lambda})} + O(\gamma) \\
     & =\frac{k+1}{k}\mathcal{E}_{k-1}^{\mathrm{DPP}}(\mathrm{diag}(\hat{\lambda})) + O(\gamma) \\
     & \leq\frac{k+1}{k}\left(1 + \frac{r}{k-r}\right)(T-t) + O(\gamma) \\ 
     & = \left( 1 + \frac{r+1}{k-r} \right) (T-t) + O(\gamma).
    \end{align*}
    where in the second equation we have used \Cref{eq:dppclassical}, in the third line we have used \Cref{eq:dpp-nystrom}, and the last line follows by elementary manipulations. In summary, we have established that 
    \begin{eqn}\label{eq:dppwah}
        \DPPfunction_k(\tilde{K}_\gamma) \leq   \left( 1 + \frac{r+1}{k-r} \right) (T-t) + O(\gamma).
    \end{eqn}

    Now the proof technique of \Cref{th:markov-norm-limits} establishes that in the limit of $\gamma \ra 0$, the quantity $\ve_{*}^{\gamma}(\I)$
(cf. \Cref{def:markov-epsilon}) agrees with 
\[
\tilde{\ve}_{*}^{\gamma}(\I):=\Tr\left[\tilde{K}_{\gamma}-(\tilde{K}_{\gamma})_{:,\I}(\tilde{K}_{\gamma})_{\I,\I}^{-1}(\tilde{K}_{\gamma})_{\I,:}\right],
\]
 as well as the limit $\ve_{*}(\I)$, both up to error $O(\gamma)$. 

    For every $\gamma > 0$, there must exist a $k$-subset $\I^\gamma$ that performs at least as well as the DPP expectation, i.e., satisfying $ \tilde{\ve}_{*}^{\gamma}(\I^\gamma) \leq \DPPfunction_k(\tilde{K}_\gamma)$. But also $\tilde{\ve}_{*}^{\gamma}(\I^\gamma) = {\ve}_{*}(\I^\gamma) + O(\gamma)$, so it follows from \Cref{eq:dppwah} that 
    \begin{eqn}
        {\ve}_{*}(\I^\gamma) \leq \left( 1 + \frac{r+1}{k-r} \right) (T-t) + O(\gamma).
    \end{eqn}
    Since there are only finitely many subsets, it follows that there exists some $k$-subset $\I$ such that $\tilde{\ve}_{*} (\I) \leq \left( 1 + \frac{r+1}{k-r} \right) (T-t)$, which completes the proof.
\end{proof}


Now we can restate and prove Theorem \hyperlink{Theorem4B}{4B}:
\ThSpectralCSSP*
\begin{Proof}{th:spectral-cssp}
The proof follows directly from Theorem \hyperlink{Theorem4A}{4A}, together with \Cref{lem:dppstuff}.
\end{Proof}
\noindent While the choice of $s$ in Theorem \hyperlink{Theorem4B}{4B}  may be optimized to give an asymptotic $(r, \epsilon)$ bound in the sense of \cite{Chen2022-randomly,Derezinski2021-determinantal} for nuclear maximization (following the strategy in \cite{Fornace2024-column}), we omit such derivations for simplicity's sake.


