}
  \label{fig:illu}
 \end{figure*}
Figure 4 illustrates a segment of the algorithm's operational methodology. The initial phase presents the overview. During the second phase, the data is transferred to auxiliary memory. Stage 3 is the phase in which sorting occurs. From Stage 4 forward, the operation of the jumpinsert function is illustrated, initiating the return of sorted data to the primary or preceding memory (the memory in each segment of the division is primary for the memory below it and auxiliary for the memory above it). Initially, the value of the largest auxiliary memory number is compared to that of the largest main memory number to return the data. If the data in main memory was larger, a jump is executed; otherwise, an insertion operation is performed. This graphic illustrates two data points with a value of 7, demonstrating the stability of the persiansort algorithm.\\
{\color{zaffre}
\begin{lstlisting}
10:  int auxiliary_size(int n, int wp){
11:      int m=n/wp;
12:      if(m==0) return 2;
13:       else return 1+m+auxiliary_size(m , wp);
      }

14:  void reverse (int ar[],int s,int e){
15:         while(s<e) {
16:              swap(ar[s],ar[e]);
17:              s++;e--;
            }
     }
18:   void warping(int ar[],int aux[],int start,int end,int aux_size,int wp){
19:          if(start>=end) return;
20:          int max_jump=((end-start+1)/wp)+1;
21:          int low,high,temp,j,i=start;
22:          while (ar[i+1]<ar[i] && i<end) i++;
23:          if(i>start) reverse(ar,start,i);
24:          while (i<end){
25:              while (ar[i+1]>=ar[i] && i<end) i++;
26:              if(i==end) return;
27:              if((i+max_jump)>end) max_jump=end-i;
28:              if((end-start+1)>aux_size)
                        {
29:                       for(j=1;j<max_jump+1;j++)
30:                             aux[j]=aux[i+j];
31:                       if(max_jump>1) warping(aux,aux,1,max_jump,aux_size,wp);
32:                       jumpinsert(ar,start,i,aux,1,max_jump);
33:                       i=i+max_jump;
                        }
34:               else
                        {
35:                        temp=end-i,low=end+1,high=end+max_jump;
36:                        for(j=low;j<high+1;j++)
37:                              aux[j]=aux[j-temp];
38:                        if(max_jump>1) warping(aux,aux,low,high,aux_size,wp);
39:                        jumpinsert(aux,start,i,aux,low,high);
40:                        i=i+max_jump;
                        }
             }
      }
41:  void persiansort(int ar[],int start,int end,int wp){
42:         int aux_size=auxiliary_size(end-start+1,wp);
43:         int aux[aux_size]{};
44:         if((end-start+1)<wp) aux_size=1;
45:         warping(ar,aux,start,end,aux_size,wp);
      }
\end{lstlisting}
