\vskip -0.1in
\begin{center}
\includegraphics[width=1\columnwidth]{figures/QT_General_Concept.png}\vskip -0.1in
\caption{{\bfseries Concept of Quantum-Train.}}
\label{fig:QT_Concept}
\end{center}
\vskip -0.2in
\end{figure}
