    assert Default.fibfib(2) == Default.fibfib_func(2), "expectation violation"
    assert Default.fibfib(1) == Default.fibfib_func(1), "expectation violation"
    assert Default.fibfib(0) == Default.fibfib_func(0), "expectation violation"

