\begin{lemmaE}[][all end]
    \label{cutRopeCase}
    The following rule is derivable from the proof calculus:
    \def\fCenter{\ \vdash\ }
    \begin{prooftree}
        \Axiom $\Gamma \fCenter \angel{h_A'=-w_A, h_D' = 0}{P}{Q}, \Delta$
        \UnaryInf $\Gamma \fCenter \angel{h_A' = min(0, -w_A), h_D'=max(0,0)}{P}{Q}, \Delta$
    \end{prooftree}
    where $\Gamma \equiv h_A = h, h>0, h_D = 0, w_A >0, w_D>0, r=1, x>0$, $P \equiv h_A = 0 \land h\cdot w_A < x$, $Q \equiv h_D = h$ and $\Delta \equiv \angel{h'_A = min(0, -w_A + r \cdot w_D), h'_D = max(0, r(w_A-w_D))}{P}{Q}$.
\end{lemmaE}
\begin{proofE}
    For easier derivation of this proof rule, two auxiliary lemmas are proven first:
    \begin{lemma}
        \label{minRule}
        The following proof rule is derivable from the proof calculus:
        \begin{prooftree}
            \AxiomC{$\Gamma, t <0 \vdash \angel{x:= t}{P}{Q}, \Delta$}
            \AxiomC{$\Gamma, t\geq 0 \vdash \angel{x:=0}{P}{Q}, \Delta$}
            \BinaryInfC{$\Gamma \vdash \angel{?t<0; x:= t \;\cup\; ? t\geq = ; x:=0}{P}{Q}, \Delta$}
        \end{prooftree}
    \end{lemma}
    \begin{proof}
        This rule can be syntactically derived by first using the rules $\chA$, $\seqA$ and $\tA$ to split the original formula into smaller parts. Then, the tautology $t<0 \lor t\geq 0$ is cut in and used to make a case distinction. For each case, the formula that does not match the case is weakened away, e.g. for the case $t>0$, $t<0 \land \angel{x:=t}{P}{Q}$ is kept. Then $\land R$ is used to split this formula. $t<0$ can be directly proven by identity while $\angel{x:=t}{P}{Q}$ is the precondition of the proof rule. The proof for the second case $t\geq 0$ is similar to the first case.
        \begin{figure}[H]
            \centering
            \resizebox{\textwidth}{!}{
                \def\fCenter{\ \vdash\ }
                \begin{tabular}{@{}c@{}}
                    \AxiomC{$*$}
                    \LeftLabel{id}
                    \UnaryInf $\Gamma, t\geq 0 \fCenter t\geq 0, \Delta$
                    \Axiom $\Gamma, t\geq 0 \fCenter \angel{x:=0}{P}{Q}, \Delta$
                    \LeftLabel{$\land R$}
                    \BinaryInf $\circled{1} \ \Gamma, t \geq 0 \fCenter t\geq 0 \land \angel{x:=0}{P}{Q}, \Delta$
                    \DisplayProof\\[1.5cm]
                    \AxiomC{$*$}
                    \LeftLabel{r.A.}
                    \UnaryInf $\Gamma \fCenter t<0 \lor t\geq 0$
                    \AxiomC{$*$}
                    \LeftLabel{id}
                    \UnaryInf $\Gamma, t<0 \fCenter t<0, \Delta$
                    \Axiom $\Gamma, t<0 \fCenter \angel{x:=t}{P}{Q}, \Delta$
                    \LeftLabel{$\land R$}
                    \BinaryInf $\Gamma, t < 0 \fCenter t<0 \land \angel{x:=t}{P}{Q}, \Delta$
                    \AxiomC{\circled{1}}
                    \LeftLabel{$\lor L$, wR}
                    \BinaryInf $\Gamma, t< 0 \lor t\geq 0 \fCenter t<0 \land \angel{x:=t}{P}{Q}, t\geq 0 \land \angel{x:=0}{P}{Q}, \Delta$
                    \LeftLabel{cut, wR}
                    \BinaryInf $\Gamma \fCenter t<0 \land \angel{x:=t}{P}{Q}, t\geq 0 \land \angel{x:=0}{P}{Q}, \Delta$
                    \LeftLabel{$\tA$}
                    \UnaryInf $\Gamma \fCenter \angel{?t<0}{\angel{x:=t}{P}{Q}}{\demon{x:=t}{P}{Q}}, \angel{t\geq 0}{\angel{x:=0}{P}{Q}}{\demon{x:=0}{P}{Q}}, \Delta$
                    \LeftLabel{$\seqA$}
                    \UnaryInf $\Gamma \fCenter \angel{?t<0; x:= t}{P}{Q}, \angel{?t\geq 0; x:=0}{P}{Q}, \Delta$
                    \LeftLabel{$\chA$, $\lor R$}
                    \UnaryInf $\Gamma \fCenter \angel{?t<0; x:= t \;\cup\; ? t\geq 0 ; x:=0}{P}{Q}, \Delta$ 
                    \DisplayProof
                \end{tabular}
            }
        \end{figure}
        \qed
    \end{proof}
    \begin{lemma}
        \label{maxRule}
        The following proof rule is derivable from the proof calculus:
        \begin{prooftree}
        \AxiomC{$\Gamma, t >0 \vdash \angel{x:= t}{P}{Q}, \Delta$}
        \AxiomC{$\Gamma, t\leq 0 \vdash \angel{x:=0}{P}{Q}, \Delta$}
        \BinaryInfC{$\Gamma \vdash \angel{?t>0; x:= t \;\cup\; ? t\leq = ; x:=0}{P}{Q}, \Delta$}
        \end{prooftree}
    \end{lemma}
    \begin{proof}
        This proof works similar to the proof of Lemma \ref{minRule}. Most of the steps are the same but instead of cutting in $t<0 \lor t\geq 0$, $t>0 \lor t\leq 0$ is cut in to match the different cases.
        \begin{figure}[H]
            \centering
            \resizebox{\textwidth}{!}{
                \def\fCenter{\ \vdash\ }
                \begin{tabular}{@{}c@{}}
                    \AxiomC{$*$}
                    \LeftLabel{id}
                    \UnaryInf $\Gamma, t\leq 0 \fCenter t\leq 0, \Delta$
                    \Axiom $\Gamma, t\leq 0 \fCenter \angel{x:=0}{P}{Q}, \Delta$
                    \LeftLabel{$\land R$}
                    \BinaryInf $\circled{1} \ \Gamma, t \leq 0 \fCenter t\leq 0 \land \angel{x:=0}{P}{Q}, \Delta$
                    \DisplayProof\\[1.5cm]
                    \AxiomC{$*$}
                    \LeftLabel{r.A.}
                    \UnaryInf $\Gamma \fCenter t>0 \lor t\leq 0$
                    \AxiomC{$*$}
                    \LeftLabel{id}
                    \UnaryInf $\Gamma, t>0 \fCenter t>0, \Delta$
                    \Axiom $\Gamma, t>0 \fCenter \angel{x:=t}{P}{Q}, \Delta$
                    \LeftLabel{$\land R$}
                    \BinaryInf $\Gamma, t > 0 \fCenter t>0 \land \angel{x:=t}{P}{Q}, \Delta$
                    \AxiomC{\circled{1}}
                    \LeftLabel{$\lor L$, wR}
                    \BinaryInf $\Gamma, t> 0 \lor t\leq 0 \fCenter t>0 \land \angel{x:=t}{P}{Q}, t\leq 0 \land \angel{x:=0}{P}{Q}, \Delta$
                    \LeftLabel{cut, wR}
                    \BinaryInf $\Gamma \fCenter t>0 \land \angel{x:=t}{P}{Q}, t\leq 0 \land \angel{x:=0}{P}{Q}, \Delta$
                    \LeftLabel{$\tA$}
                    \UnaryInf $\Gamma \fCenter \angel{?t>0}{\angel{x:=t}{P}{Q}}{\demon{x:=t}{P}{Q}}, \angel{t\leq 0}{\angel{x:=0}{P}{Q}}{\demon{x:=0}{P}{Q}}, \Delta$
                    \LeftLabel{$\seqA$}
                    \UnaryInf $\Gamma \fCenter \angel{?t>0; x:= t}{P}{Q}, \angel{?t\leq 0; x:=0}{P}{Q}, \Delta$
                    \LeftLabel{$\chA$, $\lor R$}
                    \UnaryInf $\Gamma \fCenter \angel{?t>0; x:= t \;\cup\; ? t\leq 0 ; x:=0}{P}{Q}, \Delta$ 
                    \DisplayProof
                \end{tabular}
            }
        \end{figure}
        \qed
    \end{proof}
    For the proof of L. \ref{cutRopeCase}, the definition of the min- and max-operator used in the continuous game is first expanded. The resulting sequence is split using $\seqA$. After that, L. \ref{minRule} can be used first and then L. \ref{maxRule}. The branches with the additional preconditions $-w_A \geq 0$ and $0>0$ that result from using the lemmas, can immediately be closed because $-w_A \geq 0$ contradicts the assumption $w_A > 0$ in $\Gamma$ and $0>0$ is false. The other branches are used to determine the values of the ODEs and result in the precondition for the rule that should be proven.
