                \AxiomC{\circled{2}}
                \LeftLabel{L. \ref{maxRule}}
                \BinaryInfC{$\Gamma \fCenter \angel{?0>0; v_D := 0 \;\cup\; ?0\leq 0; v_D := 0}{\angel{h_A' = -w_A, h_D' = v_D}{P}{Q}}{\demon{h_A' = -w_A, h_D' = v_D}{P}{Q}}, \Delta$}
                \LeftLabel{$\seqA$}
